# rule_id=exp_ea2d85fa3ff2bce1 | domain=Electromagnetism | topic=Electromagnetism / Capacitance and Dielectrics
def check_exp_ea2d85fa3ff2bce1_b5e1091dcda1(sample: dict) -> dict:

    text = sample.get('prediction', '') + ' ' + sample.get('answer', '')
    # 寻找 N+1 片定片和 N 片动片的描述
    pattern_n = re.compile(r'(\d+)\s*片定片.*(\d+)\s*片动片|(\d+)\s*片动片.*(\d+)\s*片定片')
    match = pattern_n.search(text)
    if not match:
        return {"result": "inconclusive", "message": "未识别到定片与动片的具体数量描述", "evidence": ""}

    nums = [int(x) for x in match.groups() if x is not None]
    n_fixed = max(nums)
    n_moving = min(nums)

    # 验证是否符合 N+1 和 N 的关系
    if n_fixed != n_moving + 1:
        return {"result": "inconclusive", "message": "片数不符合N+1与N的交错排列特征", "evidence": match.group(0)}

    expected_gaps = 2 * n_moving

    # 检查预测中是否错误地使用了 N 或 N+1 作为间隙数/电容倍数
    # 查找类似 C = N*C0 或 C = (N+1)*C0 的表达
    error_patterns = [
        str(n_moving) + r'\s*C_?0',
        str(n_fixed) + r'\s*C_?0',
        r'电容为\s*' + str(n_moving) + r'\s*倍',
        r'电容为\s*' + str(n_fixed) + r'\s*倍'
    ]

    for ep in error_patterns:
        if re.search(ep, text):
            return {
                "result": "fail",
                "message": "错误地将间隙数识别为 N 或 N+1，应为 2N",
                "evidence": match.group(0) + " | " + ep
            }

    # 检查是否正确识别了 2N
    correct_pattern = str(expected_gaps) + r'\s*C_?0|' + str(expected_gaps) + r'\s*个间隙'
    if re.search(correct_pattern, text):
        return {"result": "pass", "message": "正确识别了 2N 个有效电场区域", "evidence": correct_pattern}

    return {"result": "inconclusive", "message": "无法确定计算逻辑是否正确", "evidence": ""}

