# rule_id=exp_6f33b77c2cf8aef0 | domain=Electromagnetism | topic=Electromagnetism / DC Circuits and Kirchhoff's Laws
def check_exp_6f33b77c2cf8aef0_30c80e1532fe(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    # 触发条件：题目描述电阻R减小但相关电压V增大
    # 匹配 R 减小 (变小, 调小, 减小)
    r_decrease = re.search(r'[Rr]\s*(减小|变小|调小|阻值变小)', question)
    # 匹配 V 增大 (变大, 调大, 增大)
    v_increase = re.search(r'[VvUu]\s*(增大|变大|调大|示数变大)', question)

    if not (r_decrease and v_increase):
        return {"result": "inconclusive", "message": "未检测到电阻减小且电压增大的触发场景", "evidence": ""}

    # 检查逻辑：模型推导中 V 随 R 的变化趋势
    # 如果预测中出现 V 随 R 减小而减小 (正相关)，则与题目背景矛盾
    # 匹配逻辑：R减小 -> V减小 或 R增大 -> V增大
    positive_correlation = re.search(r'([Rr].*减小.*[VvUu].*减小)|([Rr].*变小.*[VvUu].*变小)|([Rr].*增大.*[VvUu].*增大)', prediction)

    if positive_correlation:
        return {
            "result": "fail",
            "message": "电路趋势不一致：模型推导V随R正向变化，与题目背景矛盾",
            "evidence": positive_correlation.group(0)
        }

    # 如果预测中明确提到 V 随 R 减小而增大 (负相关)，则通过
    negative_correlation = re.search(r'([Rr].*减小.*[VvUu].*增大)|([Rr].*变小.*[VvUu].*变大)', prediction)
    if negative_correlation:
        return {
            "result": "pass",
            "message": "电路趋势一致：模型正确识别了V随R减小而增大的逻辑",
            "evidence": negative_correlation.group(0)
        }

    return {"result": "inconclusive", "message": "无法从预测文本中判定V对R的导数符号", "evidence": ""}

