# rule_id=exp_9ef7b62444232322 | domain=Electromagnetism | topic=Electromagnetism / DC Circuits and Kirchhoff's Laws
def check_exp_9ef7b62444232322_05efdb0158be(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 检查是否包含比例系数形式 (如 1/n, 0.5Is, k*Us)
    ratio_pattern = re.compile(r'(\d+/\d+|\d+\.\d+|k)\s*[\*\s]?(I_s|U_s|Is|Us|I|U)')
    has_ratio = bool(ratio_pattern.search(prediction))

    if not has_ratio:
        return {"result": "inconclusive", "message": "未检测到比例系数表达形式", "evidence": ""}

    # 检查是否包含定量计算的关键词（基尔霍夫、节点电压、矩阵、方程组、KCL/KVL）
    calc_keywords = ['基尔霍夫', 'Kirchhoff', 'KCL', 'KVL', '节点电压', '回路电流', '方程组', '矩阵', '联立']
    has_calc_method = any(kw in prediction for kw in calc_keywords)

    # 检查是否仅包含定性描述（对称、显然、同理）
    qualitative_keywords = ['对称', '显然', '同理', '由图可知']
    only_qualitative = any(kw in prediction for kw in qualitative_keywords) and not has_calc_method

    if has_ratio and only_qualitative:
        evidence = next((kw for kw in qualitative_keywords if kw in prediction), "定性描述")
        return {
            "result": "fail",
            "message": "检测到比例系数但缺乏定量拓扑计算过程（如基尔霍夫方程）",
            "evidence": evidence
        }

    if has_ratio and has_calc_method:
        return {"result": "pass", "message": "包含比例系数及相应的定量计算逻辑", "evidence": ""}

    return {"result": "inconclusive", "message": "无法确定计算逻辑的严密性", "evidence": ""}

