# rule_id=exp_428f13c259c43de3 | domain=Electromagnetism | topic=Electromagnetism / Electric Dipoles and Multipole Expansion
def check_exp_428f13c259c43de3_a0946d887fa5(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 检查分子是否包含 e^2/m 的特征
    numerator_pattern = r'e\^2\s*/\s*m'
    # 检查分母是否包含受迫振动共振形式: sqrt((w0^2-w^2)^2 + (gamma*w)^2)
    # 匹配 w0^2 - w^2 的平方项
    term1_pattern = r'\(w0\^2\s*-\s*w\^2\)\^2'
    # 匹配 (gamma*w)^2 项
    term2_pattern = r'\(gamma\s*\*?\s*w\)\^2'
    # 匹配 sqrt 结构
    denominator_pattern = r'sqrt\(.*' + term1_pattern + r'.*' + term2_pattern + r'.*\)'

    # 移除空格进行模糊匹配
    clean_pred = prediction.replace(' ', '')

    has_numerator = re.search(r'e\^?2/m', clean_pred) or re.search(r'e\*e/m', clean_pred)
    has_denominator = re.search(r'sqrt\(\(w0\^2-w\^2\)\^2\+\(gamma\*?w\)\^2\)', clean_pred)

    if has_numerator and has_denominator:
        return {
            'result': 'pass',
            'message': '极化率表达式符合受迫振动共振形式',
            'evidence': 'numerator and denominator patterns matched'
        }
    elif 'alpha' in clean_pred or 'polarizability' in prediction.lower():
        return {
            'result': 'fail',
            'message': '极化率表达式分母或分子结构不符合受迫振动物理模型',
            'evidence': prediction[:100]
        }
    else:
        return {
            'result': 'inconclusive',
            'message': '未检测到极化率相关计算表达式',
            'evidence': ''
        }

# rule_id=exp_74aed58496eb982b | domain=Electromagnetism | topic=Electromagnetism / Electric Dipoles and Multipole Expansion
def check_exp_74aed58496eb982b_73a072c8bd43(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 检查是否涉及简谐量假设解
    if not re.search(r'cos\\(.*\\+.*phi\\)', prediction) and 'x0' not in prediction:
        return {"result": "inconclusive", "message": "未检测到简谐量假设解相关表述", "evidence": ""}

    # 检查极化率计算中是否错误地保留了相位余弦项（重复投影）
    # 逻辑：如果计算极化率 alpha 或 p/E 时，公式中出现了 cos(phi) 且 phi 不是 0，则可能存在逻辑错误
    # 或者是检查幅值公式是否符合标准动力学解
    error_patterns = [
        r'alpha\\s*=\\s*.*cos\\(phi\\)',
        r'p/E\\s*=\\s*.*cos\\(phi\\)',
        r'x0\\s*=\\s*.*cos\\(phi\\)'
    ]

    for pattern in error_patterns:
        match = re.search(pattern, prediction)
        if match:
            return {
                "result": "fail",
                "message": "极化率或幅值计算中疑似重复包含了相位投影项 cos(phi)",
                "evidence": match.group(0)
            }

    # 检查是否正确使用了模长公式（暗示正确处理了相位）
    correct_patterns = [
        r'sqrt\\(\\(w0\\^2\\-w\\^2\\)\\^2',
        r'\\|.*\\|',
        r'complex'
    ]

    found_correct = any(re.search(p, prediction) for p in correct_patterns)
    if found_correct:
        return {"result": "pass", "message": "幅值计算逻辑符合标准动力学解", "evidence": ""}

    return {"result": "inconclusive", "message": "无法确定幅值与相位的关联逻辑是否正确", "evidence": ""}

# rule_id=exp_826b6c89e9792ee9 | domain=Electromagnetism | topic=Electromagnetism / Electric Dipoles and Multipole Expansion
def check_exp_826b6c89e9792ee9_1bd1f32c5d6b(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 搜索 E_r 和 E_theta 的表达式特征
    # 目标关系: E_r = 2 * k * p * cos(theta) / r^3, E_theta = k * p * sin(theta) / r^3
    # 简化检查: E_r / E_theta = 2 * cot(theta)

    # 寻找包含 E_r 和 E_theta 的等式或比例描述
    patterns = [
        r"E_r\s*=\s*2.*?cot",
        r"E_r/E_\\theta\s*=\s*2",
        r"E_r\s*:\s*E_\\theta\s*=\s*2",
        r"E_r\s*=\s*2.*?cos.*?E_\\theta\s*=\s*.*?sin"
    ]

    # 寻找错误模式：比例为1，或者三角函数反了
    error_patterns = [
        r"E_r\s*=\s*E_\\theta",
        r"E_r/E_\\theta\s*=\s*tan",
        r"E_r\s*=\s*.*?sin.*?E_\\theta\s*=\s*2.*?cos"
    ]

    found_correct = any(re.search(p, prediction, re.IGNORECASE) for p in patterns)
    found_error = any(re.search(p, prediction, re.IGNORECASE) for p in error_patterns)

    if found_correct:
        return {
            "result": "pass",
            "message": "符合电偶极子场强分量比例关系",
            "evidence": ""
        }
    elif found_error:
        return {
            "result": "fail",
            "message": "电偶极子场强分量比例错误，径向与极角分量系数比应为2且对应cos/sin",
            "evidence": ""
        }

    return {
        "result": "inconclusive",
        "message": "未在预测中找到明确的场强分量比例表达式",
        "evidence": ""
    }

# rule_id=exp_826d722ba64c620c | domain=Electromagnetism | topic=Electromagnetism / Electric Dipoles and Multipole Expansion
def check_exp_826d722ba64c620c_388d2bccbcbc(sample: dict) -> dict:

    text = (sample.get('prediction', '') + ' ' + sample.get('answer', '')).lower()

    # 检查是否涉及偶极子电势计算
    if not any(kw in text for kw in ['dipole', '偶极', 'potential', '电势', 'phi']):
        return {"result": "inconclusive", "message": "未检测到偶极子电势相关讨论", "evidence": ""}

    # 寻找偶极矩方向描述：同向(same/along/parallel) 或 反向(opposite/anti-parallel)
    is_same_dir = any(kw in text for kw in ['same direction', 'along the z', 'along the axis', 'parallel', '同向', '沿着'])
    is_opp_dir = any(kw in text for kw in ['opposite', 'anti-parallel', '反向', '相反'])

    # 寻找公式特征：+cos(theta) 或 -cos(theta)
    has_pos_cos = bool(re.search(r'\+.*cos\s*\\?theta|(?<!-)\bcos\s*\\?theta', text))
    has_neg_cos = bool(re.search(r'-\s*cos\s*\\?theta', text))

    # 逻辑校验
    if is_same_dir:
        if has_neg_cos and not has_pos_cos:
            return {"result": "fail", "message": "偶极矩与极轴同向时，电势应正比于 +cosθ", "evidence": "detected same direction but negative cosine term"}
        elif has_pos_cos:
            return {"result": "pass", "message": "符号一致性检查通过", "evidence": "same direction with positive cosine"}

    if is_opp_dir:
        if has_pos_cos and not has_neg_cos:
            return {"result": "fail", "message": "偶极矩与极轴反向时，电势应正比于 -cosθ", "evidence": "detected opposite direction but positive cosine term"}
        elif has_neg_cos:
            return {"result": "pass", "message": "符号一致性检查通过", "evidence": "opposite direction with negative cosine"}

    return {"result": "inconclusive", "message": "无法确定方向描述与公式符号的对应关系", "evidence": ""}

# rule_id=exp_04c3b03c7bc1609e | domain=Electromagnetism | topic=Electromagnetism / Electric Potential and Potential Energy
def check_exp_04c3b03c7bc1609e_64e8a0452c44(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    trigger_keywords = ['small oscillation', 'small displacement', '小位移', '微振动', '简谐运动', 'period']
    is_triggered = any(kw in question.lower() or kw in prediction.lower() for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到小位移振动相关场景", "evidence": ""}

    # 检查力 F 是否与 -x 成正比，或势能 U 是否与 x^2 成正比
    # 匹配 F = -kx 或 F ∝ -x 或 U = 1/2 kx^2 等模式
    force_linear_pattern = r'F\s*(=|∝|~)\s*-?\s*k?\s*x'
    potential_quadratic_pattern = r'U\s*(=|∝|~)\s*.*x\s*(\^|\*\*)\s*2'

    # 检查是否存在错误的非线性项，如 1/x 或 1/x^2 在平衡点附近未抵消
    error_pattern = r'1\s*/\s*x'

    has_linear_force = re.search(force_linear_pattern, prediction, re.IGNORECASE)
    has_quadratic_u = re.search(potential_quadratic_pattern, prediction, re.IGNORECASE)
    has_error_term = re.search(error_pattern, prediction, re.IGNORECASE)

    if has_linear_force or has_quadratic_u:
        if has_error_term:
            return {"result": "fail", "message": "虽然提到了线性项，但公式中包含未抵消的 1/x 项，不符合简谐运动建模", "evidence": has_error_term.group()}
        return {"result": "pass", "message": "符合简谐运动回复力线性一致性", "evidence": (has_linear_force or has_quadratic_u).group()}

    if has_error_term:
        return {"result": "fail", "message": "小位移振动模型中出现了非法的 1/x 项", "evidence": has_error_term.group()}

    return {"result": "inconclusive", "message": "无法从推导过程中确认回复力的线性关系", "evidence": ""}

