# rule_id=exp_242ad7646e8db813 | domain=Electromagnetism | topic=Electromagnetism / Electric Potential and Potential Energy
def check_exp_242ad7646e8db813_3078ea58d716(sample: dict) -> dict:

    text = (sample.get('prediction', '') + ' ' + sample.get('answer', '')).lower()

    # 检查触发词：无穷远、穿过/到达、电荷
    trigger_keywords = ['无穷远', '穿过', '到达', '电势能', '动能']
    if not any(kw in text for kw in trigger_keywords):
        return {"result": "inconclusive", "message": "未检测到临界穿越相关的物理场景", "evidence": ""}

    # 尝试提取数值 (m, v, k, Q, q, R)
    # 匹配模式示例: m=2, v=10, k=9e9, Q=1e-6, q=2e-6, R=0.5
    def get_val(pattern, content):
        match = re.search(pattern, content)
        return float(match.group(1)) if match else None

    m = get_val(r'm\s*=\s*([0-9.eE+-]+)', text)
    v = get_val(r'v\s*=\s*([0-9.eE+-]+)', text)
    k = get_val(r'k\s*=\s*([0-9.eE+-]+)', text) or 9e9
    Q = get_val(r'Q\s*=\s*([0-9.eE+-]+)', text)
    q = get_val(r'q\s*=\s*([0-9.eE+-]+)', text)
    R = get_val(r'R\s*=\s*([0-9.eE+-]+)', text)

    if all(x is not None for x in [m, v, Q, q, R]):
        ek = 0.5 * m * (v**2)
        ep = k * Q * q / R
        # 检查是否满足穿越条件：初动能 >= 电势能增量
        if ek >= ep:
            return {"result": "pass", "message": "满足能量守恒临界穿越条件", "evidence": f"Ek={ek}, Ep={ep}"}
        else:
            return {"result": "fail", "message": "初动能不足以克服电势能障碍到达目标点", "evidence": f"Ek={ek} < Ep={ep}"}

    # 如果无法提取数值，检查公式描述
    if '1/2' in text and 'v' in text and 'k' in text and 'q' in text and '/' in text:
        if '>' in text or '>=' in text or '大于' in text:
            return {"result": "pass", "message": "公式逻辑描述符合能量守恒不等式", "evidence": "检测到能量比较逻辑"}

    return {"result": "inconclusive", "message": "缺乏足够的数值或公式证据进行逻辑校验", "evidence": ""}

# rule_id=exp_284d15cf44501f99 | domain=Electromagnetism | topic=Electromagnetism / Electric Potential and Potential Energy
def check_exp_284d15cf44501f99_01269a433c4a(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 检查是否涉及球壳内部场景
    keywords = ['球壳', '内部', 'inside', 'spherical shell']
    is_relevant = any(kw in question or kw in prediction for kw in keywords)
    if not is_relevant:
        return {"result": "inconclusive", "message": "未识别到球壳内部相关场景", "evidence": ""}

    # 检查电场强度是否被错误地设为非零值
    # 寻找形如 E = kQ/r^2 且应用于内部的描述
    e_field_error = re.search(r'E\s*=\s*kQ/r\^2|电场强度不为0|E\s*!=?\s*0', prediction)
    if e_field_error:
        return {"result": "fail", "message": "错误地认为球壳内部电场强度不为0", "evidence": e_field_error.group()}

    # 检查电势一致性：内部电势应等于表面电势 V = kQ/R
    # 如果预测中提到内部电势随 r 变化（如 V = kQ/r），则判定为错
    v_r_dependence = re.search(r'V\s*=\s*kQ/r(?!\^2|\s*\*\s*R)', prediction)
    if v_r_dependence and 'r < R' in prediction:
        return {"result": "fail", "message": "球壳内部电势应为常数kQ/R，而非随r变化", "evidence": v_r_dependence.group()}

    # 检查正面表述
    correct_logic = re.search(r'E\s*=\s*0|V\s*=\s*kQ/R|电势相等|等势体', prediction)
    if correct_logic:
        return {"result": "pass", "message": "符合等壳电势一致性原则", "evidence": correct_logic.group()}

    return {"result": "inconclusive", "message": "无法确定电势或电场逻辑是否正确", "evidence": ""}

