# rule_id=exp_aae8ecf5c72c6bd1 | domain=Electromagnetism | topic=Electromagnetism / Electric Potential and Potential Energy
def check_exp_aae8ecf5c72c6bd1_d68890306c07(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    # Trigger check: n >> 1 and presence of delta/sigma
    trigger_n = 'n' in question and ('>>' in question or '\\gg' in question)
    trigger_symbols = ('delta' in question or '\\delta' in question) and ('sigma' in question or '\\sigma' in question)

    if not (trigger_n and trigger_symbols):
        return {"result": "inconclusive", "message": "未触发n >> 1或delta/sigma符号条件", "evidence": ""}

    # Check logic: Look for (delta * sigma)^n and its coefficient structure
    # Pattern for (delta * sigma)^n
    pattern_exp_str = r'(\\delta\\sigma|\\delta\\s*\\cdot\\s*\\sigma|\\delta\\sigma)\\^n'
    # Pattern for the denominator (delta*sigma - 1)^2
    pattern_denom_str = r'(\\delta\\sigma\\s*-\\s*1)\\^2'

    match_exp = re.search(pattern_exp_str, prediction)
    match_denom = re.search(pattern_denom_str, prediction)

    if match_exp and match_denom:
        return {
            "result": "pass",
            "message": "结果包含正确的指数增长项及其求和系数形式",
            "evidence": match_exp.group(0)
        }
    elif match_exp and not match_denom:
        return {
            "result": "fail",
            "message": "结果包含指数项但缺少正确的等比数列求和分母项 (x-1)^2",
            "evidence": match_exp.group(0)
        }

    return {"result": "inconclusive", "message": "预测中未发现明显的指数求和项结构", "evidence": ""}

