def check_exp_e6d2284b74376874_34bc17c99b54(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 定义关键物理量和求和结构的正则模式
    # 匹配累加功的求和形式，包含 Q 和 (i-1)q/n 项
    patterns = [
        r'\\sum',
        r'i-1',
        r'q/n',
        r'Q.*q/n',
        r'R'
    ]

    # 检查是否包含离散求和的逻辑特征
    matches = [1 if re.search(p, prediction) else 0 for p in patterns]
    match_count = sum(matches)

    # 如果匹配了大部分特征，认为通过
    if match_count >= 4:
        return {
            "result": "pass",
            "message": "模型正确考虑了已移入电荷对后续电荷产生的附加电势累加项",
            "evidence": "".join(re.findall(r'\\sum.*R', prediction)[:1])
        }

    # 如果完全没有求和迹象但题目触发了该逻辑，可能存在建模错误
    if 'q/n' in prediction or 'sum' in prediction.lower():
        return {
            "result": "fail",
            "message": "功的计算未正确体现离散电荷逐次移入的序列求和修正",
            "evidence": ""
        }

    return {
        "result": "inconclusive",
        "message": "未在预测中发现明确的离散功累加计算过程",
        "evidence": ""
    }

