# rule_id=exp_1add7030a55a3f17 | domain=Electromagnetism | topic=Electromagnetism / Electromagnetic Induction and Faraday's Law
def check_exp_1add7030a55a3f17_38b34f8ec946(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 匹配电动势 E 或 epsilon 的表达式
    # 核心逻辑：检查是否包含 B, omega (或 w), 以及半径的平方 (R^2 或 a^2)
    # 典型公式: 1/2 * B * omega * R^2

    # 预处理：移除空格
    clean_pred = prediction.replace(' ', '')

    # 检查磁场 B
    has_b = 'B' in clean_pred
    # 检查角速度 omega 或 w
    has_omega = '\\omega' in clean_pred or 'omega' in clean_pred or 'w' in clean_pred
    # 检查半径平方 R^2 或 a^2 或 L^2
    has_radius_sq = re.search(r'[RaL]\^2', clean_pred) or re.search(r'[RaL]\*\*[2]', clean_pred)

    # 触发场景检查：是否包含旋转、圆盘、切割等关键词
    trigger_keywords = ['旋转', '圆盘', '切割', 'rotate', 'disk', 'cutting']
    is_triggered = any(kw in sample.get('question', '') or kw in prediction for kw in trigger_keywords)

    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未识别到旋转切割场景', 'evidence': ''}

    if has_b and has_omega and has_radius_sq:
        # 进一步检查系数，通常包含 1/2 或 /2
        has_half = '1/2' in clean_pred or '/2' in clean_pred or '0.5' in clean_pred
        if has_half:
            return {'result': 'pass', 'message': '符合旋转切割电动势比例关系 E ∝ BωR^2 且包含系数1/2', 'evidence': clean_pred}
        else:
            return {'result': 'pass', 'message': '符合基本比例关系 E ∝ BωR^2', 'evidence': clean_pred}

    # 如果提到了电动势计算但缺少关键项
    if 'E=' in clean_pred or '\\epsilon=' in clean_pred:
        return {'result': 'fail', 'message': '电动势计算公式量纲不正确，缺少B、ω或半径平方项', 'evidence': clean_pred}

    return {'result': 'inconclusive', 'message': '无法确定公式正确性', 'evidence': ''}

# rule_id=exp_21edcf2ac3c79710 | domain=Electromagnetism | topic=Electromagnetism / Electromagnetic Induction and Faraday's Law
def check_exp_21edcf2ac3c79710_27cce4193456(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    # 触发条件：题目中同时出现互感M、自感L、电阻R
    trigger_keywords = ['互感', '自感', '电阻', 'M', 'L', 'R']
    trigger_count = sum(1 for k in trigger_keywords if k in question)
    if trigger_count < 3:
        return {"result": "inconclusive", "message": "未检测到足够的RL回路参数", "evidence": ""}

    # 检查逻辑：是否考虑了自感L对阻抗的影响，即 sqrt(R^2 + (wL)^2) 或 R + jwL
    # 错误模式：直接忽略L项，即 I = E/R 或 I = M(dI/dt)/R
    correct_patterns = [
        r'sqrt\(R\^2\s*\+\s*\(omega\s*\*\s*L\)\^2\)',
        r'R\^2\s*\+\s*w\^2\s*L\^2',
        r'R\s*\+\s*j\s*omega\s*L',
        r'Z\s*=\s*sqrt',
        r'\\sqrt{R\^2\s*\+\s*\\omega\^2L\^2}'
    ]

    error_patterns = [
        r'I\s*=\s*M\s*\*\s*omega\s*\*\s*I_0\s*/\s*R(?!\s*\+)',
        r'I\s*=\s*E\s*/\s*R(?!\s*\+)'
    ]

    found_correct = any(re.search(p, prediction, re.IGNORECASE) for p in correct_patterns)
    found_error = any(re.search(p, prediction, re.IGNORECASE) for p in error_patterns)

    if found_correct:
        return {"result": "pass", "message": "正确应用了复阻抗或考虑了自感项", "evidence": ""}

    if found_error:
        return {"result": "fail", "message": "计算感应电流时忽略了回路自感L的影响", "evidence": "检测到简化公式 I=E/R"}

    return {"result": "inconclusive", "message": "无法确定是否正确处理了自感耦合", "evidence": ""}

# rule_id=exp_37e88b0d6c08f037 | domain=Electromagnetism | topic=Electromagnetism / Electromagnetic Induction and Faraday's Law
def check_exp_37e88b0d6c08f037_99ed18a19a3f(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 识别加速度 a 包含速度 v 的表达式，如 a = (mg - B^2L^2v/R)/m
    # 匹配 a=...v... 或 dv/dt=...v...
    has_v_dependent_a = bool(re.search(r'[ad]v?/[dt]t?\s*=\s*[^=]*v', prediction))
    # 识别是否错误使用了匀变速直线运动公式
    # 典型错误：s = 1/2 * a * t^2 或 v = v0 + at (当 a 不是常数时)
    wrong_formulas = [
        r's\s*=\s*(1/2|0\.5)\s*\*?\s*a\s*\*?\s*t\^?2',
        r'v\s*=\s*v_?0\s*\+\s*a\s*\*?\s*t',
        r'v\^?2\s*-\s*v_?0\^?2\s*=\s*2\s*a\s*s'
    ]

    if has_v_dependent_a:
        for pattern in wrong_formulas:
            match = re.search(pattern, prediction)
            if match:
                return {
                    "result": "fail",
                    "message": "加速度包含速度变量时，禁止直接使用匀变速直线运动公式，应使用积分法。",
                    "evidence": match.group(0)
                }

        # 检查是否包含积分或微分方程处理的迹象
        has_integral_logic = bool(re.search(r'\\int|dt|dv|ln\(|exp\(', prediction))
        if has_integral_logic:
            return {
                "result": "pass",
                "message": "检测到加速度与速度相关，且使用了积分或微分方程处理逻辑。",
                "evidence": ""
            }
        else:
            return {
                "result": "inconclusive",
                "message": "加速度与速度相关，但未明确检测到正确的积分过程或错误的公式套用。",
                "evidence": ""
            }

    return {
        "result": "inconclusive",
        "message": "未检测到加速度包含速度变量的特征。",
        "evidence": ""
    }

