# rule_id=exp_3a38bdc5aa1adc1a | domain=Electromagnetism | topic=Electromagnetism / Electromagnetic Induction and Faraday's Law
def check_exp_3a38bdc5aa1adc1a_633fa6a320d1(sample: dict) -> dict:

    prediction = sample.get('prediction', '')

    # 识别是否涉及相位差或tan delta
    phase_keywords = ['相位差', 'tan', 'δ', 'delta', '滞后', '超前', '阻抗角']
    if not any(kw in prediction for kw in phase_keywords):
        return {"result": "inconclusive", "message": "未检测到相位差相关描述", "evidence": ""}

    # 检查是否明确了滞后/超前关系
    has_direction = any(kw in prediction for kw in ['滞后', '超前', 'lag', 'lead'])

    # 检查tan delta公式中电阻与感抗/容抗的关系 (通常为 X/R 或 R/X)
    # 规则要求核实上下层级关系，防止混淆
    has_tan_expr = re.search(r'tan\s*[δ|delta]\s*=\s*([^\s]+)', prediction)

    if has_tan_expr:
        expr = has_tan_expr.group(1)
        # 如果出现了tan delta但没有说明谁滞后谁，或者公式中R和X的位置模糊
        if not has_direction:
            return {
                "result": "fail",
                "message": "相位差定义不明确：未说明I2相对于I1是滞后还是超前",
                "evidence": has_tan_expr.group(0)
            }

        # 检查是否存在潜在的阻抗角混淆（例如在损耗角定义中误用了阻抗角公式）
        if 'R' in expr and ('X' in expr or 'L' in expr or 'C' in expr):
            return {"result": "pass", "message": "相位差定义及公式逻辑已包含", "evidence": has_tan_expr.group(0)}

    if has_direction:
        return {"result": "pass", "message": "已明确相位超前/滞后关系", "evidence": ""}

    return {"result": "inconclusive", "message": "无法确定相位差定义的严谨性", "evidence": ""}

# rule_id=exp_48220b07be595460 | domain=Electromagnetism | topic=Electromagnetism / Electromagnetic Induction and Faraday's Law
def check_exp_48220b07be595460_635af6f815ab(sample: dict) -> dict:

    prediction = sample.get('prediction', '')

    # 触发词：步长参数 tau 或 delta_x，以及求和符号 sum 或 \\sum
    trigger_patterns = [r'tau', r'delta_x', r'\\Delta x', r'\\sum', r'sum']
    has_trigger = any(re.search(p, prediction) for p in trigger_patterns)

    if not has_trigger:
        return {"result": "inconclusive", "message": "未检测到步长参数或求和符号", "evidence": ""}

    # 检查逻辑：如果出现了求和且出现了积分，验证是否包含步长微分元
    # 寻找类似 sum(f * tau) -> integral(f dt) 的结构
    has_sum = re.search(r'(\\sum|sum)', prediction)
    has_integral = re.search(r'(\\int|integral)', prediction)

    if has_sum and has_integral:
        # 检查积分中是否包含对应的微分元 (dt, dx)
        has_differential = re.search(r'd[t|x]', prediction)
        # 检查求和中是否包含步长因子 (tau, delta)
        has_step_factor = re.search(r'(tau|delta)', prediction)

        if has_step_factor and not has_differential:
            return {
                "result": "fail",
                "message": "离散求和转积分时缺失对应的微分元",
                "evidence": prediction[max(0, has_integral.start()-20):min(len(prediction), has_integral.end()+20)]
            }

        if not has_step_factor and has_differential:
            return {
                "result": "fail",
                "message": "求和项中未发现与积分微分元对应的步长参数",
                "evidence": prediction[max(0, has_sum.start()-20):min(len(prediction), has_sum.end()+20)]
            }

        return {"result": "pass", "message": "求和与积分转换形式基本一致", "evidence": ""}

    return {"result": "inconclusive", "message": "未同时发现求和与积分过程，无法验证一致性", "evidence": ""}

# rule_id=exp_66a9ed214a563250 | domain=Electromagnetism | topic=Electromagnetism / Electromagnetic Induction and Faraday's Law
def check_exp_66a9ed214a563250_4a62e91b944c(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    # 触发条件：要求计算端电压且处于断路状态
    is_open_circuit = any(kw in question for kw in ['断路', '断开', '未闭合', 'open circuit'])
    is_asking_v = any(kw in question for kw in ['V_PQ', 'U_PQ', '端电压', '电势差', '电压'])

    if not (is_open_circuit and is_asking_v):
        return {"result": "inconclusive", "message": "未识别到断路状态或端电压计算请求", "evidence": ""}

    # 检查逻辑：断路时电流应为0，但电动势存在
    # 错误模式：在断路情况下尝试计算电流 I = E/R 或认为 V=0 (忽略了感应电动势)
    error_patterns = [
        r"I\s*=\s*E\s*/\s*R",
        r"电流为\s*[1-9]",
        r"V_PQ\s*=\s*0",
        r"U_PQ\s*=\s*0"
    ]

    found_error = False
    evidence = ""
    for pattern in error_patterns:
        match = re.search(pattern, prediction)
        if match:
            found_error = True
            evidence = match.group(0)
            break

    if found_error:
        return {
            "result": "fail",
            "message": "断路状态下不应通过欧姆定律计算电流，端电压应等于感应电动势而非0",
            "evidence": evidence
        }

    # 正确模式：V = E = Blv
    correct_patterns = [
        r"V_PQ\s*=\s*B\s*l\s*v",
        r"U_PQ\s*=\s*B\s*l\s*v",
        r"E\s*=\s*B\s*l\s*v"
    ]
    for pattern in correct_patterns:
        if re.search(pattern, prediction):
            return {"result": "pass", "message": "正确识别断路状态下的电动势计算", "evidence": ""}

    return {"result": "inconclusive", "message": "无法确定计算逻辑是否正确", "evidence": ""}

# rule_id=exp_6da50abc8c7eb789 | domain=Electromagnetism | topic=Electromagnetism / Electromagnetic Induction and Faraday's Law
def check_exp_6da50abc8c7eb789_161113319176(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 检查是否同时出现了总匝数 N 和长度 l
    has_N = bool(re.search(r'N\s*=', prediction)) or 'N' in prediction
    has_l = bool(re.search(r'l\s*=', prediction)) or 'l' in prediction

    if not (has_N and has_l):
        return {"result": "inconclusive", "message": "未在预测中同时识别到总匝数 N 和长度 l", "evidence": ""}

    # 匹配磁场公式 B = mu * N * i 的错误形式 (忽略系数)
    # 错误模式：直接使用 N 而没有除以 l
    error_pattern = r'B\s*=\s*[^\/]*?\mu_?0?\s*N\s*i'
    # 正确模式：使用了 N/l 或 n
    correct_pattern = r'B\s*=\s*.*?\mu_?0?\s*\(\s*N\s*/\s*l\s*\)\s*i|B\s*=\s*.*?\mu_?0?\s*n\s*i'

    error_match = re.search(error_pattern, prediction, re.IGNORECASE)
    correct_match = re.search(correct_pattern, prediction, re.IGNORECASE)

    if error_match and not correct_match:
        return {
            "result": "fail",
            "message": "磁场公式错误地直接使用了总匝数 N 而非匝数密度 N/l",
            "evidence": error_match.group(0)
        }
    elif correct_match:
        return {
            "result": "pass",
            "message": "正确使用了匝数密度公式",
            "evidence": correct_match.group(0)
        }

    return {"result": "inconclusive", "message": "无法确定公式是否正确应用了匝数密度", "evidence": ""}

# rule_id=exp_732464e4fa43295b | domain=Electromagnetism | topic=Electromagnetism / Electromagnetic Induction and Faraday's Law
def check_exp_732464e4fa43295b_15db6269f878(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 检查是否同时存在磁场变化(dB/dt)和面积/位置变化(v, dA/dt, L)
    has_b_change = any(x in prediction for x in ['dB/dt', 'dB', 'B(t)', 'dot{B}'])
    has_motion = any(x in prediction for x in ['v', 'dA/dt', 'dx/dt', 'L*v'])

    if not (has_b_change and has_motion):
        return {"result": "inconclusive", "message": "未检测到动生与感生同时存在的场景", "evidence": ""}

    # 检查叠加逻辑：寻找类似 B*L*v + A*dB/dt 的结构，注意符号判定
    # 匹配模式：项1 (B*L*v 或类似) 符号 项2 (A*dB/dt 或类似)
    # 错误通常发生在将两者简单相减而忽略了楞次定律定义的正方向
    pattern_sum = re.compile(r'([BLv]{2,3}.*[\+\-].*[A-Za-z]*dB/dt)|(dB/dt.*[\+\-].*[BLv]{2,3})')
    match = pattern_sum.search(prediction)

    if match:
        evidence = match.group(0)
        # 如果公式中出现了减号，且上下文没有明确的坐标系定义抵消，则可能存在风险
        # 但由于物理环境复杂，此处仅检查是否执行了求导叠加形式
        if '+' in evidence or '-' in evidence:
            return {"result": "pass", "message": "检测到电动势叠加计算式", "evidence": evidence}
        else:
            return {"result": "fail", "message": "未发现明确的电动势项叠加逻辑", "evidence": evidence}

    return {"result": "inconclusive", "message": "无法解析具体的叠加公式", "evidence": ""}

# rule_id=exp_7457cb1eb5179f29 | domain=Electromagnetism | topic=Electromagnetism / Electromagnetic Induction and Faraday's Law
def check_exp_7457cb1eb5179f29_b97acb4c0f57(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '无预测内容', 'evidence': ''}

    # 匹配常见的磁通量公式模式: Phi = (mu0 * I * L / 2pi) * ln(r2/r1)
    # 重点检查 ln 内部是否为距离比值，外部是否有长度系数 L
    ln_pattern = re.compile(r'ln\\?\\(([^\\)]+)\\)')
    frac_pattern = re.compile(r'\\frac{([^}]+)}{([^}]+)}')

    matches = ln_pattern.findall(prediction)
    if not matches:
        return {'result': 'inconclusive', 'message': '未检测到对数项公式', 'evidence': ''}

    for match in matches:
        # 检查对数项内部是否包含比值结构
        if '/' in match or '\\frac' in match:
            # 检查公式前缀是否包含长度 L (平行于导线的边)
            # 典型的错误是将垂直边的长度放在了系数位置，或者对数项颠倒
            prefix_part = prediction.split(match)[0]
            # 寻找是否包含 mu0, I, L 等符号
            has_l = 'L' in prefix_part or 'l' in prefix_part

            # 检查对数项是否为距离比 (r_far / r_near)
            # 简单逻辑：如果对数项里出现了 L，通常是错误的建模（L应在外面）
            if 'L' in match or 'l' in match:
                return {
                    'result': 'fail',
                    'message': '积分变量混淆：平行于导线的边长L应作为线性系数，而非在对数项内。',
                    'evidence': match
                }

            if has_l:
                return {
                    'result': 'pass',
                    'message': '公式结构符合长直导线磁通量积分规律。',
                    'evidence': match
                }

    return {'result': 'inconclusive', 'message': '无法确定公式变量对应关系', 'evidence': ''}

