# rule_id=exp_7cf000807a5a8961 | domain=Electromagnetism | topic=Electromagnetism / Electromagnetic Induction and Faraday's Law
def check_exp_7cf000807a5a8961_53f7d47d04b2(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 检查是否涉及磁针偏转、平均场或感应磁场
    keywords = ['磁针', '偏转', '平均磁场', '感应磁场', 'B_ind', 'tan']
    if not any(kw in prediction or kw in question for kw in keywords):
        return {"result": "inconclusive", "message": "未检测到磁针偏转或平均场相关物理量", "evidence": ""}

    # 提取公式特征：tan(alpha) = B_avg / B_ext
    # 匹配模式：tan(alpha) = B_ind / B_0 或类似结构
    pattern = r"tan\\s*[\\(\\s]*[\\u03b1a-zA-Z]+[\\s\\)]*\\s*=\\s*([^\\s/]+)\\s*/\\s*([^\\s]+)"
    match = re.search(pattern, prediction)

    if match:
        numerator = match.group(1)
        denominator = match.group(2)

        # 检查分子是否包含平均值含义 (avg, mean, <B>)
        is_avg = any(x in numerator.lower() for x in ['avg', 'mean', 'bar', 'average', 'ind'])
        # 检查分母是否为背景场 (earth, ext, 0)
        is_ext = any(x in denominator.lower() for x in ['earth', 'ext', '0', 'background'])

        if is_avg and is_ext:
            return {"result": "pass", "message": "正确应用了平均场偏转角公式", "evidence": match.group(0)}
        else:
            return {"result": "fail", "message": "偏转角公式中物理量对应关系错误，需使用平均感应场与背景场之比", "evidence": match.group(0)}

    # 检查文本描述逻辑
    if '平均' in prediction and ('磁场' in prediction or 'B' in prediction) and 'tan' in prediction:
        return {"result": "pass", "message": "文本逻辑符合平均场效应描述", "evidence": ""}

    return {"result": "inconclusive", "message": "无法确定公式逻辑是否正确", "evidence": ""}

# rule_id=exp_90d8ca55fb236125 | domain=Electromagnetism | topic=Electromagnetism / Electromagnetic Induction and Faraday's Law
def check_exp_90d8ca55fb236125_8eafd101d55d(sample: dict) -> dict:

    text = sample.get('prediction', '') + ' ' + sample.get('answer', '')
    # 检查是否属于电磁感应导轨类场景
    keywords = ['导体棒', '导轨', '磁场', '切割', '电磁炮']
    is_relevant = any(kw in (sample.get('question', '') + text) for kw in keywords)
    if not is_relevant:
        return {"result": "inconclusive", "message": "未识别到相关物理场景", "evidence": ""}

    # 检查是否存在速度 v 且不为 0 的描述
    has_velocity = re.search(r'[vV]\s*=\s*[1-9]', text) or '速度' in text
    # 检查是否存在电源 V 或 E
    has_voltage = re.search(r'[VE]\s*=', text) or '电压' in text or '电动势' in text

    if not (has_velocity and has_voltage):
        return {"result": "inconclusive", "message": "缺少速度或电压关键参数", "evidence": ""}

    # 检查电流表达式是否仅为 V/R 而忽略了 BLv
    # 匹配类似 I = V/R 或 I = E/R 的模式，且后面没有减去 BLv 或加上 BLv
    simple_ohm = re.search(r'I\s*=\s*[VE]/R(?!\s*[-+]|[\w\s]*B)', text)
    # 检查是否包含完整的动生电动势项 BLv 或 B*L*v
    has_motional_emf = re.search(r'B\s*\*?\s*L\s*\*?\s*v', text, re.IGNORECASE)

    if simple_ohm and not has_motional_emf:
        return {
            "result": "fail",
            "message": "电流表达式缺失动生电动势项 (BLv)",
            "evidence": simple_ohm.group(0)
        }
    elif has_motional_emf:
        return {
            "result": "pass",
            "message": "电流表达式包含动生电动势项",
            "evidence": has_motional_emf.group(0)
        }

    return {"result": "inconclusive", "message": "无法确定电流建模完整性", "evidence": ""}

