# rule_id=exp_385f358f3b4e6541 | domain=Electromagnetism | topic=Electromagnetism / Lenz's Law and Eddy Currents
def check_exp_385f358f3b4e6541_67c305439bc2(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '无预测内容', 'evidence': ''}

    # 匹配特征速度 v0 的定义公式，关注 2/(mu0 * sigma * d) 的结构
    # 允许不同的符号表示，但核心逻辑是 2 除以 (磁导率 * 电导率 * 厚度)
    patterns = [
        r'v_?0\s*=\s*2\s*/\s*\(\s*mu_?0\s*\\?sigma\s*d\s*\)',
        r'v_?0\s*=\s*\\frac\{2\}\{\s*\\mu_?0\s*\\sigma\s*d\s*\}',
        r'v_?0\s*=\s*2\s*/\s*mu_?0\s*\\sigma\s*d'
    ]

    found_correct = False
    evidence = ''
    for p in patterns:
        match = re.search(p, prediction, re.IGNORECASE)
        if match:
            found_correct = True
            evidence = match.group(0)
            break

    # 检查是否存在错误建模：将 v0 误认为运动速度 v 的函数
    error_pattern = r'v_?0\s*=\s*f\(v\)|v_?0\s*\\propto\s*v'
    if re.search(error_pattern, prediction, re.IGNORECASE):
        return {'result': 'fail', 'message': '特征速度 v0 被错误地建模为运动速度 v 的函数', 'evidence': re.search(error_pattern, prediction).group(0)}

    if found_correct:
        return {'result': 'pass', 'message': '正确定义了特征速度 v0 = 2/(mu0 * sigma * d)', 'evidence': evidence}

    # 如果提到了 v0 但没有给出正确的定义式，返回 inconclusive
    if 'v_0' in prediction or 'v0' in prediction:
        return {'result': 'inconclusive', 'message': '检测到特征速度符号但未发现明确的正确定义公式', 'evidence': ''}

    return {'result': 'inconclusive', 'message': '未检测到特征速度 v0 的相关建模逻辑', 'evidence': ''}

