# rule_id=exp_9d07570b3869d6eb | domain=Electromagnetism | topic=Electromagnetism / Lenz's Law and Eddy Currents
def check_exp_9d07570b3869d6eb_9de720145f01(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测文本为空', 'evidence': ''}

    # 检查是否包含磁矩相关的符号或描述
