# rule_id=exp_3cefc83584b1a3fa | domain=Electromagnetism | topic=Electromagnetism / Magnetic Dipoles and Magnetic Materials
def check_exp_3cefc83584b1a3fa_fc57be791a7c(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    # Trigger: Check if the problem involves magnetic monopoles or dipoles
    trigger_keywords = ['magnetic monopole', 'magnetic dipole', '磁单极', '磁偶极']
    is_triggered = any(kw in question.lower() for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未触发磁源模型校验条件", "evidence": ""}

    # Check logic: Look for signs of incorrect summation of field magnitudes instead of vector subtraction
    # Dipole field on axis: B ~ 1/(z-d)^2 - 1/(z+d)^2 or similar subtraction patterns
    # Incorrect modeling often adds them: 1/(z-d)^2 + 1/(z+d)^2

    # Search for addition patterns in prediction that suggest same-sign charges (incorrect for standard dipole)
    addition_patterns = [
        r"1/.*\^2\s*\+\s*1/.*\^2",
        r"q_m.*\+.*q_m",
        r"磁场.*相加",
        r"sum.*of.*fields"
    ]

    # Search for subtraction patterns (correct for dipole)
    subtraction_patterns = [
        r"1/.*\^2\s*-\s*1/.*\^2",
        r"q_m.*-.*q_m",
        r"vector.*subtraction",
        r"矢量.*相减"
    ]

    found_addition = any(re.search(p, prediction, re.IGNORECASE) for p in addition_patterns)
    found_subtraction = any(re.search(p, prediction, re.IGNORECASE) for p in subtraction_patterns)

    if found_addition and not found_subtraction:
        # Check if the question explicitly allows same-sign charges
        if 'same sign' in question.lower() or '同号' in question:
            return {"result": "pass", "message": "题目明确要求同号电荷处理", "evidence": ""}

        evidence = re.search(addition_patterns[0], prediction, re.IGNORECASE).group(0) if re.search(addition_patterns[0], prediction, re.IGNORECASE) else ""
        return {
            "result": "fail",
            "message": "磁偶极子模型应使用等量异号磁荷，磁场贡献应为矢量相减而非绝对值相加",
            "evidence": evidence
        }

    if found_subtraction:
        return {"result": "pass", "message": "符合磁偶极子矢量相减模型", "evidence": ""}

    return {"result": "inconclusive", "message": "无法确定磁源极性处理逻辑", "evidence": ""}

