    # Source -> Accel1 -> Accel2 -> Drift -> Detector
    # We look for time summation or distance sequence in the prediction
    # Common symbols: t1, t2, t_drift or d1, d2, L

    # Check if the prediction mentions the drift region L after acceleration stages
    # A common error is placing the drift region between acceleration stages

    # Look for patterns like t = t1 + t2 + t_L or similar logic
    drift_pattern = re.compile(r'drift|L|t_L|t_drift', re.IGNORECASE)
    accel_pattern = re.compile(r'acceleration|accel|t1|t2|d1|d2', re.IGNORECASE)

    if not drift_pattern.search(prediction):
        return {"result": "inconclusive", "message": "Drift region parameters not found in prediction.", "evidence": ""}

    # Heuristic: Check if the logic implies Accel -> Drift
    # If the prediction contains a sequence of terms, we check if 'drift' or 'L' appears after 'acceleration'
    accel_pos = prediction.lower().find('acceleration')
    drift_pos = prediction.lower().find('drift')

    if accel_pos != -1 and drift_pos != -1:
        if drift_pos < accel_pos:
            return {
                "result": "fail",
                "message": "The drift region appears to be positioned before the acceleration stage in the logic.",
                "evidence": prediction[min(accel_pos, drift_pos):max(accel_pos, drift_pos)+10]
            }

    # Check for time accumulation logic: t_total = t_accel + t_drift
    # If it shows t_total = t_drift + t_accel (where drift is first), it might be a logic error in mass spec context
    # However, addition is commutative, so we look for structural descriptions

    structural_keywords = ['then', 'followed by', 'enters', 'reaches']
    found_sequence = False
    for kw in structural_keywords:
        if kw in prediction.lower():
            found_sequence = True
            break

    if not found_sequence:
        return {"result": "inconclusive", "message": "No clear sequential description found to verify logic.", "evidence": ""}

    return {"result": "pass", "message": "The sequence of acceleration and drift regions appears consistent with mass spectrometer logic.", "evidence": ""}

