def check_exp_3c20c3d95614cd31_414c06bdf5db(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 检查是否包含广义动量相关的关键词
    keywords = ['momentum', 'generalized', 'P =', 'P=', '动量']
    if not any(kw.lower() in prediction.lower() for kw in keywords):
        return {'result': 'inconclusive', 'message': '未检测到动量表达式', 'evidence': ''}

    # 匹配修正项 q * l * B 的变体，考虑叉乘或点乘符号
    # 目标形式: q * l * B 或 q * (l x B) 或 qlB
    pattern_qlB = re.compile(r'q.*[l|L|\ell].*[B|\vec{B}]')
    # 匹配质量与速度项 M * v_CM
    pattern_Mv = re.compile(r'[M|m].*[v|V]')

    has_qlB = bool(pattern_qlB.search(prediction))
    has_Mv = bool(pattern_Mv.search(prediction))

    if has_qlB and has_Mv:
        # 进一步检查量纲逻辑：q, l, B 必须同时存在于一个项中
        # 简单检查是否包含 q, l, B 字符
        if 'q' in prediction and ('l' in prediction or '\\ell' in prediction) and 'B' in prediction:
            return {'result': 'pass', 'message': '公式符合广义动量量纲与结构要求', 'evidence': prediction}
        else:
            return {'result': 'fail', 'message': '修正项符号不完整', 'evidence': prediction}
    elif has_Mv and not has_qlB:
        return {'result': 'fail', 'message': '缺少磁场修正项 q(l x B)', 'evidence': prediction}

    return {'result': 'inconclusive', 'message': '无法确定公式准确性', 'evidence': ''}

