    prediction = sample.get('prediction', '')

    # 触发条件检查：是否存在几何约束 r0 << R0 或类似表达
    trigger_pattern = r'(r0\s*<<\s*R0|R0\s*>>\s*r0|r\s*<<\s*R)'
    if not re.search(trigger_pattern, question):
        return {"result": "inconclusive", "message": "未检测到特定的几何约束触发条件", "evidence": ""}

    # 检查逻辑：是否直接假设磁场为常数 (B = const, B为常数, 均匀磁场)
    constant_field_patterns = [
        r'假设磁场为常数', r'磁场是均匀的', r'B\s*=\s*B0', r'B\s*为常数',
        r'uniform magnetic field', r'constant magnetic field'
    ]

    # 检查逻辑：是否包含推导迹象 (安培环路定理, Ampere, 积分, 分布)
    derivation_patterns = [
        r'安培环路定理', r'Ampere', r'\\oint', r'integral', r'B\(r\)', r'B\(z\)', r'分布'
    ]

    is_constant_assumed = any(re.search(p, prediction) for p in constant_field_patterns)
    has_derivation = any(re.search(p, prediction) for p in derivation_patterns)

    if is_constant_assumed and not has_derivation:
        return {
            "result": "fail",
            "message": "在存在几何约束的情况下直接假设磁场为常数，未进行空间分布推导",
            "evidence": "检测到常数磁场假设且缺乏推导过程"
        }

    if has_derivation:
        return {
            "result": "pass",
            "message": "检测到磁场空间分布的推导逻辑",
            "evidence": "匹配到推导相关关键词或公式"
        }

