    # 核心系数逻辑：omega^2 = (M*B)/I = (I_current * S * B) / I_moment
    # 匹配常见的角频率平方或周期公式特征
    # 寻找类似 MB/I, ISB/I, (ISB)/I 的结构
    patterns = [
        r'\\frac{[^}]*I[^}]*S[^}]*B[^}]*}{I}',
        r'\\frac{M\\s*B}{I}',
        r'\\omega^2\\s*=\\s*\\frac{',
        r'T\\s*=\\s*2\\pi\\s*\\sqrt{\\frac{I}{'
    ]

    found_formula = False
    for p in patterns:
        if re.search(p, prediction):
            found_formula = True
            break

    if not found_formula:
        return {'result': 'inconclusive', 'message': '未找到明确的动力学方程系数表达式', 'evidence': ''}

    # 校验转动惯量 I 与 磁矩 M 的位置关系
    # 在周期公式中，I 应该在分子；在 omega^2 中，I 应该在分母
    if 'T =' in prediction or 'T=' in prediction or '\\pi' in prediction:
        if re.search(r'T.*\\sqrt{\\frac{I}{.*B', prediction) or re.search(r'T.*\\sqrt{\\frac{I}{.*M', prediction):
            return {'result': 'pass', 'message': '周期公式系数结构正确', 'evidence': 'T与sqrt(I/MB)匹配'}
        elif re.search(r'T.*\\sqrt{\\frac{.*B}{I}', prediction):
            return {'result': 'fail', 'message': '周期公式中转动惯量与磁矩位置颠倒', 'evidence': prediction}

    if 'omega' in prediction or '\\omega' in prediction:
        if re.search(r'\\omega^2.*\\frac{.*B}{I}', prediction) or re.search(r'\\omega^2.*\\frac{M', prediction):
            return {'result': 'pass', 'message': '角频率平方系数结构正确', 'evidence': 'omega^2与MB/I匹配'}
        elif re.search(r'\\omega^2.*\\frac{I}{', prediction):
            return {'result': 'fail', 'message': '角频率公式中转动惯量位置错误', 'evidence': prediction}

    return {'result': 'inconclusive', 'message': '公式结构模糊，无法确定系数准确性', 'evidence': ''}

