# rule_id=exp_8b5c00401e80e020 | domain=Electromagnetism | topic=Electromagnetism / Magnetic Fields and Lorentz Force
def check_exp_8b5c00401e80e020_f76749c2f44a(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    trigger_words = ['high magnetic permeability', 'field lines constrained inside']
    is_triggered = any(word in question.lower() for word in trigger_words)

    if not is_triggered:
        return {"result": "inconclusive", "message": "Trigger words not found in question.", "evidence": ""}

    # Search for flux equality patterns like Phi_1 = Phi_2 or Phi1 = Phi2
    # Also check for common errors like Phi_1 = 2*Phi_2 or Phi_1 = 0.5*Phi_2
    flux_pattern = re.compile(r'\\Phi(?:_{?[^}]*}?|\d+)?\s*=\s*([^\\s=]+)\\Phi(?:_{?[^}]*}?|\d+)?')
    matches = flux_pattern.findall(prediction)

    if not matches:
        return {"result": "inconclusive", "message": "No magnetic flux continuity expression found in prediction.", "evidence": ""}

    for coefficient in matches:
        # Clean the coefficient to see if it represents a multiplier other than 1
        clean_coeff = coefficient.strip().replace('*', '').replace(' ', '')
        if clean_coeff and clean_coeff != '1' and any(char.isdigit() for char in clean_coeff):
            return {
                "result": "fail",
                "message": "Magnetic flux continuity violated: non-unity scaling factor detected.",
                "evidence": f"Detected scaling factor: {coefficient}"
            }

    return {"result": "pass", "message": "Magnetic flux continuity (Phi1 = Phi2) is maintained.", "evidence": str(matches)}

