# rule_id=exp_a641b5617285ed98 | domain=Electromagnetism | topic=Electromagnetism / Magnetic Fields and Lorentz Force
def check_exp_a641b5617285ed98_015d13d18c5b(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 匹配时间尺度公式，寻找包含 m, q/e, B, gamma 的结构
    # 核心逻辑：t 正比于 m / (q * B * gamma^n)
    patterns = [
        r'm\s*/\s*\(\s*[qe]\s*\*?\s*B\s*\*?\s*gamma\s*\^?\s*[23]\s*\)',
        r'[qe]\s*B\s*gamma\s*\^?\s*[23]\s*/\s*m',
        r'm\s*[qe]^-1\s*B^-1\s*gamma\^?-[23]'
    ]

    found = False
    evidence = ''
    for p in patterns:
        match = re.search(p, prediction, re.IGNORECASE)
        if match:
            found = True
            evidence = match.group(0)
            break

    if not found:
        # 如果没有直接匹配到公式，检查是否提到了 gamma 的平方或三次方反比关系
        if 'gamma' in prediction.lower() and ('square' in prediction.lower() or 'cube' in prediction.lower() or '^2' in prediction or '^3' in prediction):
            return {'result': 'pass', 'message': '检测到符合逻辑的 gamma 幂次描述', 'evidence': 'gamma related terms found'}
        return {'result': 'inconclusive', 'message': '未发现明确的同步辐射时间尺度公式结构', 'evidence': ''}

    # 检查 gamma 的幂次是否在分母（即负幂次）
    if '/' in evidence or '^-' in evidence:
        return {'result': 'pass', 'message': '公式结构符合同步辐射特征时间量纲', 'evidence': evidence}
    else:
        return {'result': 'fail', 'message': '公式结构可能颠倒了量纲关系', 'evidence': evidence}

