# rule_id=exp_b678b53ab2898c35 | domain=Electromagnetism | topic=Electromagnetism / Magnetic Fields and Lorentz Force
def check_exp_b678b53ab2898c35_ee951e7026f2(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 检查是否涉及磁矩 mu 或等效电流 I 的计算场景
    trigger_keywords = ['magnetic moment', 'equivalent current', 'cyclotron', '回旋', '磁矩', '等效电流']
    if not any(kw in prediction.lower() for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未检测到磁矩或等效电流相关计算场景', 'evidence': ''}

    # 匹配磁矩 mu 的表达式特征：包含 v^2 (或 v_perp^2) 且与 B 成反比
    # 目标公式形式: mu = (m * v^2) / (2 * B)
    mu_pattern = re.compile(r'mu\s*=\s*.*v.*\^2.*/.*B', re.IGNORECASE)
    energy_pattern = re.compile(r'mu\s*=\s*.*E_k.*/.*B', re.IGNORECASE)

    # 匹配电流 I = qf = qv / 2pir
    current_pattern = re.compile(r'I\s*=\s*q.*v.*/.*r', re.IGNORECASE)

    has_mu_correct = bool(mu_pattern.search(prediction) or energy_pattern.search(prediction))
    has_current_correct = bool(current_pattern.search(prediction))

    if has_mu_correct:
        return {'result': 'pass', 'message': '磁矩表达式符合量纲一致性（v^2/B结构）', 'evidence': mu_pattern.search(prediction).group() if mu_pattern.search(prediction) else energy_pattern.search(prediction).group()}

    if 'mu' in prediction.lower() and 'B' in prediction:
        # 如果提到了 mu 和 B 但不符合反比或平方关系，则可能错误
        wrong_mu = re.compile(r'mu\s*=\s*.*B.*v', re.IGNORECASE)
        if wrong_mu.search(prediction):
            return {'result': 'fail', 'message': '磁矩表达式量纲错误：未发现速度平方或与磁场成反比关系', 'evidence': wrong_mu.search(prediction).group()}

    return {'result': 'inconclusive', 'message': '无法确定公式推导的准确性', 'evidence': ''}

