    prediction = sample.get('prediction', '')

    # 触发条件：多个带电粒子、磁场、距离恒定/相对静止
    trigger_keywords = ['带电粒子', '磁场', '距离恒定', '相对静止', '保持不变']
    is_triggered = any(kw in question for kw in trigger_keywords) and ('粒子' in question)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未触发多粒子约束运动场景", "evidence": ""}

    # 检查逻辑：是否同时考虑了洛伦兹力 (qvB) 和 库仑力 (ke^2/r^2)
    # 匹配公式特征：包含 v, B, k, e/q, d/r 以及平方项
    lorentz_pattern = re.compile(r'(qvB|evB|qvb|evb)', re.I)
    coulomb_pattern = re.compile(r'(k[qe]?\^2/|k[qe][qe]/[rd]\^2)', re.I)
    centripetal_pattern = re.compile(r'(mv\^2/[rd]|m\w\^2[rd])', re.I)

    has_lorentz = bool(lorentz_pattern.search(prediction))
    has_coulomb = bool(coulomb_pattern.search(prediction)) or '库仑力' in prediction
    has_balance = '=' in prediction and (has_lorentz or has_coulomb)

    if is_triggered:
        if not (has_lorentz and has_coulomb):
            return {
                "result": "fail",
                "message": "分析多粒子约束运动时，未同时考虑洛伦兹力与库仑力的综合作用",
                "evidence": prediction[:100]
            }
        return {
            "result": "pass",
            "message": "已考虑洛伦兹力与库仑力的平衡关系",
            "evidence": ""
        }

    return {"result": "inconclusive", "message": "无法确定模型完整性", "evidence": ""}

