# rule_id=exp_d2c587c182607b74 | domain=Electromagnetism | topic=Electromagnetism / Magnetic Fields and Lorentz Force
def check_exp_d2c587c182607b74_af735418f46d(sample: dict) -> dict:

    text = (sample.get('prediction', '') + ' ' + sample.get('answer', '')).lower()

    # 检查是否涉及电场、磁场和阻力项
    has_e = any(x in text for x in ['e', '电场', 'electric field'])
    has_b = any(x in text for x in ['b', '磁场', 'magnetic field'])
    has_tau = any(x in text for x in ['tau', 'τ', '弛豫时间', 'relaxation time'])
    has_v = any(x in text for x in ['v', '速度', 'velocity'])

    if not (has_e and has_b and has_tau and has_v):
        return {"result": "inconclusive", "message": "未检测到完整的输运平衡物理量", "evidence": ""}

    # 检查平衡方程的核心逻辑：qE + q(v x B) - mv/tau = 0
    # 重点检查阻力项符号是否为负，且与速度方向相反
    drag_patterns = [
        r"mv/\\tau", r"mv/tau", r"m\\vec{v}/\\tau", r"-mv/\\tau",
        r"\\frac{mv}{\\tau}", r"\\frac{m v}{\\tau}"
    ]

    found_drag = False
    for p in drag_patterns:
        if re.search(p, text):
            found_drag = True
            break

    # 检查是否存在正号阻力项（错误逻辑）
    wrong_drag = re.search(r"\+\s*mv/\\tau|\+\s*\\frac{mv}{\\tau}", text)

    # 检查洛伦兹力项与电场项的平衡关系
    balance_logic = any(x in text for x in ["平衡", "steady state", "equilibrium", "="])

    if found_drag and balance_logic:
        if wrong_drag:
            return {"result": "fail", "message": "阻力项符号错误，应为负号（与速度方向相反）", "evidence": wrong_drag.group()}

        # 检查分量形式 eEx = evyB + mvx/tau 或类似变体
        # 简化逻辑：如果公式中出现了 qE, qvB 和 mv/tau 且符号逻辑自洽则 pass
        if "=" in text:
            return {"result": "pass", "message": "稳态平衡方程逻辑基本符合物理规律", "evidence": "found drag and balance terms"}

    return {"result": "inconclusive", "message": "无法确定平衡方程的准确性", "evidence": ""}

# rule_id=exp_d38b38b135ca1695 | domain=Electromagnetism | topic=Electromagnetism / Magnetic Fields and Lorentz Force
def check_exp_d38b38b135ca1695_a6cb32fe1f5b(sample: dict) -> dict:


    text = sample.get('prediction', '') + ' ' + sample.get('answer', '')

    # 提取数值的辅助正则
    def find_val(pattern, text):
        match = re.search(pattern, text)
        if match:
            try:
                return float(match.group(1))
            except:
                return None
        return None

    # 尝试匹配 r=... 和 l=...
    r_val = find_val(r'[rR]\s*=\s*([0-9\.]+)', text)
    l_val = find_val(r'[lL]\s*=\s*([0-9\.]+)', text)

    if r_val is None or l_val is None:
        return {
            "result": "inconclusive",
            "message": "未在文本中提取到明确的半径 r 或间距 l 的数值",
            "evidence": ""
        }

    # 校验逻辑: r = l / sqrt(2)
    expected_r = l_val / math.sqrt(2)

    # 允许 5% 的误差
    if abs(r_val - expected_r) / expected_r < 0.05:
        return {
            "result": "pass",
            "message": "半径与间距满足垂直进出的几何关系 r = l/sqrt(2)",
            "evidence": "r=" + str(r_val) + ", l=" + str(l_val)
        }
    else:
        return {
            "result": "fail",
            "message": "半径与间距不符合垂直进出的几何约束，预期 r = " + str(round(expected_r, 4)),
            "evidence": "r=" + str(r_val) + ", l=" + str(l_val)
        }

# rule_id=exp_d62bcd92fb6c2327 | domain=Electromagnetism | topic=Electromagnetism / Magnetic Fields and Lorentz Force
def check_exp_d62bcd92fb6c2327_b6123ec3190e(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测文本为空', 'evidence': ''}

    # 寻找包含 M, e, B, r, U 的表达式片段
    # 目标结构: M = (q*B^2*r^2) / (2U) 或类似变体
    # 匹配分子部分: 包含 e/q, B^2, r^2
    # 匹配分母部分: 包含 U, 2
    patterns = [
        r'M\s*=\s*.*?e.*?B\^2.*?r\^2.*?/.*?2.*?U',
        r'M\s*=\s*.*?q.*?B\^2.*?r\^2.*?/.*?2.*?U',
        r'm\s*=\s*.*?q.*?B\^2.*?r\^2.*?/.*?2.*?U',
        r'm\s*=\s*.*?e.*?B\^2.*?r\^2.*?/.*?2.*?U',
        r'M\s*\propto\s*.*?e.*?B\^2.*?r\^2.*?/.*?U'
    ]

    found_match = False
    evidence = ''
    for p in patterns:
        match = re.search(p, prediction, re.IGNORECASE)
        if match:
            found_match = True
            evidence = match.group(0)
            break

    if found_match:
        return {'result': 'pass', 'message': '公式比例结构符合质谱仪基本方程', 'evidence': evidence}

    # 检查是否存在错误的比例关系，例如 B 或 r 没有平方，或者 U 在分子上
    wrong_patterns = [
        r'M\s*=\s*.*?e.*?B.*?r.*?/.*?U', # 缺少平方
        r'M\s*=\s*.*?U.*?/.*?B\^2',
        r'M\s*=\s*.*?e.*?B\^2.*?r\^2.*?U' # U在分子
    ]
    for wp in wrong_patterns:
        if re.search(wp, prediction, re.IGNORECASE):
            return {'result': 'fail', 'message': '公式比例结构错误，请检查B、r的幂次或U的位置', 'evidence': re.search(wp, prediction, re.IGNORECASE).group(0)}

    return {'result': 'inconclusive', 'message': '未在预测中找到明确的质量M表达式', 'evidence': ''}

# rule_id=exp_d7f1c3a3eb6a1dae | domain=Electromagnetism | topic=Electromagnetism / Magnetic Fields and Lorentz Force
def check_exp_d7f1c3a3eb6a1dae_f5ccd1bd857c(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
