    text_to_check = (question + ' ' + prediction).lower()

    # 检查是否涉及负电荷（电子）在磁场中的运动
    is_negative_charge = any(kw in text_to_check for kw in ['electron', '电子', 'negative charge', '负电荷'])
    is_magnetic_moment = any(kw in text_to_check for kw in ['magnetic moment', '磁矩', '\\mu', 'mu'])
    is_magnetic_field = any(kw in text_to_check for kw in ['magnetic field', '磁场', ' B '])

    if not (is_negative_charge and is_magnetic_moment and is_magnetic_field):
        return {"result": "inconclusive", "message": "未识别到负电荷磁矩计算场景", "evidence": ""}

    # 检查公式或描述中是否体现了磁矩与磁场方向相反 (mu = -...B 或 opposite/相反)
    # 匹配模式如 \vec{\mu} = -...
    has_negative_relation = '-' in prediction or 'opposite' in prediction or '相反' in prediction or '反向' in prediction

    # 检查公式特征
    formula_pattern = re.compile(r'\\mu.*=.*-.*B')
    has_formula_match = bool(formula_pattern.search(prediction))

    if is_negative_charge:
        if has_negative_relation or has_formula_match:
            return {"result": "pass", "message": "正确识别负电荷磁矩与外磁场方向相反", "evidence": "识别到负号或相反方向描述"}
        else:
            # 如果明确讨论了方向但没有体现相反关系，则判定为错误
            if any(kw in prediction.lower() for kw in ['same', 'parallel', '相同', '同向', '平行']):
                return {"result": "fail", "message": "负电荷等效磁矩方向应与外磁场相反，而非相同", "evidence": prediction}
            return {"result": "inconclusive", "message": "无法确定磁矩方向判定逻辑", "evidence": ""}

    return {"result": "inconclusive", "message": "不满足判定条件", "evidence": ""}

