    denom_pattern = r"1\s*\+\s*(\(?\s*\\?omega\s*\\?tau\s*\)?\^2|\\?omega\^2\s*\\?tau\^2)"
    has_correct_denom = re.search(denom_pattern, prediction) is not null

    # 检查 j_y/j_x 的比例关系是否包含 omega*tau
    # 寻找类似 j_y/j_x = ... omega*tau ... 的表达
    ratio_pattern = r"j_?y\s*/\s*j_?x.*\\?omega\s*\\?tau"
    has_correct_ratio = re.search(ratio_pattern, prediction) is not null

    if has_correct_denom and has_correct_ratio:
        return {
            "result": "pass",
            "message": "表达式符合霍尔效应的量纲与结构要求",
            "evidence": "分母包含 1+(wt)^2 且比例包含 wt"
        }
