# rule_id=exp_0977f479838db497 | domain=Electromagnetism | topic=Electromagnetism / Poynting Vector and Radiation Pressure
def check_exp_0977f479838db497_0e6ecab1e54c(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 寻找分母中类似 10^a * 10^b 或 10^{a} * 10^{b} 的结构
    pattern = r'10\^\{?(-?\d+)\}?\s*\*\s*10\^\{?(-?\d+)\}?'
    matches = re.findall(pattern, prediction)

    if not matches:
        return {"result": "inconclusive", "message": "未在预测中发现复合幂次乘积结构", "evidence": ""}

    for match in matches:
        exp1, exp2 = int(match[0]), int(match[1])
        expected_sum = exp1 + exp2
        # 寻找紧随其后的结果，如 10^{sum}
        result_pattern = r'10\^\{?(' + str(expected_sum) + r')\}?'
        context_after = prediction[prediction.find(match[1]):prediction.find(match[1])+50]

        # 如果发现了乘积形式但后续计算出的指数不匹配（且存在明显的指数结果汇报）
        wrong_result_pattern = r'10\^\{?(-?\d+)\}?'
        all_results = re.findall(wrong_result_pattern, context_after)

        # 排除掉 match 里的两个指数
        for res_exp in all_results:
            res_val = int(res_exp)
            if res_val != exp1 and res_val != exp2:
                if res_val != expected_sum:
                    return {
                        "result": "fail",
                        "message": "幂次合并计算错误：10^" + str(exp1) + " * 10^" + str(exp2) + " 不等于 10^" + str(res_val),
                        "evidence": "10^" + str(exp1) + " * 10^" + str(exp2) + " -> 10^" + str(res_val)
                    }
                else:
                    return {
                        "result": "pass",
                        "message": "幂次合并计算正确",
                        "evidence": "10^" + str(exp1) + " * 10^" + str(exp2) + " = 10^" + str(expected_sum)
                    }

    return {"result": "inconclusive", "message": "发现幂次项但未提取到明确的合并计算结果", "evidence": ""}

