# rule_id=exp_51d784e1fbba376e | domain=Electromagnetism | topic=Electromagnetism / Poynting Vector and Radiation Pressure
def check_exp_51d784e1fbba376e_ee99bb160f66(sample: dict) -> dict:

    prediction = sample.get('prediction', '')

    # 触发词检查：坡印廷矢量、动量密度、Poynting
    trigger_keywords = ['坡印廷', 'Poynting', '动量密度', 'momentum density']
    if not any(kw in prediction for kw in trigger_keywords):
        return {"result": "inconclusive", "message": "未检测到坡印廷矢量或动量密度相关讨论", "evidence": ""}

    # 核心公式模式：p = S/c^2 或 p = epsilon_0 * (E x B)
    # 匹配 p = S/c^2 及其变体
    pattern_s_c2 = re.compile(r'p(_V)?\s*=\s*S\s*/\s*c(\^2|\*\*2|2)')
    # 匹配 p = epsilon_0 * E * B 或 p = epsilon_0 * (E x B)
    pattern_eps_eb = re.compile(r'p(_V)?\s*=\s*epsilon(_0)?\s*\*?\s*\(?E\s*[xX*]\s*B\)?')
    # 匹配 S = p * c^2
    pattern_s_pc2 = re.compile(r'S\s*=\s*p(_V)?\s*\*?\s*c(\^2|\*\*2|2)')

    # 错误模式：如 p = S/c 或 p = S*c^2
    wrong_pattern = re.compile(r'p(_V)?\s*=\s*S\s*([*/])\s*c(?!(\^2|\*\*2|2))')

    if pattern_s_c2.search(prediction) or pattern_eps_eb.search(prediction) or pattern_s_pc2.search(prediction):
        return {"result": "pass", "message": "动量密度与坡印廷矢量的转换公式正确", "evidence": "命中正确物理公式"}

    if wrong_pattern.search(prediction):
        return {"result": "fail", "message": "动量密度与坡印廷矢量的转换系数错误，应为c^2", "evidence": "检测到错误的c幂次关系"}

    return {"result": "inconclusive", "message": "无法确定公式准确性", "evidence": ""}

# rule_id=exp_349c029794fc971b | domain=Electromagnetism | topic=Electromagnetism / RL, RC, and RLC Circuits
def check_exp_349c029794fc971b_879c226aabde(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 检查是否包含RL回路的关键物理量符号
    required_symbols = ['L', 'i', 'R']
    missing_symbols = [s for s in required_symbols if s not in prediction]
    if missing_symbols:
        return {'result': 'inconclusive', 'message': '未检测到必要的物理量符号', 'evidence': ''}

    # 匹配 di/dt 的各种表达形式
    di_dt_patterns = [r'di/dt', r'dI/dt', r'i\'', r'I\'', r'\\dot{i}', r'\\dot{I}']
    has_derivative = any(re.search(p, prediction) for p in di_dt_patterns)

    # 匹配方程核心结构：E = L(di/dt) + iR 或其变体
    # 允许符号在等号两边移动，但 L(di/dt) 和 iR 应该在同一侧或符合平衡关系
    # 模式1: E = L*di/dt + i*R
    # 模式2: L*di/dt + i*R = E
    # 模式3: E - L*di/dt - i*R = 0
    patterns = [
        r'[E|U|V].*=[^=]*(L.*d[iI]/dt|L.*[iI]\').*[\+|\-].*[iI].*R',
        r'(L.*d[iI]/dt|L.*[iI]\').*[\+|\-].*[iI].*R.*=[^=]*[E|U|V]',
        r'[E|U|V].*-[^=]*(L.*d[iI]/dt|L.*[iI]\').*=[^=]*[iI].*R'
    ]

    found_match = False
    evidence = ''
    for p in patterns:
        match = re.search(p, prediction)
        if match:
            found_match = True
            evidence = match.group(0)
            break

    if found_match:
        return {'result': 'pass', 'message': '符合RL回路电动势平衡方程', 'evidence': evidence}

    # 如果提到了L, i, R但没有写出正确的方程结构，判定为逻辑错误
    if has_derivative and ('L' in prediction and 'R' in prediction):
        return {'result': 'fail', 'message': 'RL回路方程表达不正确或符号逻辑错误', 'evidence': prediction[:100]}

    return {'result': 'inconclusive', 'message': '无法确定方程是否符合RL回路平衡判定', 'evidence': ''}

