# rule_id=exp_a0646bab23354fce | domain=Electromagnetism | topic=Electromagnetism / RL, RC, and RLC Circuits
def check_exp_a0646bab23354fce_0ead6c3dd94e(sample: dict) -> dict:

    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()

    # Trigger detection
    nonlinear_elements = ['thyristor', 'element x', 'neon lamp', 'diac', 'nonlinear']
    has_nonlinear = any(elem in question for elem in nonlinear_elements)
    has_rc = 'rc' in question or ('resistor' in question and 'capacitor' in question)
