# rule_id=exp_ae64e10386317bab | domain=Mechanics | topic=Mechanics / Angular Momentum Conservation
def check_exp_ae64e10386317bab_9a49bfae61ac(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 检查是否涉及角动量守恒导致的动能变化 (r1/r2)^2 或类似的比例关系
    # 以及势能增量 mgh 或 mg\Delta h
    energy_inc_pattern = re.compile(r'(\\Delta E|E_2\\s*-\\s*E_1|\\Delta K|\\Delta U)', re.IGNORECASE)
    ratio_pattern = re.compile(r'(\(r_1/r_2\\)\^2|r_1\\^2/r_2\\^2|v_1\\^2.*r_1\\^2/r_2\\^2)', re.IGNORECASE)
    potential_pattern = re.compile(r'(mg\\Delta h|mgh|mg\\(L-l\\))', re.IGNORECASE)

    has_energy = bool(energy_inc_pattern.search(prediction))
    has_ratio = bool(ratio_pattern.search(prediction))
    has_potential = bool(potential_pattern.search(prediction))

    # 如果讨论了能量变化但忽略了势能或动能比例项，则可能存在概念错误
    if has_energy:
        if not has_ratio and not has_potential:
            return {
                'result': 'fail',
                'message': '机械能增量校验失败：未发现动能增量（角动量守恒项）或势能增量的正确表达。',
                'evidence': prediction[:100]
            }
        if has_ratio and has_potential:
            return {
                'result': 'pass',
                'message': '机械能增量校验通过：包含了动能增量和势能增量。',
                'evidence': 'found ratio and potential terms'
            }

    return {'result': 'inconclusive', 'message': '未检测到明确的能量增量计算逻辑', 'evidence': ''}

# rule_id=exp_cdfc082ba633af27 | domain=Mechanics | topic=Mechanics / Angular Momentum Conservation
def check_exp_cdfc082ba633af27_b7e814123841(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 匹配角动量守恒的核心物理量：转动惯量 I, 质量 m, 半径 R, 速度 v 或 角速度 omega
    # 重点寻找 L = (I + mR^2)w 这种形式的表达式
    patterns = [
        r'L\s*=\s*\(I\s*\+\s*m\*?R\^2\)\s*\*?\s*\\?omega',
        r'\\?omega\s*=\s*.*L.*/\s*\(I\s*\+\s*m\*?R\^2\)',
        r'I_total\s*=\s*I\s*\+\s*m\*?R\^2',
        r'm\*?v\*?R\s*=\s*\(I\s*\+\s*m\*?R\^2\)'
    ]

    found_match = False
    evidence = ''
    for p in patterns:
        match = re.search(p, prediction, re.IGNORECASE)
        if match:
            found_match = True
            evidence = match.group(0)
            break

    if found_match:
        # 检查是否正确应用了 I + mR^2 的逻辑
        if 'm' in evidence and 'R' in evidence and 'I' in evidence:
            return {'result': 'pass', 'message': '正确识别并应用了非弹性吸附过程的角动量分配公式', 'evidence': evidence}
        else:
            return {'result': 'fail', 'message': '公式中缺少必要的物理量(I, m, R)', 'evidence': evidence}

    # 如果文本中提到了角动量守恒但没有写出正确公式，可能存在建模错误
    if '角动量' in prediction and ('守恒' in prediction or '分配' in prediction):
        if 'm*R^2' not in prediction.replace(' ', ''):
            return {'result': 'fail', 'message': '未正确考虑附加质量产生的转动惯量增量 mR^2', 'evidence': '角动量守恒相关描述'}

    return {'result': 'inconclusive', 'message': '未发现明确的角动量分配计算逻辑', 'evidence': ''}

# rule_id=exp_f6022f6dffb1e18f | domain=Mechanics | topic=Mechanics / Angular Momentum Conservation
def check_exp_f6022f6dffb1e18f_7216c28161a6(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    # 触发词：方木、棱柱、矩形、翻滚、碰撞、转动
    trigger_keywords = ['方木', '棱柱', '矩形', '翻滚', '碰撞', '转动', '绕点', '角动量']
    is_triggered = any(kw in question for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到非圆截面物体碰撞转动场景", "evidence": ""}

    # 检查逻辑：是否应用了角动量守恒 L_before = L_after 或 I1w1 = I2w2
    # 匹配模式：L1=L2, I*w=I*w, 角动量守恒, Mvr + Iw
    patterns = [
        r'L_?[1i]\s*=\s*L_?[2f]',
        r'I_?.*?\\omega_?.*?\s*=\s*I_?.*?\\omega_?.*?',
        r'角动量守恒',
        r'mvr\s*\+\s*I\\omega',
        r'I_?.*?\\omega.*?cos'
    ]

    found_logic = False
    evidence = ""
    for pattern in patterns:
        match = re.search(pattern, prediction, re.IGNORECASE)
        if match:
            found_logic = True
            evidence = match.group(0)
            break

    if found_logic:
        return {"result": "pass", "message": "正确应用了碰撞瞬间的角动量守恒律", "evidence": evidence}
    else:
        # 如果题目明确要求计算碰撞后的速度/角速度但没提到角动量守恒，则可能存在概念错误
        if '角速度' in question or '速度' in question:
            return {"result": "fail", "message": "在非圆截面物体碰撞中未发现角动量守恒的应用", "evidence": ""}

    return {"result": "inconclusive", "message": "无法确定是否应用了角动量守恒律", "evidence": ""}

# rule_id=exp_00eb95441f994be3 | domain=Mechanics | topic=Mechanics / Center of Mass and Motion of Extended Bodies
def check_exp_00eb95441f994be3_5a0ba159e92c(sample: dict) -> dict:

    text = (sample.get('question', '') + ' ' + sample.get('prediction', '')).lower()

    # 触发条件：涉及人船模型、相对运动、位移计算
    trigger_keywords = ['人船模型', '船', '位移', '相对运动', '走动', '移动']
    is_triggered = any(kw in text for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "pass", "message": "未涉及人船模型相关场景", "evidence": ""}

    # 检查逻辑：是否存在地面摩擦力或阻力（与速度相关的外力）
    # 人船模型要求水平方向动量守恒（合外力为0）
    friction_keywords = ['摩擦力', '阻力', '粘滞', 'f=', 'kv', '阻碍']
    has_friction = any(kw in text for kw in friction_keywords)

    # 检查是否错误使用了人船模型公式 (m1*x1 = m2*x2 或类似变体)
    formula_pattern = r'm[1a]\s*x[1a]\s*=\s*m[2b]\s*x[2b]'
    has_formula = re.search(formula_pattern, text) is not None

    if has_friction:
        # 如果存在摩擦力，但解题过程中使用了人船模型公式，则判定为建模错误
        if has_formula or '质心不变' in text or '动量守恒' in text:
            return {
                "result": "fail",
                "message": "存在地面摩擦力或阻力时，系统水平方向合外力不为零，不能直接使用人船模型公式。",
                "evidence": "检测到摩擦力相关描述且使用了质心位移公式"
            }
        else:
            return {"result": "pass", "message": "存在摩擦力时未误用人船模型", "evidence": ""}

    return {"result": "inconclusive", "message": "无法确定系统受力情况是否满足人船模型边界", "evidence": ""}

# rule_id=exp_36ae2d8c062c5e57 | domain=Mechanics | topic=Mechanics / Center of Mass and Motion of Extended Bodies
def check_exp_36ae2d8c062c5e57_66567135e343(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 检查是否符合触发条件：阻力与速度成正比 (f=-kv) 且初末状态为静止
    trigger_keywords = ['阻力', '速度成正比', 'kv', 'k*v', 'f=-kv']
    state_keywords = ['静止', '停止', '初速度为0', '末速度为0']

    is_triggered = any(k in question or k in prediction for k in trigger_keywords) and \
                   (any(s in question for s in state_keywords) or 'v=0' in question)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未识别到阻力系统或初末静止状态", "evidence": ""}

    # 检查逻辑：位移是否为0
    # 寻找位移相关的描述，如 delta x = 0, 位移为0, 回到原点等
    displacement_zero_patterns = [
        r'位移(为|等于)0',
        r'总位移(为|等于)0',
        r'\\Delta x\\s*=\\s*0',
        r'x\\s*=\\s*0',
        r'回到(出发点|原点)',
        r'displacement\\s*is\\s*0'
    ]

    found_zero_displacement = False
    for pattern in displacement_zero_patterns:
        if re.search(pattern, prediction):
            found_zero_displacement = True
            break

    # 如果预测中提到了位移不为0，或者计算出了一个非零数值，则判定为逻辑错误
    displacement_nonzero_patterns = [
        r'位移(不为|不等于)0',
        r'\\Delta x\\s*\\neq\\s*0',
        r'位移为\\s*[1-9]'
    ]

    for pattern in displacement_nonzero_patterns:
        if re.search(pattern, prediction):
            return {"result": "fail", "message": "在仅受线性阻力且初末动量为0时，总位移应为0", "evidence": re.search(pattern, prediction).group()}

    if found_zero_displacement:
        return {"result": "pass", "message": "正确识别总位移为0", "evidence": "位移为0"}

    return {"result": "inconclusive", "message": "未能明确判断位移结论", "evidence": ""}

# rule_id=exp_10b7df8a0c1d93cf | domain=Mechanics | topic=Mechanics / Circular Motion and Centripetal Force
def check_exp_10b7df8a0c1d93cf_1aad4e0288ed(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 匹配错误的静态平衡假设：T = mg/cos(theta) 或 T = mg*cos(theta)
    # 这种假设忽略了向心力 mv^2/R
    error_patterns = [
        r'T\s*=\s*m\s*g\s*/\s*cos',
        r'T\s*=\s*m\s*g\s*\\cos',
        r'T\s*=\s*m\s*g\s*cos'
    ]

    # 匹配正确的动力学方程：T - mg cos(theta) = m v^2 / R
    correct_pattern = r'T\s*-\s*m\s*g\s*(cos|\\cos).*=\s*m\s*v\^2\s*/'

    found_error = False
    evidence = ""
    for pattern in error_patterns:
        match = re.search(pattern, prediction, re.IGNORECASE)
        if match:
            found_error = True
            evidence = match.group(0)
            break

    if found_error:
        # 进一步检查是否在同一上下文中补救了动力学项，如果没有则判定为概念错误
        if not re.search(correct_pattern, prediction, re.IGNORECASE):
            return {
                "result": "fail",
                "message": "错误地将圆周运动径向力等效为静力平衡(T=mg cosθ或T=mg/cosθ)，忽略了向心力项。",
                "evidence": evidence
            }

    # 如果文本中包含相关物理量但没有明显的错误公式，或者逻辑复杂，返回不确定
    if 'T' in prediction and 'm' in prediction and ('cos' in prediction or 'theta' in prediction):
        if re.search(correct_pattern, prediction, re.IGNORECASE):
            return {
                "result": "pass",
                "message": "正确使用了圆周运动径向动力学方程。",
                "evidence": ""
            }
        return {"result": "inconclusive", "message": "检测到受力分析但无法确定公式准确性", "evidence": ""}

    return {"result": "inconclusive", "message": "未检测到相关的径向受力计算公式", "evidence": ""}

# rule_id=exp_3540497a51d17abe | domain=Mechanics | topic=Mechanics / Circular Motion and Centripetal Force
def check_exp_3540497a51d17abe_bb8d9b1a03e2(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 匹配隐函数求导的特征模式，例如 2x*dx/dt + 2y*dy/dt = 0 或类似的微分形式
    # 考虑到符号多样性，匹配包含变量、导数项且等号右侧为0或常数的结构
    patterns = [
        r'2\s*x\s*\*?\s*d\s*x\s*/\s*d\s*t\s*\+\s*2\s*y\s*\*?\s*d\s*y\s*/\s*d\s*t\s*=\s*0',
        r'x\s*\*?\s*v_x\s*\+\s*y\s*\*?\s*v_y\s*=\s*0',
        r'x\s*\*?\s*\\dot\{x\}\s*\+\s*y\s*\*?\s*\\dot\{y\}\s*=\s*0',
        r'd\s*\(\s*x\^2\s*\+\s*y\^2\s*\)\s*/\s*d\s*t\s*=\s*0'
    ]

    found_implicit_diff = False
    evidence = ""
    for p in patterns:
        match = re.search(p, prediction, re.IGNORECASE)
        if match:
            found_implicit_diff = True
            evidence = match.group(0)
            break

    # 如果预测中出现了复杂的根式求导（如 d/dt sqrt(R^2-x^2)），则可能违反了“避免解出复杂根式”的建议
    radical_diff_pattern = r'd\s*/\s*d\s*t\s*\\?sqrt\('
    has_radical_diff = re.search(radical_diff_pattern, prediction, re.IGNORECASE)

    if found_implicit_diff:
        return {
            "result": "pass",
            "message": "检测到使用了隐函数全微分方法，符合减少代数运算错误的建议。",
            "evidence": evidence
        }
    elif has_radical_diff:
        return {
            "result": "fail",
            "message": "检测到直接对复杂根式求导，建议使用隐函数全微分以减少错误。",
            "evidence": has_radical_diff.group(0)
        }
    else:
        return {
            "result": "inconclusive",
            "message": "未在预测中识别到明确的隐函数求导或根式求导过程。",
            "evidence": ""
        }

# rule_id=exp_3dbeb06a9b454677 | domain=Mechanics | topic=Mechanics / Circular Motion and Centripetal Force
def check_exp_3dbeb06a9b454677_eaf243645302(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 检查是否包含能量守恒相关的速度平方项 v^2 = 2gh 或 v^2 = 2gL cos theta
    energy_pattern = r'v\^2\s*=\s*2g[hL]|v\^2\s*=\s*2gL\s*cos\s*\\?theta'
    # 检查是否包含向心力公式 T = mg cos theta + mv^2/L
    force_pattern = r'T\s*=\s*mg\s*cos\s*\\?theta\s*\+\s*m\s*v\^2\s*/\s*L|T\s*-\s*mg\s*cos\s*\\?theta\s*=\s*m\s*v\^2\s*/\s*L'

    has_energy = re.search(energy_pattern, prediction)
    has_force = re.search(force_pattern, prediction)

    if has_energy and has_force:
        return {
            "result": "pass",
            "message": "预测中包含了机械能守恒求速度平方以及向心力公式的关联逻辑",
            "evidence": f"{has_energy.group()} ; {has_force.group()}"
        }
    elif has_energy or has_force:
        return {
            "result": "fail",
            "message": "预测中仅包含能量守恒或向心力公式之一，未完整体现关联准则",
            "evidence": has_energy.group() if has_energy else has_force.group() if has_force else ""
        }

    return {
        "result": "inconclusive",
        "message": "未在预测中识别到相关的物理公式模式",
        "evidence": ""
    }

# rule_id=exp_501b34c43ec7550b | domain=Mechanics | topic=Mechanics / Circular Motion and Centripetal Force
def check_exp_501b34c43ec7550b_a12983dcd37a(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()

    trigger_keywords = ['最小静摩擦系数', '不下滑', '不滑落', 'minimum friction', 'no slip', 'no-slip', '静摩擦系数']
    is_triggered = any(kw in question for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未触发临界摩擦力平衡判定规则", "evidence": ""}

    frictionless_formula = ['tan', 'v^2/rg', 'v^2/(rg)', 'v**2/(r*g)']
    has_frictionless_logic = any(f in prediction.replace(' ', '') for f in frictionless_formula)

    friction_logic = ['mu', 'μ', 'f=', 'f =', 'f_max', '摩擦力']
    has_friction_logic = any(fl in prediction for fl in friction_logic)

    if has_frictionless_logic and not has_friction_logic:
        return {
            "result": "fail",
            "message": "可能误用了无摩擦平衡公式 tan θ = v²/Rg，未考虑静摩擦力的贡献",
            "evidence": prediction
        }

    if 'mu' in prediction or 'μ' in prediction:
        if '>=' in prediction or '<=' in prediction or '=' in prediction:
            return {
                "result": "pass",
                "message": "识别到摩擦系数相关的临界条件计算",
                "evidence": prediction
            }

    return {"result": "inconclusive", "message": "无法确定是否正确应用了摩擦力平衡逻辑", "evidence": ""}

# rule_id=exp_a7796c66a11f332f | domain=Mechanics | topic=Mechanics / Circular Motion and Centripetal Force
def check_exp_a7796c66a11f332f_ee89b25917bc(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 检查是否涉及圆周运动或向心加速度场景
    keywords = ['圆周', '轨道', '向心加速度', 'circular', 'centripetal']
    is_relevant = any(k in question or k in prediction for k in keywords)
    if not is_relevant:
        return {"result": "inconclusive", "message": "未识别到圆周运动相关场景", "evidence": ""}

    # 检查是否使用了二阶导数投影的复杂方法（通常表现为对坐标x,y求二阶导）
    complex_pattern = re.compile(r"d\^2[xy]/dt\^2|\\ddot\{[xy]\}")
    has_complex_method = bool(complex_pattern.search(prediction))

    # 检查是否使用了推荐的 a = v^2/R 模式
    # 匹配 a = v^2/R 或 a = (vx^2 + vy^2)/R 等变体
    simple_pattern = re.compile(r"a(_c)?\s*=\s*v\^2\s*/\s*R|a(_c)?\s*=\s*\(v_x\^2\s*\+\s*v_y\^2\)\s*/\s*R")
    has_simple_method = bool(simple_pattern.search(prediction))

    if has_complex_method and not has_simple_method:
        return {
            "result": "fail",
            "message": "优先使用 a_c = v^2/R 公式，避免对坐标分量进行二次求导后再投影。",
            "evidence": complex_pattern.search(prediction).group()
        }
    elif has_simple_method:
        return {
            "result": "pass",
            "message": "正确使用了向心加速度简化公式。",
            "evidence": simple_pattern.search(prediction).group()
        }

    return {"result": "inconclusive", "message": "未检测到明确的加速度计算公式", "evidence": ""}

# rule_id=exp_b7886f351065b520 | domain=Mechanics | topic=Mechanics / Circular Motion and Centripetal Force
def check_exp_b7886f351065b520_dd25b38d2bdb(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 触发条件检查：旋转圆环、橡皮筋、细绳、径向扩张
    trigger_keywords = ['圆环', '橡皮筋', '细绳', '旋转', '扩张', '半径', '张力']
    is_triggered = any(kw in question for kw in trigger_keywords) or any(kw in prediction for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到圆环旋转受力相关场景", "evidence": ""}

    # 核心逻辑检查：微元法、张力分量、向心力平衡
    # 检查是否包含 T = m*omega^2*r / 2pi 或类似的平衡关系
    # 匹配 T = (M/2π) * ω²r 的变体
    patterns = [
        r'T\s*=\s*.*M.*ω.*r.*2π',
        r'2T.*sin.*dθ',
        r'T.*dθ.*dm.*ω.*r',
        r'T\s*=\s*m.*v\^2.*2π.*r',
        r'T\s*=\s*m.*ω\^2.*r.*2.*pi'
    ]

    found_logic = False
    matched_evidence = ""
    for pattern in patterns:
        match = re.search(pattern, prediction, re.IGNORECASE)
        if match:
            found_logic = True
            matched_evidence = match.group(0)
            break

    if found_logic:
        return {
            "result": "pass",
            "message": "模型符合圆环旋转受力平衡逻辑",
            "evidence": matched_evidence
        }
    else:
        # 如果提到了旋转圆环但没有正确的张力公式推导，判定为建模错误
        if 'T' in prediction and ('ω' in prediction or 'omega' in prediction):
            return {
                "result": "fail",
                "message": "未发现正确的圆环张力与向心力平衡建模公式 (T = Mω²r/2π)",
                "evidence": ""
            }

    return {"result": "inconclusive", "message": "无法确定建模逻辑是否正确", "evidence": ""}

# rule_id=exp_be5504b6afc50ca7 | domain=Mechanics | topic=Mechanics / Circular Motion and Centripetal Force
def check_exp_be5504b6afc50ca7_4de00d84efad(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 匹配张力 T 与周长伸长量 2π(r-R) 的关系式
    # 允许的变体包括 T=k*2*pi*(r-R), T=k*2π(r-R), T=k*delta_L 等
    patterns = [
        r'T\s*=\s*k\s*\*?\s*2\s*π\s*\(?r\s*-\s*R\)?',
        r'T\s*=\s*k\s*\*?\s*2\s*pi\s*\(?r\s*-\s*R\)?',
        r'T\s*=\s*k\s*\*?\s*ΔL',
        r'T\s*=\s*k\s*\*?\s*\(2πr\s*-\s*2πR\)'
    ]

    # 检查是否存在错误的定义，例如 T = k * (r - R) 忽略了 2π
    error_patterns = [
        r'T\s*=\s*k\s*\*?\s*\(r\s*-\s*R\)',
        r'T\s*=\s*k\s*\*?\s*Δr'
    ]

    found_correct = any(re.search(p, prediction, re.IGNORECASE) for p in patterns)
    found_error = any(re.search(p, prediction, re.IGNORECASE) for p in error_patterns)

    if found_correct:
        return {
            "result": "pass",
            "message": "正确使用了弹性圆环劲度系数与周长伸长量的关系",
            "evidence": ""
        }
    elif found_error:
        return {
            "result": "fail",
            "message": "错误地将劲度系数作用于半径变化而非周长变化",
            "evidence": "T = k * (r - R)"
        }

    return {
        "result": "inconclusive",
        "message": "未在预测中找到明确的张力计算公式",
        "evidence": ""
    }

# rule_id=exp_39a3e8c055eac221 | domain=Mechanics | topic=Mechanics / Dynamics of Systems of Particles
def check_exp_39a3e8c055eac221_95702ce860e4(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 检查是否触发：题目中是否存在非二次型动能或色散关系描述
    trigger_keywords = ['E(k)', 'K(p)', 'dispersion relation', '色散关系', '动能公式']
    is_triggered = any(kw in question or kw in prediction for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到非标准色散关系触发词", "evidence": ""}

    # 检查逻辑：是否错误地直接使用了 F=ma (或 a=F/m)
    # 且没有体现 v=dK/dp 或 a=(d2K/dp2)F 的链式求导过程
    direct_fma = re.search(r'a\s*=\s*F\s*/\s*m', prediction)
    chain_rule_indicators = ['dv/dp', 'd^2K/dp^2', 'dK/dp', 'diff(K, p)', 'derivative']

    has_chain_rule = any(ind in prediction for ind in chain_rule_indicators)

    if direct_fma and not has_chain_rule:
        return {
            "result": "fail",
            "message": "在非标准色散关系下错误地直接套用了F=ma，未通过链式求导计算加速度",
            "evidence": direct_fma.group(0)
        }

    if has_chain_rule:
        return {
            "result": "pass",
            "message": "检测到使用了链式求导或动量导数处理加速度",
            "evidence": "found chain rule indicators"
        }

    return {"result": "inconclusive", "message": "无法确定加速度计算逻辑是否正确", "evidence": ""}

# rule_id=exp_f49fb1ea29c44d11 | domain=Mechanics | topic=Mechanics / Dynamics of Systems of Particles
def check_exp_f49fb1ea29c44d11_04580062688e(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
