    # 触发词检查：准粒子、电磁场、K-p关系、色散关系
    trigger_keywords = ['准粒子', 'quasiparticle', '色散关系', 'dispersion', 'K-p', '动量', 'momentum']
    is_triggered = any(kw in question or kw in prediction for kw in trigger_keywords)

