# rule_id=exp_0bef14df033d965d | domain=Mechanics | topic=Mechanics / Elasticity and Hooke's Law
def check_exp_0bef14df033d965d_105e09270bb4(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 定义关键物理量和公式模式
    # 目标公式: K = (1/24) * m * L^2 * (dε/dt)^2
    # 匹配 1/24, m, L^2, 以及应变率的平方 (dot{epsilon}^2 或 (de/dt)^2)
    patterns = [
        r'1/24',
        r'm.*L\^2',
        r'\\dot{\\varepsilon}',
        r'd\\varepsilon/dt'
    ]

    # 检查是否包含积分过程或最终公式的关键特征
    has_m = 'm' in prediction
    has_L = 'L' in prediction
    has_coeff = '1/24' in prediction or '24' in prediction

    # 匹配核心公式结构
    formula_match = re.search(r'1/24.*m.*L\^2.*(\\dot{\\varepsilon}|d\\varepsilon/dt)\^2', prediction)

    if formula_match:
        return {
            'result': 'pass',
            'message': '检测到正确的均匀伸缩连续体动能建模公式',
            'evidence': formula_match.group(0)
        }

    # 如果提到了动能建模但系数或形式不对
    if ('kinetic' in prediction.lower() or '动能' in prediction) and (has_m and has_L):
        if '1/2' in prediction and '1/24' not in prediction:
            return {
                'result': 'fail',
                'message': '动能建模错误：均匀伸缩连续体的积分系数应为1/24而非质点模型的1/2',
                'evidence': '1/2'
            }

    return {
        'result': 'inconclusive',
        'message': '未发现明确的均匀伸缩动能建模公式',
        'evidence': ''
    }

# rule_id=exp_23517eb6d5a909b6 | domain=Mechanics | topic=Mechanics / Elasticity and Hooke's Law
def check_exp_23517eb6d5a909b6_8f102680e531(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': 'No prediction found', 'evidence': ''}

    # 检查是否涉及 eV 和 N/m 或 J 的转换场景
    if not (('eV' in prediction.lower()) and ('j' in prediction.lower() or 'n/m' in prediction.lower())):
        return {'result': 'inconclusive', 'message': 'No eV to SI conversion detected', 'evidence': ''}

    # 查找是否存在 1.602e-19 或类似的换算因子
    conversion_factor_pattern = r'1\.602\s*[x*×]\s*10\s*\^?\s*\-?\s*19'
    has_conversion = re.search(conversion_factor_pattern, prediction)

    # 查找是否存在直接将 eV 数值当作 J 使用的错误（量级检查）
    # 如果出现了 eV 数值直接除以长度平方得到很大的 N/m 而没有乘以 1.6e-19，则视为错误

    if not has_conversion:
        # 如果提到了 eV 转换但没看到 1.602e-19，且直接得出了结果，可能存在量级错误
        if 'eV' in prediction and ('=' in prediction):
            return {
                'result': 'fail',
                'message': 'Missing conversion factor 1.602e-19 J/eV when converting energy units.',
                'evidence': prediction[:100]
            }
        return {'result': 'inconclusive', 'message': 'Conversion logic not explicitly found', 'evidence': ''}

    return {
        'result': 'pass',
        'message': 'Correct conversion factor for eV to J detected.',
        'evidence': has_conversion.group(0)
    }

# rule_id=exp_2db19cba5d2a7743 | domain=Mechanics | topic=Mechanics / Elasticity and Hooke's Law
def check_exp_2db19cba5d2a7743_ac7a61780072(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 检查能量密度公式 u = 1/2 * E * epsilon^2
    # 匹配模式包含 1/2, E, epsilon (或 e), 平方
    density_pattern = re.compile(r'(1/2|0\.5).*E.*(epsilon|\u03b5|e).*[\^\*\*]2', re.IGNORECASE)

    # 检查体积代换 V = m/rho
    volume_sub_pattern = re.compile(r'm\s*/\s*(rho|\u03c1)', re.IGNORECASE)

    # 检查总能量公式 U = u * V
    total_energy_pattern = re.compile(r'U\s*=\s*.*(1/2|0\.5).*E.*(epsilon|\u03b5|e).*[\^\*\*]2.*m\s*/\s*(rho|\u03c1)', re.IGNORECASE)

    has_density = bool(density_pattern.search(prediction))
    has_volume_sub = bool(volume_sub_pattern.search(prediction))
    has_total_energy = bool(total_energy_pattern.search(prediction))

    if has_total_energy:
        return {
            'result': 'pass',
            'message': '成功识别能量密度与体积代换(m/rho)的组合公式',
            'evidence': total_energy_pattern.search(prediction).group(0)
        }
    elif has_density and has_volume_sub:
        return {
            'result': 'pass',
            'message': '识别到能量密度公式及质量密度体积代换逻辑',
            'evidence': f'Density: {density_pattern.search(prediction).group(0)}, Volume: {volume_sub_pattern.search(prediction).group(0)}'
        }
    elif has_density or has_volume_sub:
        return {
            'result': 'fail',
            'message': '建模不完整：缺少能量密度公式或体积代换逻辑',
            'evidence': prediction[:100]
        }

    return {'result': 'inconclusive', 'message': '未发现相关的弹性势能建模公式', 'evidence': ''}

# rule_id=exp_419dbe2552042ac9 | domain=Mechanics | topic=Mechanics / Elasticity and Hooke's Law
def check_exp_419dbe2552042ac9_dd51b63a3324(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 检查是否涉及势能函数简谐近似的场景
    keywords = ['势能', 'Potential', 'Morse', 'Lennard-Jones', 'V(x)', 'U(r)']
    is_relevant = any(kw in question or kw in prediction for kw in keywords)
    if not is_relevant:
        return {"result": "inconclusive", "message": "未检测到势能函数相关背景", "evidence": ""}

    # 核心逻辑：检查是否使用了二阶导数定义 k
    # 匹配模式：k = V''(x0), k = d^2V/dx^2, k = 1/2 * V'' * x^2 等逻辑描述
    patterns = [
        r"k\s*=\s*V''",
        r"k\s*=\s*d\^2V/dx\^2",
        r"k\s*=\s*d2V/dx2",
        r"V''\(x_0\)",
        r"二阶导数",
        r"Taylor\s*expansion",
        r"泰勒展开"
    ]

    found_logic = False
    evidence = ""
    for pattern in patterns:
        match = re.search(pattern, prediction, re.IGNORECASE)
        if match:
            found_logic = True
            evidence = match.group(0)
            break

    # 检查是否存在错误建模：比如漏掉1/2或者直接将V(x)等同于k
    # 如果提到了势能求k但没有二阶导逻辑，则可能存在建模错误
    if not found_logic:
        # 如果题目明确要求推导k，但预测中没有二阶导逻辑
        if 'k' in prediction and ('劲度系数' in prediction or 'stiffness' in prediction):
             return {"result": "fail", "message": "未发现通过势能函数二阶导数推导劲度系数的正确逻辑", "evidence": ""}
        return {"result": "inconclusive", "message": "无法确定推导逻辑是否符合准则", "evidence": ""}

    return {"result": "pass", "message": "符合势能函数简谐近似准则", "evidence": evidence}

