    # For a single wall, there should be 1 image vortex
    if is_corner:
        # Search for mention of 3 images or the specific velocity summation logic
        has_image_method = any(kw in prediction for kw in ['镜像', 'image', 'method of images'])
        has_three_images = any(kw in prediction for kw in ['3个', 'three', '3 image'])

