# rule_id=exp_8db8deff4badf6e8 | domain=Mechanics | topic=Mechanics / Fluid Dynamics (Bernoulli's Equation, Continuity)
def check_exp_8db8deff4badf6e8_da7c76d23551(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 触发条件：题目涉及收尾速度或终端速度
    trigger_keywords = ['terminal velocity', '收尾速度', '终端速度', 'falling in fluid']
    if not any(kw in question.lower() or kw in prediction.lower() for kw in trigger_keywords):
        return {"result": "inconclusive", "message": "未检测到收尾速度相关场景", "evidence": ""}

    # 检查平衡方程的核心组件：mg, 1/2 (或 0.5), C (或 Cd), rho, A (或 pi*r^2), v^2
    # 匹配 mg = ... 或 ... = mg
    patterns = [
        r'm\s*\*?\s*g\s*=\s*(0\.5|1/2)\s*\*?\s*C_?d?\s*\*?\s*rho\s*\*?\s*A\s*\*?\s*v\^2',
        r'm\s*\*?\s*g\s*=\s*(0\.5|1/2)\s*\*?\s*C_?d?\s*\*?\s*rho\s*\*?\s*pi\s*\*?\s*r\^2\s*\*?\s*v\^2',
        r'(0\.5|1/2)\s*\*?\s*C_?d?\s*\*?\s*rho\s*\*?\s*A\s*\*?\s*v\^2\s*=\s*m\s*\*?\s*g'
    ]

    found_eq = False
    evidence = ""
    for p in patterns:
        match = re.search(p, prediction.replace(' ', ''))
        if match:
            found_eq = True
            evidence = match.group(0)
            break

    # 检查是否错误使用了表面积 (Surface Area) 而非横截面积 (Cross-sectional Area)
    # 如果文本中明确提到 surface area 用于阻力公式，则判定为 modeling 错误
    surface_area_error = re.search(r'A\s*=\s*4\s*\*?\s*pi\s*\*?\s*r\^2', prediction.replace(' ', ''))

    if found_eq:
        if surface_area_error:
            return {"result": "fail", "message": "使用了表面积而非最大横截面积", "evidence": surface_area_error.group(0)}
        return {"result": "pass", "message": "建立了正确的收尾速度受力平衡方程", "evidence": evidence}

    # 如果有 mg 和 v^2 但格式不匹配，返回 inconclusive
    if 'mg' in prediction.lower() and 'v^2' in prediction.lower():
        return {"result": "inconclusive", "message": "检测到相关物理量但未发现标准平衡方程", "evidence": ""}

    return {"result": "fail", "message": "未建立重力与流体阻力的平衡方程", "evidence": ""}

# rule_id=exp_b5c41412040248ea | domain=Mechanics | topic=Mechanics / Fluid Dynamics (Bernoulli's Equation, Continuity)
def check_exp_b5c41412040248ea_1f14e33ad9dd(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 检查串联逻辑关键词：通量相等/连续，总压降/温差/电势差为各层之和
    flux_keywords = ['通量', '流量', '电流', '热流', '相等', '连续', 'constant', 'equal', 'continuity']
    sum_keywords = ['总压降', '温差', '电势差', '之和', 'sum', 'total', 'delta']

    # 检查等效系数公式特征: k_eff = L / sum(L_i/k_i) 或 R_total = sum(R_i)
    formula_patterns = [
        r'L\s*/\s*\\sum\(L_i\s*/\s*k_i\)',
        r'\\sum\s*R_i',
        r'\\Delta\s*P\s*=\s*\\sum',
        r'k_eff\s*=\s*L_total\s*/'
    ]

    has_flux_logic = any(kw in prediction for kw in flux_keywords)
    has_sum_logic = any(kw in prediction for kw in sum_keywords)
    has_formula = any(re.search(pat, prediction) for pat in formula_patterns)

    if has_flux_logic and (has_sum_logic or has_formula):
        # 进一步验证是否符合串联特征（而非并联）
        if '1/k_eff' in prediction or 'L/k' in prediction or 'sum' in prediction:
            return {
                'result': 'pass',
                'message': '模型符合串联输运等效参数逻辑',
                'evidence': '匹配到串联通量连续性或等效公式特征'
            }

    # 如果提到串联但公式错误（如直接加权平均）
    if '串联' in prediction and ('k_eff = \\sum k_i' in prediction or 'k_eff = (k1+k2)/2' in prediction):
        return {
            'result': 'fail',
            'message': '串联模型等效参数计算逻辑错误',
            'evidence': '串联等效系数不应是直接求和或简单平均'
        }

    return {'result': 'inconclusive', 'message': '未发现明确的串联输运建模逻辑特征', 'evidence': ''}

