# rule_id=exp_c8981c34ad54a5cf | domain=Mechanics | topic=Mechanics / Fluid Dynamics (Bernoulli's Equation, Continuity)
def check_exp_c8981c34ad54a5cf_910184ef9400(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    micro_triggers = ['考虑', '一层', '偏转', '微元', '动量变化', 'dp/dt', 'dm/dt', '单位时间', '截面']
    macro_formulas = ['C_d', '阻力系数', '0.5 * rho * v^2', '1/2 * rho * v^2', '经验公式']
    derivation_keywords = ['F =', 'P =', 'mv', 'delta', '动量定理']

    has_micro_context = any(word in question for word in micro_triggers)
    if not has_micro_context:
        return {"result": "inconclusive", "message": "题目未明确要求微观/局部物理过程推导", "evidence": ""}

    uses_macro_directly = any(re.search(re.escape(macro), prediction) for macro in macro_formulas)
    has_derivation = any(word in prediction for word in derivation_keywords)

    if uses_macro_directly and not has_derivation:
        evidence_match = re.search('|'.join([re.escape(m) for m in macro_formulas]), prediction)
        evidence = evidence_match.group(0) if evidence_match else ""
        return {
            "result": "fail",
            "message": "题目要求基于局部物理过程推导，但解题直接套用了宏观经验公式。",
            "evidence": evidence
        }

    if has_derivation:
        return {"result": "pass", "message": "解题过程中包含了动量/能量推导步骤。", "evidence": ""}

    return {"result": "inconclusive", "message": "无法确定是否正确应用了局部模型推导。", "evidence": ""}

