    trigger_keywords = ['不考虑广义相对论', '牛顿引力定律', 'Newtonian gravity', 'without general relativity']
    is_triggered = any(kw in question for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到牛顿力学框架的明确限制", "evidence": ""}

    # 检查逻辑：牛顿力学系数应为2，广义相对论为4
    # 匹配模式：k=2, 系数为2, 2GM/c^2b 等
    newton_pattern = r'(系数|k|factor)\s*(=|为|is)?\s*2'
    gr_pattern = r'(系数|k|factor)\s*(=|为|is)?\s*4'

    # 在预测中寻找系数设定
    has_newton_coeff = re.search(newton_pattern, prediction, re.IGNORECASE)
    has_gr_coeff = re.search(gr_pattern, prediction, re.IGNORECASE)

    if has_gr_coeff and not has_newton_coeff:
        return {
            "result": "fail",
            "message": "题目要求使用牛顿力学，但预测中使用了广义相对论的偏转系数(4)",
            "evidence": has_gr_coeff.group(0)
        }
    elif has_newton_coeff:
        return {
            "result": "pass",
            "message": "正确使用了牛顿力学的偏转系数(2)",
            "evidence": has_newton_coeff.group(0)
        }

    return {"result": "inconclusive", "message": "未能从预测中提取到明确的偏转系数", "evidence": ""}

