# rule_id=exp_293a33962552d627 | domain=Mechanics | topic=Mechanics / Gravitation and Kepler's Laws
def check_exp_293a33962552d627_cfb8672f4d46(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 匹配远地点半径公式 r_a = R * (v^2 / (2*v_0^2 - v^2))
    # 或者匹配偏差公式 2*delta / (1 - 2*delta)
    patterns = [
        r'r_a\s*=\s*R\s*\*\s*\(?v\^2\s*/\s*\(2\*v_0\^2\s*-\s*v\^2\)\)?',
        r'2\s*\*?\s*delta\s*/\s*\(1\s*-\s*2\s*\*?\s*delta\)',
        r'\\frac{2\\delta}{1-2\\delta}',
        r'\\frac{v^2}{2v_0^2-v^2}'
    ]

    hit_pattern = False
    evidence = ''
    for p in patterns:
        match = re.search(p, prediction)
        if match:
            hit_pattern = True
            evidence = match.group(0)
            break

    if hit_pattern:
        return {'result': 'pass', 'message': '命中了轨道偏差计算公式', 'evidence': evidence}

    # 检查是否包含关键词：远地点、机械能守恒、角动量守恒
    keywords = ['远地点', 'r_a', '2v_0^2', '2v^2']
    count = sum(1 for k in keywords if k in prediction)
    if count >= 2:
        return {'result': 'pass', 'message': '包含关键物理量和守恒逻辑描述', 'evidence': ' '.join([k for k in keywords if k in prediction])}

    return {'result': 'inconclusive', 'message': '未检测到明确的偏差计算公式或逻辑', 'evidence': ''}

# rule_id=exp_2cf32fed971445e2 | domain=Mechanics | topic=Mechanics / Gravitation and Kepler's Laws
def check_exp_2cf32fed971445e2_734162d38093(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 检查题目是否同时包含海拔h和半径R的关键词
    has_h = any(k in question for k in ['海拔', '高度', ' h ', 'h='])
    has_R = any(k in question for k in ['地球半径', '半径R', ' R ', 'R='])

    if not (has_h and has_R):
        return {"result": "inconclusive", "message": "题目未明确包含海拔h和半径R的触发条件", "evidence": ""}

    # 检查预测中是否体现了 r = R + h 的逻辑
    # 匹配模式：r=R+h, (R+h), R + h, 或者数值相加的逻辑
    patterns = [
        r'r\s*=\s*R\s*\+\s*h',
        r'\(R\s*\+\s*h\)',
        r'R\s*\+\s*h',
        r'r\s*=\s*h\s*\+\s*R'
    ]

    found_correct_modeling = False
    for p in patterns:
        if re.search(p, prediction, re.IGNORECASE):
            found_correct_modeling = True
            break

    # 检查是否存在错误建模：直接用 h 或 R 代替轨道半径 r 进行向心力计算
    # 例如 G*M*m/h^2 或 G*M*m/R^2 (当题目明确有h时)
    wrong_patterns = [
        r'G.*m/h\^2',
        r'G.*m/R\^2',
        r'v\^2/h',
        r'v\^2/R'
    ]

    found_wrong_modeling = False
    for wp in wrong_patterns:
        if re.search(wp, prediction):
            found_wrong_modeling = True
            break

    if found_correct_modeling:
        return {"result": "pass", "message": "正确使用了 r = R + h 作为轨道半径", "evidence": "命中半径求和逻辑"}
    elif found_wrong_modeling:
        return {"result": "fail", "message": "计算向心力或速度时错误地仅使用了 h 或 R 而非 R + h", "evidence": "检测到错误的半径建模表达式"}
    else:
        return {"result": "inconclusive", "message": "无法确定是否正确处理了轨道半径", "evidence": ""}

# rule_id=exp_326d94237b20217a | domain=Mechanics | topic=Mechanics / Gravitation and Kepler's Laws
def check_exp_326d94237b20217a_63afcd42b153(sample: dict) -> dict:

    text = (sample.get('prediction', '') + ' ' + sample.get('context', '')).lower()
    keywords = ['planet', 'mass enclosed', 'radius r', 'spherical', 'density']
    is_triggered = any(kw in text for kw in keywords)
    if not is_triggered:
        return {'result': 'inconclusive', 'message': '未检测到天体物理相关描述', 'evidence': ''}

    # 检查是否错误使用了圆盘体积元 (2*pi*r*dr)
    wrong_patterns = [r'2\s*\*?\s*pi\s*\*?\s*r\s*\*?\s*dr', r'2\s*\u03c0\s*r\s*dr']
    # 检查是否正确使用了球对称体积元 (4*pi*r^2*dr)
    correct_patterns = [r'4\s*\*?\s*pi\s*\*?\s*r\s*\^?\s*2\s*\*?\s*dr', r'4\s*\u03c0\s*r\s*\^?\s*2\s*dr']

    found_wrong = False
    wrong_evidence = ''
    for p in wrong_patterns:
        match = re.search(p, text)
        if match:
            found_wrong = True
            wrong_evidence = match.group(0)
            break

    found_correct = False
    for p in correct_patterns:
        if re.search(p, text):
            found_correct = True
            break

    if found_wrong and not found_correct:
        return {
            'result': 'fail',
            'message': '检测到错误的圆盘体积元简化，天体物理模型应使用球对称体积元 4πr²dr',
            'evidence': wrong_evidence
        }
    elif found_correct:
        return {'result': 'pass', 'message': '体积元符合球对称几何要求', 'evidence': ''}

    return {'result': 'inconclusive', 'message': '未发现明确的体积元公式', 'evidence': ''}

# rule_id=exp_37a18c99c7de474c | domain=Mechanics | topic=Mechanics / Gravitation and Kepler's Laws
def check_exp_37a18c99c7de474c_929b782a0faa(sample: dict) -> dict:


    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '无预测内容', 'evidence': ''}

    # 匹配 sin(theta) = r/R 相关的数值或表达式
    # 寻找类似 sin(theta), r/R, 或者具体的数值比例
    # 常见模式：sin(theta) = r_inner / r_outer

    # 提取数值的辅助正则
    num_pattern = r'([0-9]*\.?[0-9]+)'

    # 检查是否提到最大距角或最大张角
    keywords = ['最大距角', '最大张角', 'elongation', 'maximum angle']
    has_keyword = any(k in prediction or k in sample.get('question', '') for k in keywords)

    if not has_keyword:
        return {'result': 'inconclusive', 'message': '未识别到最大距角相关讨论', 'evidence': ''}

    # 尝试寻找 sin 关系式
    # 匹配 sin(theta) = a/b 或 theta = arcsin(a/b)
    sin_match = re.search(r'sin[\s\(]*[^=]*[\s\)]*=[\s]*' + num_pattern + r'[\s]*/[\s]*' + num_pattern, prediction)

    if sin_match:
        r_inner = float(sin_match.group(1))
        r_outer = float(sin_match.group(2))
        if r_inner >= r_outer:
            return {'result': 'fail', 'message': '内轨道半径应小于外轨道半径', 'evidence': sin_match.group(0)}
        return {'result': 'pass', 'message': '符合正弦几何关系', 'evidence': sin_match.group(0)}

    # 检查是否直接给出了 sin(theta) 的值
    val_match = re.search(r'sin[\s\(]*[^=]*[\s\)]*=[\s]*' + num_pattern, prediction)
    if val_match:
        val = float(val_match.group(1))
        if val > 1.0:
            return {'result': 'fail', 'message': '正弦值不能大于1', 'evidence': val_match.group(0)}
        return {'result': 'pass', 'message': '识别到正弦值计算', 'evidence': val_match.group(0)}

    return {'result': 'inconclusive', 'message': '无法提取明确的几何等式', 'evidence': ''}

# rule_id=exp_44f6759e80e831f2 | domain=Mechanics | topic=Mechanics / Gravitation and Kepler's Laws
def check_exp_44f6759e80e831f2_9d9c0ccb995e(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    # 触发条件：题目涉及地面参考系、地球自转或转动地球
    trigger_keywords = ['地面参考系', 'ground frame', '地球自转', 'rotating earth', '相对于地面']
    is_triggered = any(kw in question for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未触发地面参考系速度合成检查", "evidence": ""}

    # 检查逻辑：寻找速度合成公式的迹象
    # 顺行：v_g = v_i - omega*R 或 v_g = v_i - v_e
    # 逆行：v_g = v_i + omega*R 或 v_g = v_i + v_e

    # 提取预测中的公式特征
    # 匹配类似 v = v_i - wR 或 v = v_i + wR 的结构
    pattern_sub = re.compile(r'v.*=.*v.*-.*[\omega|w].*R', re.IGNORECASE)
    pattern_add = re.compile(r'v.*=.*v.*\+.*[\omega|w].*R', re.IGNORECASE)

    has_sub = bool(pattern_sub.search(prediction))
    has_add = bool(pattern_add.search(prediction))

    # 如果预测中完全没有体现速度合成关系，可能存在逻辑遗漏
    if not (has_sub or has_add):
        # 进一步检查是否有 omega * R 或 v_earth 的计算但没做加减
        if 'omega' in prediction.lower() and 'R' in prediction and 'v' in prediction:
             return {"result": "fail", "message": "未发现正确的地面参考系速度合成公式(v = v_i \\pm \\omega R)", "evidence": prediction[:100]}
        return {"result": "inconclusive", "message": "预测中未明确体现速度合成计算过程", "evidence": ""}

    # 简单验证：如果题目提到顺行(prograde/eastward)但用了加法，或逆行(retrograde/westward)用了减法，则报错
    if ('顺行' in question or 'east' in question.lower()) and has_add and not has_sub:
        return {"result": "fail", "message": "顺行速度合成逻辑错误，应为减法", "evidence": "found addition for prograde"}
    if ('逆行' in question or 'west' in question.lower()) and has_sub and not has_add:
        return {"result": "fail", "message": "逆行速度合成逻辑错误，应为加法", "evidence": "found subtraction for retrograde"}

    return {"result": "pass", "message": "符合地面参考系速度合成逻辑", "evidence": "detected velocity composition formula"}

# rule_id=exp_4efef57ccc2cd9fd | domain=Mechanics | topic=Mechanics / Gravitation and Kepler's Laws
def check_exp_4efef57ccc2cd9fd_377d4d32e7f7(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    # 检查触发条件：题目中出现 g 和 R (半径)，且未明确给出 G 的数值
    has_g = 'g' in question or '重力加速度' in question
    has_R = re.search(r'[R|r]', question) or '半径' in question
