# rule_id=exp_6a841ecb9ce0d80c | domain=Mechanics | topic=Mechanics / Gravitation and Kepler's Laws
def check_exp_6a841ecb9ce0d80c_2b89279451db(sample: dict) -> dict:

    question = sample.get('question', '')
