# rule_id=exp_7ed77810e20d0fb8 | domain=Mechanics | topic=Mechanics / Gravitation and Kepler's Laws
def check_exp_7ed77810e20d0fb8_471e6a84b43d(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 检查是否触发：题目涉及角速度(omega)与半径(R)的关系
    trigger_keywords = ['角速度', '半径', 'R', 'omega', 'ω', '关系', '幂']
    if not any(kw in question for kw in trigger_keywords):
        return {"result": "inconclusive", "message": "未识别到天体运动幂律相关问题", "evidence": ""}

    # 匹配预测中的指数 p 的值
    # 匹配模式如 p = -1.5, p = -3/2, 指数为-1.5, 指数为-3/2
    patterns = [
        r'[p|指数]\s*[=是]\s*(-?1\.5)',
        r'[p|指数]\s*[=是]\s*(-?3/2)',
        r'R\^\{\s*(-?1\.5)\s*\}',
        r'R\^\{\s*(-?3/2)\s*\}',
        r'R\^\s*(-?1\.5)',
        r'R\^\s*(-?3/2)'
    ]

    found_p = None
    evidence = ""
    for pattern in patterns:
        match = re.search(pattern, prediction)
        if match:
            found_p = match.group(1)
            evidence = match.group(0)
            break

    if not found_p:
        return {"result": "inconclusive", "message": "未在预测中找到明确的幂指数 p", "evidence": ""}

    # 校验逻辑：p 是否等于 -1.5 或 -3/2
    is_correct = False
    if found_p == '-1.5' or found_p == '-3/2':
        is_correct = True
    else:
        try:
            if abs(float(found_p) - (-1.5)) < 0.01:
                is_correct = True
        except:
            pass

    if is_correct:
        return {"result": "pass", "message": "幂律指数校验正确 (p = -1.5)", "evidence": evidence}
    else:
        return {"result": "fail", "message": "幂律指数校验错误，应为 -1.5 或 -3/2", "evidence": evidence}

# rule_id=exp_806200c422ddf614 | domain=Mechanics | topic=Mechanics / Gravitation and Kepler's Laws
def check_exp_806200c422ddf614_ad2abf6b6036(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 检查是否涉及双星系统
    is_binary = any(kw in (question + prediction) for kw in ['双星', 'binary system', 'binary star'])
    if not is_binary:
        return {"result": "inconclusive", "message": "未识别到双星系统场景", "evidence": ""}

    # 匹配角速度、质量和距离的关系：ω^2 = G(M1+M2)/R^3
    # 允许变体：ω^2 * R^3 = G(M1+M2) 或 T^2 = 4π^2 R^3 / G(M1+M2)
    patterns = [
        r"ω\^2\s*=\s*G\(M_?1\s*\+\s*M_?2\)\s*/\s*R\^3",
        r"ω\^2\s*R\^3\s*=\s*G\(M_?1\s*\+\s*M_?2\)",
        r"G\(M_?1\s*\+\s*M_?2\)\s*/\s*R\^2\s*=\s*ω\^2\s*R",
        r"T\^2\s*=\s*4π\^2\s*R\^3\s*/\s*G\(M_?1\s*\+\s*M_?2\)"
    ]

    found_correct_logic = False
    evidence = ""
    for p in patterns:
        match = re.search(p, prediction.replace(' ', ''))
        if match:
            found_correct_logic = True
            evidence = match.group(0)
            break

    if found_correct_logic:
        return {"result": "pass", "message": "正确使用了双星系统等效单体化公式", "evidence": evidence}

    # 检查是否存在错误逻辑：误用单星公式 ω^2 = GM/R^3 而非总质量
    error_pattern = r"ω\^2\s*=\s*GM\s*/\s*R\^3"
    if re.search(error_pattern, prediction.replace(' ', '')):
        return {"result": "fail", "message": "可能误用了单星中心力场公式，未考虑双星总质量", "evidence": "ω^2 = GM/R^3"}

    return {"result": "inconclusive", "message": "无法确定公式逻辑是否正确", "evidence": ""}

