# rule_id=exp_9fc33f6773002198 | domain=Mechanics | topic=Mechanics / Gravitation and Kepler's Laws
def check_exp_9fc33f6773002198_0dd595372d37(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    context = sample.get('context', '')
    text = (prediction + ' ' + context).lower()

    # 寻找类似 a^3/T^2 或 T^2/a^3 的计算痕迹
    # 匹配数值和单位，例如 42000^3 / 24^2
    pattern = re.compile(r'(\d+\.?\d*)\s*\^\s*3\s*/\s*(\d+\.?\d*)\s*\^\s*2')
    matches = pattern.findall(text)

    if not matches:
        return {"result": "inconclusive", "message": "未发现开普勒第三定律的显式比例计算步骤", "evidence": ""}

    # 检查是否直接使用了 G 的标准值 (6.67x10^-11)
    g_pattern = re.compile(r'6\.67[\d]*\s*[x*]\s*10\s*\^?\s*-11')
    has_g_constant = bool(g_pattern.search(text))

    # 如果发现了比例计算且没有直接代入 G 值，则认为符合规则建议
    if len(matches) >= 1:
        if not has_g_constant:
            return {"result": "pass", "message": "优先使用了轨道参数比例关系而非直接代入G值", "evidence": matches[0][0] + "^3/" + matches[0][1] + "^2"}
        else:
            return {"result": "fail", "message": "检测到直接代入万有引力常数G，建议优先利用已知卫星参数比例以减少误差", "evidence": "found G constant in text"}

    return {"result": "inconclusive", "message": "无法确定计算逻辑是否遵循常数一致性", "evidence": ""}

# rule_id=exp_bf221effe9e577a7 | domain=Mechanics | topic=Mechanics / Gravitation and Kepler's Laws
def check_exp_bf221effe9e577a7_5abe14a8b984(sample: dict) -> dict:

    text = sample.get('prediction', '') + ' ' + sample.get('answer', '')
    # 匹配 alpha = k * (GM / (b * v^2)) 及其变体
    # 寻找包含 G, M, b, v 的表达式，并提取其系数
    # 模式：alpha = (数字) * G * M / (b * v^2)
    pattern = r'alpha\s*=\s*([0-9\.]+)\s*\*?\s*\(?G\*?M\)?\s*/\s*\(?b\*?v\^2\)?'
    match = re.search(pattern, text.replace(' ', ''))

    if not match:
        # 尝试匹配更通用的形式 k * GM / bv^2
        pattern_alt = r'([0-9\.]+)\s*G\s*M\s*/\s*\(?b\s*v\^2\)?'
        match = re.search(pattern_alt, text)

    if match:
        try:
            k_value = float(match.group(1))
            evidence = match.group(0)
            if abs(k_value - 2.0) < 1e-5:
                return {
                    "result": "pass",
                    "message": "偏转角系数 k 等于 2，符合牛顿力学冲量近似。",
                    "evidence": evidence
                }
            else:
                return {
                    "result": "fail",
                    "message": f"偏转角系数错误：检测到 k={k_value}，但在牛顿力学框架下应为 2。",
                    "evidence": evidence
                }
        except:
            pass

    return {
        "result": "inconclusive",
        "message": "未在文本中识别到明确的偏转角公式或系数。",
        "evidence": ""
    }

# rule_id=exp_d5497078d39988a8 | domain=Mechanics | topic=Mechanics / Gravitation and Kepler's Laws
def check_exp_d5497078d39988a8_a30b344070ae(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    # 触发条件：题目涉及改变轨道、撞击、逃逸且询问质量
    trigger_keywords = ['质量', '改变轨道', '撞击', '逃逸', '轨道半径']
    if not any(k in question for k in trigger_keywords):
        return {"result": "inconclusive", "message": "未触发引力轨道质量无关性校验条件", "evidence": ""}

    # 检查逻辑：寻找方程中 m 是否被约去的表述
    # 匹配模式：m*v^2/r = G*M*m/r^2 或类似的动能势能项，且提到约去、无关、抵消等
    cancel_patterns = [
        r'm.*约去',
        r'与.*m.*无关',
        r'm.*抵消',
        r'质量.*不影响.*轨道',
        r'G*M*m/r^2.*=.*m*v^2/r',
        r'G*M*m/r^2.*=.*m*a'
    ]

    found_logic = False
    evidence = ""
    for pattern in cancel_patterns:
        match = re.search(pattern, prediction)
        if match:
            found_logic = True
            evidence = match.group(0)
            break

    # 如果题目问“需要多大质量才能改变轨道”，而回答说“取决于质量”或未约去m，则可能逻辑错误
    error_patterns = [
        r'质量越大.*越容易改变',
        r'需要.*质量才能',
        r'轨道半径取决于.*m'
    ]

    for err_p in error_patterns:
        if re.search(err_p, prediction):
            return {"result": "fail", "message": "错误地认为轨道改变与测试质量m有关", "evidence": re.search(err_p, prediction).group(0)}

    if found_logic:
        return {"result": "pass", "message": "正确识别了引力轨道中测试质量可约去的逻辑", "evidence": evidence}

    return {"result": "inconclusive", "message": "无法确定是否正确应用了质量无关性逻辑", "evidence": ""}

# rule_id=exp_d76412f8ead16021 | domain=Mechanics | topic=Mechanics / Gravitation and Kepler's Laws
def check_exp_d76412f8ead16021_f5ab5449dc12(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 寻找势能分段函数的模式，通常包含 r=R, r<R, r>R 等边界描述
    # 匹配类似 U_in(R) 和 U_out(R) 的表达式或等式描述
    boundary_patterns = [
        r'U_in\s*=\s*U_out',
        r'U\(R\)\s*is\s*continuous',
        r'势能.*连续',
        r'U_{in}\(R\)\s*=\s*U_{out}\(R\)',
        r'limit.*r\s*->\s*R'
    ]

    # 检查是否讨论了边界处的势能
    has_boundary_discussion = any(re.search(p, prediction, re.IGNORECASE) for p in boundary_patterns)

    # 检查是否存在势能突变的错误描述 (例如 U_in != U_out)
    discontinuity_patterns = [
        r'U_in\s*!=\s*U_out',
        r'势能.*不连续',
        r'jump\s*in\s*potential'
    ]
    has_discontinuity_error = any(re.search(p, prediction, re.IGNORECASE) for p in discontinuity_patterns)

    if has_discontinuity_error:
        return {
            'result': 'fail',
            'message': '势能在物理边界处必须保持连续，检测到不连续的描述。',
            'evidence': '检测到势能不连续的相关表述'
        }

    if has_boundary_discussion:
        return {
            'result': 'pass',
            'message': '预测中包含了势能连续性的正确逻辑或符合连续性要求。',
            'evidence': '匹配到势能连续性相关描述'
        }

    return {'result': 'inconclusive', 'message': '未在预测中找到明确的势能边界连续性判定逻辑。', 'evidence': ''}

# rule_id=exp_e69220dd12b9b817 | domain=Mechanics | topic=Mechanics / Gravitation and Kepler's Laws
def check_exp_e69220dd12b9b817_09b48c43ef7c(sample: dict) -> dict:

    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()

    trigger_keywords = ['orbital altitude', 'height from the ground', 'height above', 'altitude h']
    is_triggered = any(kw in question for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到海拔高度相关表述", "evidence": ""}

    # 检查是否在万有引力或向心力公式中直接使用了 h 而不是 R+h
    # 匹配类似 G*M*m/h^2 或 v^2/h 的错误模式
    error_patterns = [
        r"g[Mm]m/h\^2",
        r"g[Mm]/h\^2",
        r"v\^2/h",
        r"r\s*=\s*h"
    ]

    # 检查是否包含正确的修正逻辑 R+h
    correct_patterns = [
        r"r\s*=\s*[Rr]\s*\+\s*h",
        r"[Rr]_e\s*\+\s*h",
        r"\([Rr]\s*\+\s*h\)\^2"
    ]

    found_error = False
    evidence = ""
    for pattern in error_patterns:
        match = re.search(pattern, prediction)
        if match:
            found_error = True
            evidence = match.group(0)
            break

    found_correct = False
    for pattern in correct_patterns:
        if re.search(pattern, prediction):
            found_correct = True
            break

    if found_error and not found_correct:
        return {
            "result": "fail",
            "message": "错误地将海拔高度 h 直接作为轨道半径 r 使用，未考虑地球半径 R",
            "evidence": evidence
        }
    elif found_correct:
        return {
            "result": "pass",
            "message": "正确使用了 r = R + h 关系",
            "evidence": "detected R+h logic"
        }

    return {"result": "inconclusive", "message": "无法确定是否正确处理了半径与高度的关系", "evidence": ""}

