# rule_id=exp_fda7a693d7cd8138 | domain=Mechanics | topic=Mechanics / Gravitation and Kepler's Laws
def check_exp_fda7a693d7cd8138_bb59869b56d9(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '无预测结果', 'evidence': ''}

    # 匹配数值和单位 (pc, kpc, mpc, Mpc, Gpc)
    pattern = r'([+-]?\d*\.?\d+(?:[eE][+-]?\d+)?)\s*(pc|kpc|mpc|Mpc|Gpc)'
    matches = re.findall(pattern, prediction)

    if not matches:
        return {'result': 'inconclusive', 'message': '未检测到天文长度单位', 'evidence': ''}

    unit_map = {
        'pc': 1.0,
        'kpc': 1e3,
        'mpc': 1e-3,
        'Mpc': 1e6,
        'Gpc': 1e9
    }

    limit = 1e10  # 10^10 pc

    for val_str, unit in matches:
        try:
            val = float(val_str)
            val_in_pc = val * unit_map.get(unit, 1.0)

            # 检查是否超过宇宙半径量级
            if val_in_pc > limit:
                return {
                    'result': 'fail',
                    'message': f'计算结果 {val_str} {unit} 超过宇宙半径量级(10^10 pc)',
                    'evidence': f'{val_str} {unit}'
                }
        except ValueError:
            continue

    return {'result': 'pass', 'message': '天文尺度在合理范围内', 'evidence': matches[0][0] + ' ' + matches[0][1]}

# rule_id=exp_248985b2bf3d57ea | domain=Mechanics | topic=Mechanics / Impulse and Momentum Transfer
