    # 核心逻辑：检查角动量定理公式 I*delta_omega = r * j 或类似的力矩表达
    # 匹配模式如 I*w = r*j, I*delta_w = h*j, I*omega = j*h 等
    patterns = [
        r'I.*[\\Delta]*\\omega.*=.*[rh].*[jJ]',
        r'[rh].*[jJ].*=.*I.*[\\Delta]*\\omega',
        r'L.*=.*[rh].*[jJ]',
        r'M.*=.*[rh].*[jJ]'
    ]

    found_pattern = False
    hit_text = ''
    for p in patterns:
        match = re.search(p, prediction)
        if match:
            found_pattern = True
            hit_text = match.group(0)
            break

    if found_pattern:
        return {'result': 'pass', 'message': '已正确包含非质心碰撞的力矩建模项', 'evidence': hit_text}

    # 如果提到了碰撞点不在质心（有高度差h）但没写出对应的力矩公式，则判定为fail
