# rule_id=exp_63eb9ff627e991c2 | domain=Mechanics | topic=Mechanics / Oscillations and Simple Harmonic Motion
def check_exp_63eb9ff627e991c2_2cf6f5d20bdd(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 检查是否包含关键物理量符号
    required_symbols = ['I', 'R']
    if not all(sym in prediction for sym in required_symbols):
        return {'result': 'inconclusive', 'message': '未检测到关键符号 I 或 R', 'evidence': ''}

    # 检查等效质量公式 m_eff = I/R^2 的变体
    # 匹配模式包括 I/R^2, I / R**2, I / (R*R) 等
    patterns = [
        r'I\s*/\s*R\s*\^\s*2',
        r'I\s*/\s*R\s*\*\*\s*2',
        r'I\s*/\s*\(\s*R\s*\*\s*R\s*\)',
        r'\\frac\{I\}\{R\^2\}',
        r'I/R\^2'
    ]

    found_eff_mass = False
    evidence = ''
    for pattern in patterns:
        match = re.search(pattern, prediction)
        if match:
            found_eff_mass = True
            evidence = match.group(0)
            break

    # 检查是否将该项计入总质量或动能项 (m + I/R^2)
    if found_eff_mass:
        # 检查是否存在 m + ... 或 (m + ...)
        context_pattern = r'm\s*\+\s*.*' + re.escape(evidence)
        if re.search(context_pattern, prediction) or '1/2' in prediction:
            return {'result': 'pass', 'message': '正确识别并转化了滑轮等效质量', 'evidence': evidence}
        else:
            return {'result': 'pass', 'message': '检测到等效质量公式，但需确认是否计入总惯性', 'evidence': evidence}

    # 如果提到了滑轮和转动惯量但没有转化公式，判定为 fail
    if 'inertia' in prediction.lower() or 'moment' in prediction.lower():
        return {'result': 'fail', 'message': '未发现滑轮转动惯量向等效质量的转化公式 I/R^2', 'evidence': ''}

    return {'result': 'inconclusive', 'message': '无法确定是否应用了等效质量转化规则', 'evidence': ''}

# rule_id=exp_6bbfdc4a5f58e09c | domain=Mechanics | topic=Mechanics / Oscillations and Simple Harmonic Motion
def check_exp_6bbfdc4a5f58e09c_9718aa5887bb(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 匹配常见的错误模式：系数k进入根号但未平方，例如 k\\sqrt{m} = \\sqrt{km}
    # 匹配模式：[变量或数字] \\sqrt{[变量或数字]} = \\sqrt{[变量或数字] * [变量或数字]}
    # 排除掉已经平方的情况
    error_patterns = [
        r'([a-zA-Z0-9]+)\\s*\\sqrt{([^}]+)}\\s*=\\s*\\sqrt{\\1\\s*\\*?\\s*\\2}',
        r'\\sqrt{([^}]+)}\\s*\\*?\\s*([a-zA-Z0-9]+)\\s*=\\s*\\sqrt{\\1\\s*\\*?\\s*\\2}',
        r'\\frac{1}{([a-zA-Z0-9]+)}\\s*\\sqrt{([^}]+)}\\s*=\\s*\\sqrt{\\frac{\\2}{\\1}}'
    ]

    for pattern in error_patterns:
        match = re.search(pattern, prediction)
        if match:
            # 进一步验证，如果系数是1则忽略
            coeff = match.group(1) if 'frac' not in pattern else match.group(1)
            if coeff == '1':
                continue
            return {
                "result": "fail",
                "message": "检测到根号内外因式转换错误：系数进入根号时未进行平方处理。",
                "evidence": match.group(0)
            }

    # 检查正确模式的缺失（可选，但此处主要查错）
    # 如果文本中包含根号化简逻辑但没有明显的错误模式，返回 inconclusive
    if 'sqrt' in prediction and '=' in prediction:
        return {
            "result": "inconclusive",
            "message": "未发现明显的根式转换幂次错误，需人工核实。",
            "evidence": ""
        }

    return {
        "result": "pass",
        "message": "未触发根式转换校验逻辑。",
        "evidence": ""
    }

# rule_id=exp_784d44f5f2b37ef4 | domain=Mechanics | topic=Mechanics / Oscillations and Simple Harmonic Motion
def check_exp_784d44f5f2b37ef4_83495e2c7dc4(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    # 触发条件：题目中提到从静止释放或最大位移处释放
    trigger_keywords = ['从静止释放', '最大位移处释放', 'released from rest', 'maximum displacement']
    is_triggered = any(kw in question for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到静止释放或最大位移释放的触发词", "evidence": ""}

    # 检查逻辑：寻找形如 cos(wt + phi) 的结构，并检查 phi 是否为 0
    # 匹配模式：cos(wt), cos(wt+0), cos(wt-0)
    # 排除模式：cos(wt + pi/2), cos(wt - pi), cos(wt + 1.57) 等

    # 提取预测中的余弦函数内部项
    cos_patterns = re.findall(r'cos\\?\\(([^\\)]+)\\?\\)', prediction)
    if not cos_patterns:
        return {"result": "inconclusive", "message": "未在预测中找到余弦运动方程", "evidence": ""}

    for term in cos_patterns:
        # 如果项中包含 t 但不包含明显的非零加减项，或者加减项为0，则认为初相为0
        # 匹配类似 omega*t + phi 的结构
        if 't' in term:
            # 检查是否存在加减号且后面跟着非零数字或符号
            has_nonzero_phi = False
            if '+' in term:
                phi_part = term.split('+')[-1].strip()
                if phi_part and phi_part != '0':
                    has_nonzero_phi = True
            elif '-' in term:
                phi_part = term.split('-')[-1].strip()
                if phi_part and phi_part != '0':
                    has_nonzero_phi = True

            if has_nonzero_phi:
                return {
                    "result": "fail",
                    "message": "从静止/最大位移处释放时，若采用余弦函数描述，初相应为0",
                    "evidence": f"cos({term})"
                }
            else:
                return {
                    "result": "pass",
                    "message": "初相校验正确",
                    "evidence": f"cos({term})"
                }

    return {"result": "inconclusive", "message": "无法确定初相数值", "evidence": ""}

# rule_id=exp_9037b945723355c9 | domain=Mechanics | topic=Mechanics / Oscillations and Simple Harmonic Motion
def check_exp_9037b945723355c9_9654855f15ea(sample: dict) -> dict:

    content = (sample.get('prediction', '') + ' ' + sample.get('answer', '')).lower()

    # 检查是否涉及滑动摩擦阻尼振动
    keywords = ['摩擦', '阻尼', '振幅', '衰减', '等差', 'linear decay']
    if not any(kw in content for kw in keywords):
        return {"result": "inconclusive", "message": "未检测到滑动摩擦阻尼振动相关关键词", "evidence": ""}

    # 检查是否错误地描述为指数衰减
    if '指数' in content or 'exponential' in content:
        if '不是指数' not in content and '非指数' not in content:
            return {"result": "fail", "message": "滑动摩擦阻尼应为线性衰减而非指数衰减", "evidence": "指数"}

    # 检查线性衰减/等差数列特征
    linear_patterns = ['等差数列', '线性递减', '线性衰减', 'linear reduction']
    has_linear = any(p in content for p in linear_patterns)

    # 检查核心公式 4umg/k 或 2umg/k (半周期)
    # 匹配形如 4*mu*m*g/k, 4umg/k, 2umg/k 等模式
    formula_patterns = [
        r'4.*mu.*m.*g.*/.*k',
        r'2.*mu.*m.*g.*/.*k',
        r'\\Delta A.*=.*4.*mu.*m.*g.*/.*k'
    ]

    found_formula = False
    hit_text = ""
    for pattern in formula_patterns:
        match = re.search(pattern, content.replace(' ', ''))
        if match:
            found_formula = True
            hit_text = match.group()
            break

    if has_linear or found_formula:
        return {"result": "pass", "message": "符合滑动摩擦阻尼线性衰减律", "evidence": hit_text}

    return {"result": "inconclusive", "message": "无法确定振幅衰减的具体规律", "evidence": ""}

# rule_id=exp_a84bda60eb4c269f | domain=Mechanics | topic=Mechanics / Oscillations and Simple Harmonic Motion
def check_exp_a84bda60eb4c269f_e4021adc0806(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 触发条件：涉及弹簧(spring)或加速度(acceleration)与位移(displacement/x)的关系
    trigger_keywords = ['弹簧', 'spring', '加速度', 'acceleration', 'a =', 'a=']
    is_triggered = any(kw in question or kw in prediction for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到弹簧或加速度相关动力学场景", "evidence": ""}

    # 检查逻辑：是否使用了牛顿第二定律 F=ma 建立 a 与 x 的线性关系
    # 错误倾向：仅通过运动学求导（如 a = dv/dt）而忽略了 F = -kx 导致的 a = -(k/m)x

    # 寻找 a 与 x 的线性关系表达式，例如 a = -k/m * x 或 a = (k/m)(L-L0)
    dynamic_pattern = re.compile(r'a\s*=\s*[^\n]*k\s*/\s*m\s*\*?\s*x|F\s*=\s*m\s*a|m\s*a\s*=\s*[^\n]*k')
    has_dynamic_modeling = bool(dynamic_pattern.search(prediction))

    # 寻找是否仅使用了纯运动学求导（如 a = d^2x/dt^2 或 a = dv/dt）且没有 F=ma 的关联
    kinematic_only_pattern = re.compile(r'a\s*=\s*d[v|x]')
    has_kinematic_only = bool(kinematic_only_pattern.search(prediction)) and not has_dynamic_modeling

    if has_dynamic_modeling:
        return {"result": "pass", "message": "正确使用了动力学方程建立a与x的关系", "evidence": dynamic_pattern.search(prediction).group(0) if dynamic_pattern.search(prediction) else ""}
    elif has_kinematic_only:
        return {"result": "fail", "message": "优先律建议：应通过F=ma建立a与x的线性关系，而非仅依赖运动学求导", "evidence": kinematic_only_pattern.search(prediction).group(0)}
    else:
        return {"result": "inconclusive", "message": "无法确定是否遵循了动力学变量替换优先律", "evidence": ""}

# rule_id=exp_b204fa9b150ca0f9 | domain=Mechanics | topic=Mechanics / Oscillations and Simple Harmonic Motion
def check_exp_b204fa9b150ca0f9_35cc0c984d51(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 检查是否涉及传送带/盖板/摩擦力/弹簧振子背景
    keywords = ['传送带', '盖板', '摩擦', '弹簧', '振子', 'stick-slip', 'oscillator']
    if not any(kw in prediction or kw in sample.get('question', '') for kw in keywords):
        return {'result': 'inconclusive', 'message': '未识别到粘滞-滑动振子相关背景', 'evidence': ''}

    # 核心校验逻辑：振幅计算是否包含势能差项 (1/2*k*x^2) 和 动能项 (1/2*m*u^2)
    # 匹配 1/2 * k * A^2 或类似的能量守恒表达式
    energy_pattern = re.compile(r'1/2\s*\*?\s*k\s*\*?\s*A\^2|0\.5\s*\*?\s*k\s*\*?\s*A\^2')
    potential_diff_pattern = re.compile(r'1/2\s*\*?\s*k\s*\*?\s*\(.*?\)\^2|0\.5\s*\*?\s*k\s*\*?\s*\(.*?\)\^2')
    kinetic_pattern = re.compile(r'1/2\s*\*?\s*m\s*\*?\s*u\^2|0\.5\s*\*?\s*m\s*\*?\s*u\^2')

    has_energy_lhs = bool(energy_pattern.search(prediction))
    has_potential_rhs = bool(potential_diff_pattern.search(prediction))
    has_kinetic_rhs = bool(kinetic_pattern.search(prediction))

    if has_energy_lhs:
        if has_potential_rhs and has_kinetic_rhs:
            return {
                'result': 'pass',
                'message': '能量守恒公式中正确包含了势能差项和动能项',
                'evidence': energy_pattern.search(prediction).group(0)
            }
        else:
            return {
                'result': 'fail',
                'message': '振幅计算未同时考虑势能差或脱离瞬间的动能项',
                'evidence': energy_pattern.search(prediction).group(0)
            }

    return {'result': 'inconclusive', 'message': '未找到明确的能量守恒表达式', 'evidence': ''}

