# rule_id=exp_5044e01592a33f37 | domain=Mechanics | topic=Mechanics / Projectile Motion
def check_exp_5044e01592a33f37_ca7af7a27718(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 检查是否涉及弹性碰撞和墙面/篮板
    keywords = ['弹性碰撞', '墙', '篮板', '镜像', '对称']
    is_relevant = any(kw in question or kw in prediction for kw in keywords)

    if not is_relevant:
        return {"result": "inconclusive", "message": "未检测到弹性碰撞或镜像法相关关键词", "evidence": ""}

    # 检查逻辑：是否将折线转化为直线，或者使用了镜像对称的思想
    # 核心逻辑是总位移等于各段位移之和，或者通过镜像点计算
    logic_patterns = [
        '镜像', '对称点', '等效为直线', '总位移',
        'x_total', 'x1 + x2', 'x_before + x_after'
    ]

    hit_count = 0
    hit_evidence = ""
    for pattern in logic_patterns:
        if pattern in prediction:
            hit_count += 1
            hit_evidence = pattern

    if hit_count >= 1:
        return {
            "result": "pass",
            "message": "模型正确使用了镜像法或位移等效逻辑",
            "evidence": hit_evidence
        }

    # 如果提到了碰撞但没有体现镜像/直线化处理，可能存在建模错误
    if '碰撞' in prediction and '直线' not in prediction and '镜像' not in prediction:
        return {
            "result": "fail",
            "message": "未发现使用镜像法将折线轨迹转化为直线轨迹的建模过程",
            "evidence": ""
        }

