# rule_id=exp_72b9a662af8a09a8 | domain=Mechanics | topic=Mechanics / Projectile Motion
def check_exp_72b9a662af8a09a8_5e9bf05419c6(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    trigger_keywords = ['跳出', '跨越', '越过', '最小功', '最小初速度', '最小速度']
