    if not any(k in question for k in trigger_keywords):
        return {"result": "inconclusive", "message": "未识别到相关物理场景", "evidence": ""}

    # 核心公式模式：Δf/f = 2v/c 或类似的比例关系
    # 匹配 2v/c, 2*v/c, (2*v)/c 等形式
    pattern_formula = re.compile(r'2\s*\*?\s*v\s*/\s*c|2v/c|\\frac{2v}{c}', re.IGNORECASE)

    # 检查预测中是否体现了该逻辑
    match = pattern_formula.search(prediction)

    if match:
        return {
            "result": "pass",
            "message": "正确应用了一阶多普勒频差公式 2v/c",
            "evidence": match.group(0)
        }

    # 如果没有显式公式，检查是否有计算频差百分比的动作
    if 'v' in prediction and 'c' in prediction and ('/' in prediction or '频率' in prediction):
        return {
            "result": "fail",
            "message": "未发现正确的一阶多普勒频差公式 (2v/c)",
            "evidence": ""
        }

    return {"result": "inconclusive", "message": "无法确定是否应用了特定频差公式", "evidence": ""}

