# rule_id=exp_7d5b4dda204a596d | domain=Modern Physics | topic=Modern Physics / Heisenberg Uncertainty Principle
def check_exp_7d5b4dda204a596d_1386c1910874(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')

    # 检查是否涉及能量时间不确定性原理
    if not any(kw in prediction.lower() for kw in ['uncertainty', 'heisenberg', 'delta e', 'delta t', 'h-bar', 'hbar']):
        return {"result": "inconclusive", "message": "未检测到不确定性原理相关计算", "evidence": ""}

    # 检查参考答案是否以焦耳(J)为单位
    if 'J' not in answer and 'joule' not in answer.lower():
        return {"result": "inconclusive", "message": "参考答案单位非焦耳", "evidence": ""}

    # 提取预测中的h-bar数值
    # 匹配科学计数法如 1.054e-34, 6.582e-16
    hbar_js_pattern = r'1\.05[45][0-9]*[eE]-34'
    hbar_evs_pattern = r'6\.58[23][0-9]*[eE]-16'

    has_js_hbar = re.search(hbar_js_pattern, prediction)
    has_evs_hbar = re.search(hbar_evs_pattern, prediction)

    # 检查是否有单位换算因子 1.602e-19
    has_conversion = re.search(r'1\.602[0-9]*[eE]-19', prediction)

    # 逻辑判断：
    # 如果使用了 eV*s 的 hbar 且没有进行 eV 到 J 的换算，则判定为单位错误
    if has_evs_hbar and not has_conversion:
        # 进一步确认最终结果单位是否被标为 J
        if 'J' in prediction or 'joule' in prediction.lower():
            return {
                "result": "fail",
                "message": "使用了eV·s单位的约化普朗克常数但未进行焦耳换算",
                "evidence": has_evs_hbar.group(0)
            }

    if has_js_hbar:
        return {"result": "pass", "message": "使用了正确的J·s单位h-bar", "evidence": has_js_hbar.group(0)}

    return {"result": "inconclusive", "message": "无法确定单位使用情况", "evidence": ""}

