# rule_id=exp_1c2ad4f1306bb323 | domain=Modern Physics | topic=Modern Physics / Nuclear Physics (Binding Energy, Radioactivity)
def check_exp_1c2ad4f1306bb323_9631c2d1ddee(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 定义基本常量的量纲 [M, L, T]
    # h: [1, 2, -1], c: [0, 1, -1], G: [-1, 3, -2], m: [1, 0, 0]
    dims = {
        'h': [1, 2, -1],
        'c': [0, 1, -1],
        'G': [-1, 3, -2],
        'm': [1, 0, 0]
    }
    # 寻找形如 h^a * c^b * G^c * m^d 的模式
    pattern = r'([hcGm])(?:\^\(?([-]?\d+(?:/\d+)?)\)?)?'
    matches = re.findall(pattern, prediction)
    if not matches:
        return {"result": "inconclusive", "message": "未在预测中找到涉及 h, c, G, m 的组合公式", "evidence": ""}

    total_dim = [0.0, 0.0, 0.0]
    for symbol, exponent_str in matches:
        if not exponent_str:
            exponent = 1.0
        elif '/' in exponent_str:
            num, den = exponent_str.split('/')
            exponent = float(num) / float(den)
        else:
            exponent = float(exponent_str)

        unit_dim = dims.get(symbol)
        for i in range(3):
            total_dim[i] += unit_dim[i] * exponent

    # 检查是否为质量量纲 [1, 0, 0]
    is_mass = abs(total_dim[0] - 1.0) < 1e-5 and abs(total_dim[1]) < 1e-5 and abs(total_dim[2]) < 1e-5

    # 如果公式存在但量纲不是质量（且上下文暗示在求质量），则报错
    if not is_mass and ('mass' in prediction.lower() or '质量' in prediction):
        return {
            "result": "fail",
            "message": "公式量纲预检失败：组合常数项的量纲不等于质量量纲 [M]",
            "evidence": str(matches)
        }

    return {"result": "pass", "message": "量纲检查通过或未触发严格校验条件", "evidence": str(matches)}

# rule_id=exp_45c9dc38cb293e37 | domain=Modern Physics | topic=Modern Physics / Nuclear Physics (Binding Energy, Radioactivity)
def check_exp_45c9dc38cb293e37_b35102db43b1(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    # 检查是否涉及铀铅测年及238U/235U比例
    keywords = ['238U', '235U', '206Pb', '207Pb', '铀', '铅', '衰变', '测年']
    if not any(kw in question for kw in keywords):
        return {"result": "inconclusive", "message": "未识别到铀铅测年相关关键词", "evidence": ""}

    # 核心逻辑：检查公式中是否正确处理了两个衰变常数对应的指数项之比
    # 目标模式：(e^(L1*T)-1) / (e^(L2*T)-1) 或类似的比例关系
