    receding = ['recede', 'away', 'further', 'moving apart']

    # 定义频移方向关键词
    blue_shift = ['blue shift', 'increase', 'higher frequency', '1+v/c', '1 + v/c']
    red_shift = ['red shift', 'decrease', 'lower frequency', '1-v/c', '1 - v/c']

    # 逻辑检查：靠近应对应频率增加（蓝移）
