    arrhenius_pattern = re.compile(r'(exp\(|e\^|i0|k_?B|k[BT])', re.IGNORECASE)
    linear_pattern = re.compile(r'(ln\(|log\(|1/T|slope|斜率)', re.IGNORECASE)
    energy_pattern = re.compile(r'(E_?a|\Delta E|激活能|能隙)', re.IGNORECASE)

    has_arrhenius = bool(arrhenius_pattern.search(prediction))
    has_linear = bool(linear_pattern.search(prediction))
    has_energy = bool(energy_pattern.search(prediction))

    if not (has_arrhenius or has_linear):
        return {'result': 'inconclusive', 'message': '未检测到阿伦尼乌斯相关公式或线性化描述', 'evidence': ''}

    # 检查逻辑：是否通过 ln(i) 与 1/T 的关系提取 E
    # 匹配 ln(i) = ... 1/T ... 类型的表达式或描述
    logic_match = re.search(r'(ln.*1/T|slope.*-E/k|斜率.*-E/k|E.*slope.*k)', prediction, re.IGNORECASE)

    if logic_match:
        return {
            'result': 'pass',
            'message': '成功识别阿伦尼乌斯线性化处理及参数提取逻辑',
            'evidence': logic_match.group(0)
        }

    # 如果提到了相关概念但没有明确的线性化提取公式，则视为建模错误或不完整
    if has_arrhenius and not has_linear:
        return {
            'result': 'fail',
            'message': '未发现将指数关系转化为线性关系(ln i vs 1/T)的步骤',
            'evidence': 'detected arrhenius but no linearization'
        }

    return {'result': 'inconclusive', 'message': '无法确定是否正确应用了参数提取逻辑', 'evidence': ''}

