# rule_id=exp_3b56bb220056b199 | domain=Modern Physics | topic=Modern Physics / Relativistic Energy and Momentum
def check_exp_3b56bb220056b199_e818b77b5077(sample: dict) -> dict:


    prediction = sample.get('prediction', '')

    # 提取数值的辅助逻辑
    def find_value(pattern, text):
        match = re.search(pattern, text)
        return float(match.group(1)) if match else None

    # 尝试从预测文本中提取 p_e, E_gamma, alpha (角度或弧度)
    # 匹配模式示例: p_e=1.2, E_gamma=0.511, alpha=30
    p_e = find_value(r'p_e\s*=\s*([0-9.]+)', prediction)
    e_gamma = find_value(r'E_gamma\s*=\s*([0-9.]+)', prediction)
    alpha_deg = find_value(r'alpha\s*=\s*([0-9.]+)', prediction)

    if p_e is None or e_gamma is None or alpha_deg is None:
        return {
            "result": "inconclusive",
            "message": "未能从预测中提取出 p_e, E_gamma 或 alpha 的数值",
            "evidence": ""
        }

    try:
        # 物理逻辑: cos(alpha) = p_e / (2 * E_gamma / c)
        # 假设单位已统一，c=1 或在数值中已包含
        # 计算左边: cos(alpha)
        lhs = math.cos(math.radians(alpha_deg))
        # 计算右边: p_e / (2 * E_gamma)
        rhs = p_e / (2 * e_gamma)

        # 允许 5% 的误差
        if abs(lhs - rhs) < 0.05:
            return {
                "result": "pass",
                "message": "出射角与动量守恒逻辑一致",
                "evidence": f"p_e={p_e}, E_gamma={e_gamma}, alpha={alpha_deg}"
            }
        else:
            return {
                "result": "fail",
                "message": "出射角不符合动量三角形关系 cos(alpha) = p_e / (2 * E_gamma)",
                "evidence": f"LHS={lhs:.4f}, RHS={rhs:.4f}"
            }
    except Exception as e:
        return {
            "result": "inconclusive",
            "message": f"计算过程出错: {str(e)}",
            "evidence": ""
        }

