# rule_id=exp_0aad4ca9321d3c10 | domain=Modern Physics | topic=Modern Physics / Special Relativity (Time Dilation, Length Contraction)
def check_exp_0aad4ca9321d3c10_2c0b40a9b5e9(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    # 检查是否触发：计算误差、差异、近似且涉及相对论
    trigger_keywords = ['误差', '差异', 'difference', 'error', 'approximate']
    relativity_keywords = ['v/c', 'beta', '相对论', 'relativity', 'c']

    is_triggered = any(k in question for k in trigger_keywords) and any(k in question for k in relativity_keywords)
    if not is_triggered:
        return {"result": "inconclusive", "message": "未触发误差分析场景", "evidence": ""}

    # 检查逻辑：是否只保留了一阶项 (v/c) 而忽略了二阶项 (v/c)^2
    # 错误模式：1 + beta, 1 - beta, 1 + v/c (没有平方项)
    # 正确模式：1/2 * beta^2, (v/c)^2, beta**2, 0.5 * beta**2

    first_order_patterns = [r'1[\+\-]\\?beta', r'1[\+\-]v/c']
    second_order_patterns = [r'beta\^2', r'v\^2/c\^2', r'\(v/c\)\^2', r'beta\*\*2', r'0\.5.*beta\^2', r'1/2.*beta\^2']

    has_first_order = any(re.search(p, prediction) for p in first_order_patterns)
    has_second_order = any(re.search(p, prediction) for p in second_order_patterns)

    if has_first_order and not has_second_order:
        return {
            "result": "fail",
            "message": "误差分析中截断过早，未保留(v/c)^2二阶项，可能导致差异项被抵消",
            "evidence": "检测到一阶近似但缺失二阶项"
        }

    if has_second_order:
        return {
            "result": "pass",
            "message": "已包含二阶项近似",
            "evidence": "检测到(v/c)^2或beta^2相关项"
        }

    return {"result": "inconclusive", "message": "无法确定近似阶数", "evidence": ""}

