# rule_id=exp_536c8b27a19ade04 | domain=Modern Physics | topic=Modern Physics / Special Relativity (Time Dilation, Length Contraction)
def check_exp_536c8b27a19ade04_9080c8cdf35d(sample: dict) -> dict:

    text = (sample.get('prediction', '') + ' ' + sample.get('answer', '')).lower()

    # 寻找双曲函数参数化的迹象
    has_sinh = 'sinh' in text
    has_cosh = 'cosh' in text
    has_gamma = 'gamma' in text or '\\gamma' in text
    has_beta = 'beta' in text or '\\beta' in text

    if not (has_sinh or has_cosh):
        return {"result": "inconclusive", "message": "未检测到双曲函数参数化", "evidence": ""}

    # 检查恒等式逻辑：gamma = cosh(alpha), beta*gamma = sinh(alpha)
    # 寻找类似 gamma = cosh 或 beta*gamma = sinh 的表达式
    patterns = [
        r'gamma\s*=\s*cosh',
        r'\\gamma\s*=\s*\\cosh',
        r'beta\s*gamma\s*=\s*sinh',
        r'\\beta\\gamma\s*=\s*\\sinh',
        r'cosh\^2.*sinh\^2.*1'
    ]

    found_pattern = False
    for p in patterns:
        if re.search(p, text):
            found_pattern = True
            break

    if found_pattern:
        # 进一步检查是否满足 cosh^2 - sinh^2 = 1 的逻辑一致性（通过文本描述判断）
        if 'cosh' in text and 'sinh' in text:
            # 如果文本中提到了这些关系但逻辑错误（例如相加等于1），则报错
            if re.search(r'cosh\^2\s*\+\s*sinh\^2\s*=\s*1', text):
                return {"result": "fail", "message": "双曲恒等式错误：应为cosh^2 - sinh^2 = 1", "evidence": "cosh^2 + sinh^2 = 1"}
            return {"result": "pass", "message": "双曲函数运动学参数化符合物理恒等式", "evidence": "匹配到双曲函数运动学关联"}

    return {"result": "inconclusive", "message": "无法确定双曲函数逻辑的正确性", "evidence": ""}

