    # 检查 v=0 时的极限值 2P/c
    # 匹配类似 F = 2P/c, F(0) = 2P/c, F_0 = 2P/c 等模式
    v0_pattern = r'f(?:\(0\)|_0|\s*=\s*|\s*at\s*v=0)?\s*=?\s*2\s*\*?\s*p\s*/\s*c'
