def check_exp_9db7a831a0151baf_1e0c3580a308(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')
    content = (question + ' ' + prediction).lower()

    # 检查是否处于超相对论极限场景 (p >> m 或 E >> m)
    has_ultra_rel = any(kw in content for kw in ['p >> m', 'p >> mc', 'e >> m', 'ultra-relativistic', '超相对论'])
    # 检查是否涉及 1-beta 或 1/beta-1 的计算
    has_target_term = any(term in content.replace(' ', '') for term in ['1-beta', '1/beta-1', '1-\beta'])

    if not (has_ultra_rel and has_target_term):
        return {"result": "inconclusive", "message": "未检测到超相对论极限或相关项计算", "evidence": ""}

    # 检查是否使用了近似公式 1/(2*(p/mc)^2) 或 (m^2)/(2p^2)
    # 匹配模式如 m^2/(2p^2), 1/2 * (m/p)^2, (mc)^2/(2p^2) 等
    patterns = [
        r'm\^2\s*/\s*\(2\*?p\^2\)',
        r'1/2\s*\*?\s*\(m/p\)\^2',
        r'm\^2c\^2\s*/\s*\(2p\^2\)',
        r'1/\(2gamma\^2\)'
    ]

    found_approximation = False
    evidence = ""
    for p in patterns:
        match = re.search(p, content.replace(' ', ''))
        if match:
            found_approximation = True
            evidence = match.group(0)
            break

    if found_approximation:
        return {"result": "pass", "message": "正确使用了超相对论近似公式避免精度丢失", "evidence": evidence}
    else:
        # 如果检测到 1-beta 但没有看到近似公式，判定为潜在的数值风险
        if '1-beta' in content.replace(' ', '') or '1-\beta' in content:
            return {"result": "fail", "message": "在超相对论极限下直接计算1-beta会导致浮点数精度丢失，应使用近似公式", "evidence": "1-beta"}

    return {"result": "inconclusive", "message": "无法确定是否使用了正确的近似逻辑", "evidence": ""}

