# rule_id=exp_aca9f59597c1831f | domain=Modern Physics | topic=Modern Physics / Special Relativity (Time Dilation, Length Contraction)
def check_exp_aca9f59597c1831f_e7fbd9a63e67(sample: dict) -> dict:
    text = (sample.get('prediction', '') + ' ' + sample.get('answer', '')).lower()

    # 触发词检查：加速、火箭、光子/频率
    trigger_keywords = ['加速', '火箭', '频率', '光子', '红移', '蓝移']
    if not any(kw in text for kw in trigger_keywords):
        return {"result": "inconclusive", "message": "未检测到加速系频率偏移相关关键词", "evidence": ""}

    # 逻辑判定：
    # 1. 传向后端 (与加速度相反) -> 红移
    # 2. 传向前端 (与加速度相同) -> 蓝移

    is_backward = any(kw in text for kw in ['传向后端', '向后传播', '反方向', 'opposite to a', 'backward'])
    is_forward = any(kw in text for kw in ['传向前端', '向前传播', '同方向', 'same direction as a', 'forward'])

    has_redshift = any(kw in text for kw in ['红移', 'redshift', '频率降低', 'f_obs < f_src'])
    has_blueshift = any(kw in text for kw in ['蓝移', 'blueshift', '频率升高', 'f_obs > f_src'])

    if is_backward:
        if has_blueshift and not has_redshift:
            return {"result": "fail", "message": "光向后传播（与加速度相反）应为红移而非蓝移", "evidence": text}
        if has_redshift:
            return {"result": "pass", "message": "正确识别向后传播导致红移", "evidence": text}

    if is_forward:
        if has_redshift and not has_blueshift:
            return {"result": "fail", "message": "光向前传播（与加速度相同）应为蓝移而非红移", "evidence": text}
        if has_blueshift:
            return {"result": "pass", "message": "正确识别向前传播导致蓝移", "evidence": text}

    return {"result": "inconclusive", "message": "无法从文本中明确判定传播方向与频率偏移的对应关系", "evidence": ""}

