    # 寻找波长与频率的比例关系表达式，如 f'/f = lambda/lambda'
    # 匹配模式：f_obs/f_src 与 lambda_obs/lambda_src 的关系
    # 错误逻辑：f_obs/f_src = lambda_obs/lambda_src (应该是反比)

    # 提取可能的比例关系
    patterns = [
        r"f_?[\w']*/f_?[\w']*\s*=\s*lambda_?[\w']*/lambda_?[\w']*",
        r"f_?[\w']*/f_?[\w']*\s*=\s*\u03bb_?[\w']*/\u03bb_?[\w']*",
        r"f_?[\w']*\s*\*\s*f_?[\w']*\s*=\s*lambda_?[\w']*\s*\*\s*lambda_?[\w']*"
    ]

    found_error = False
    evidence = ""

    for p in patterns:
        match = re.search(p, prediction)
        if match:
            expr = match.group(0)
            # 如果公式中 f_obs/f_src = lambda_obs/lambda_src 则是错误的（正比关系）
            # 正常应该是 f_obs/f_src = lambda_src/lambda_obs
            # 简单检查：如果等号两边的下标顺序一致，通常是错误的
            parts = expr.split('=')
            left, right = parts[0], parts[1]

            # 检查是否出现了 f'/f = lambda'/lambda 这种同向比例
            if ("'" in left and "'" in right and left.find("'") < left.find("/") and right.find("'") < right.find("/")):
                found_error = True
                evidence = expr
                break
            if ("obs" in left and "obs" in right and "src" in left and "src" in right):
                # 检查是否 obs 都在分子
                if left.find("obs") < left.find("src") and right.find("obs") < right.find("src"):
                    found_error = True
                    evidence = expr
                    break

    if found_error:
        return {
            "result": "fail",
            "message": "多普勒频移公式逻辑错误：频率与波长应成反比关系，检测到错误的同向比例。",
            "evidence": evidence
        }

    # 检查红移逻辑：波长增加(lambda' > lambda) 对应 频率减小(f' < f)
    if "redshift" in prediction.lower() or "红移" in prediction:
        if "lambda" in prediction and "f" in prediction:
            if re.search(r"lambda.*increase.*f.*increase", prediction, re.I) or re.search(r"波长.*增加.*频率.*增加", prediction):
                return {
                    "result": "fail",
                    "message": "红移逻辑矛盾：波长增加应对应频率减小。",
                    "evidence": "lambda increase ... f increase"
                }

    return {"result": "pass", "message": "未发现明显的频移量纲或比例逻辑错误", "evidence": ""}

