# rule_id=exp_2401dd4da37c54e5 | domain=Modern Physics | topic=Modern Physics / Spin and Magnetic Moments
def check_exp_2401dd4da37c54e5_fa4f8532d553(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '无预测内容', 'evidence': ''}

    # 匹配常见的误差表示形式，如 X = 1.23 +/- 0.01 或 X = 1.23(45)
    # 模式1: 数值 +/- 误差
    pattern_pm = re.compile(r'([\d\.]+)\s*(?:\\pm|\+/-)\s*([\d\.]+)')
    # 模式2: 科学计数法下的误差，如 (1.23 \pm 0.01)e-23
    pattern_sci = re.compile(r'\(\s*([\d\.]+)\s*(?:\\pm|\+/-)\s*([\d\.]+)\s*\)')

    match_pm = pattern_pm.search(prediction)
    match_sci = pattern_sci.search(prediction)

    val_str, err_str = None, None
    evidence = ''

    if match_sci:
        val_str, err_str = match_sci.groups()
        evidence = match_sci.group(0)
    elif match_pm:
        val_str, err_str = match_pm.groups()
        evidence = match_pm.group(0)

    if val_str and err_str:
        try:
            val = float(val_str)
            err = float(err_str)
            if val == 0:
                return {'result': 'inconclusive', 'message': '基准值为0无法比较', 'evidence': evidence}
            if err > abs(val):
                return {
                    'result': 'fail',
                    'message': '误差项大于物理量本身，可能存在数量级或单位换算错误',
                    'evidence': evidence
                }
            else:
                return {'result': 'pass', 'message': '误差量级合理', 'evidence': evidence}
        except ValueError:
            return {'result': 'inconclusive', 'message': '数值解析失败', 'evidence': evidence}

    return {'result': 'inconclusive', 'message': '未检测到明确的误差表示形式', 'evidence': ''}

