# rule_id=exp_93ab6590a867526a | domain=Optics | topic=Optics / Interference (Young's Double Slit, Thin Films)
def check_exp_93ab6590a867526a_ac1009cf6983(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 检查是否讨论了介质中的干涉条纹间距 (Delta)
    keywords = ['条纹间距', 'Delta', 'Δ', 'interference fringe']
    has_context = any(kw in prediction for kw in keywords)
    if not has_context:
        return {'result': 'inconclusive', 'message': '未检测到干涉条纹相关讨论', 'evidence': ''}

    # 核心逻辑：检查公式中是否错误地引入了折射率 n 来计算间距
    # 规则指出：介质不改变真空入射光的干涉条纹间距，即公式应只与 λ0 和 α0 有关
    # 错误模式：公式中出现了 n (折射率) 且用于修改间距

    # 匹配包含 n 的公式片段，例如 Delta = lambda / (n * sin(alpha))
    error_patterns = [
        r'\\Delta\\s*=\\s*[^=]*n[^=]*',
        r'\\Delta\\s*=\\s*\\lambda_0\\s*/\\s*\\(n\\s*\\*',
        r'间距.*除以.*n',
        r'间距.*与.*n.*有关'
    ]

    found_error = False
    evidence = ''
    for pattern in error_patterns:
        match = re.search(pattern, prediction)
        if match:
            found_error = True
            evidence = match.group(0)
            break

    if found_error:
        return {
            'result': 'fail',
            'message': '错误地认为介质折射率 n 会改变由真空入射光形成的干涉条纹间距。',
            'evidence': evidence
        }

    # 检查是否正确表述了与 n 无关或只取决于真空参数
    correct_patterns = [
        r'\\Delta\\s*=\\s*\\lambda_0\\s*/\\s*\\(2\\s*\\*\\s*sin\\(alpha_0/2\\)\\)',
        r'\\Delta\\s*=\\s*\\lambda_0\\s*/\\s*alpha_0',
        r'间距不变',
        r'与折射率无关'
    ]

    for pattern in correct_patterns:
        if re.search(pattern, prediction):
            return {
                'result': 'pass',
                'message': '正确识别了条纹间距仅取决于真空波长和入射角，与介质无关。',
                'evidence': re.search(pattern, prediction).group(0)
            }

    return {'result': 'inconclusive', 'message': '无法确定公式是否正确处理了折射率的影响', 'evidence': ''}

# rule_id=exp_a974669d3b7435d2 | domain=Optics | topic=Optics / Interference (Young's Double Slit, Thin Films)
def check_exp_a974669d3b7435d2_c65363b6d76d(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 匹配干涉条纹周期公式模式，寻找分母部分
    # 模式1: λ / (2 * sin(θ))
    # 模式2: λ / sin(α)
    # 模式3: λ / α (小角度)
    patterns = [
        r'\\lambda\s*/\s*\(2\s*\\*?\s*sin\s*\\?\(\s*\\theta\s*\\?\)\)',
        r'\\lambda\s*/\s*sin\s*\\?\(\s*\\alpha\s*\\?\)',
        r'\\lambda\s*/\s*\\alpha',
        r'\\Delta\s*=\s*\\lambda\s*/\s*\\theta'
    ]

    found_formula = False
    for p in patterns:
        if re.search(p, prediction):
            found_formula = True
            break

    # 检查是否存在错误系数，例如分母只有 sin(θ) 而不是 2sin(θ)
    error_pattern = r'\\lambda\s*/\s*sin\s*\\?\(\s*\\theta\s*\\?\)'
    if re.search(error_pattern, prediction) and not re.search(r'2\s*\\*?\s*sin\s*\\?\(\s*\\theta', prediction):
        return {
            'result': 'fail',
            'message': '干涉条纹周期公式分母系数错误，半角应为2*sin(θ)',
            'evidence': re.search(error_pattern, prediction).group(0)
        }

    if found_formula:
        return {
            'result': 'pass',
            'message': '公式系数符合双光束干涉周期定义',
            'evidence': 'matched formula pattern'
        }

    return {'result': 'inconclusive', 'message': '未检测到明确的干涉周期公式', 'evidence': ''}

# rule_id=exp_c228e2ee8743dc2b | domain=Optics | topic=Optics / Interference (Young's Double Slit, Thin Films)
def check_exp_c228e2ee8743dc2b_e7b8e031ab87(sample: dict) -> dict:

    prediction = sample.get('prediction', '')

    # 检查是否涉及干涉级数n, 波长lambda, 间距d
    keywords = ['n', 'lambda', 'd', 'theta', '干涉', '级数']
    if not any(kw in prediction.lower() for kw in keywords):
        return {"result": "inconclusive", "message": "未检测到干涉相关物理量", "evidence": ""}

    # 检查是否错误使用了小角近似 (cos theta = 1)
    # 匹配类似 cos(theta) = 1 或 cos(theta) 约等于 1 的表述
    small_angle_approx_patterns = [
        r"cos\\?.*\\approx\\?.*1",
        r"cos\\?.*=\\?.*1",
        r"忽略.*cos",
        r"small angle approximation"
    ]

    # 检查是否使用了正确的余弦修正公式
    correct_formula_patterns = [
        r"sqrt\\(1\\s*-\\s*\\(n\\*lambda/d\\)\\^2\\)",
        r"cos\\(theta\\)\\s*=\\s*\\(1\\s*-\\s*sin\\^2",
        r"d\\s*cos\\(theta\\)\\s*d\\s*theta"
    ]

    found_approx = any(re.search(p, prediction, re.IGNORECASE) for p in small_angle_approx_patterns)
    found_correct = any(re.search(p, prediction, re.IGNORECASE) for p in correct_formula_patterns)

    # 触发条件：当n较大或d与lambda接近时（通常表现为n*lambda/d不是极小值）
    # 如果文本中明确提到n很大或d与lambda量级相同，则必须使用修正
    trigger_context = ["n is large", "n较大", "d approx lambda", "d与lambda接近"]
    is_triggered = any(tc in prediction.lower() or tc in sample.get('question', '').lower() for tc in trigger_context)

    if is_triggered:
        if found_approx and not found_correct:
            return {
                "result": "fail",
                "message": "在高阶干涉或d与lambda接近时，错误使用了小角近似(cos theta=1)，未进行余弦修正。",
                "evidence": "检测到近似假设但未见cos修正公式"
            }
        if found_correct:
            return {
                "result": "pass",
                "message": "正确使用了余弦修正公式。",
                "evidence": "匹配到cos(theta) = sqrt(1-(n*lambda/d)^2)相关逻辑"
            }

    return {"result": "inconclusive", "message": "无法确定是否违反高阶干涉修正规则", "evidence": ""}

# rule_id=exp_cc254d8c435e04cf | domain=Optics | topic=Optics / Interference (Young's Double Slit, Thin Films)
def check_exp_cc254d8c435e04cf_e890dd766efe(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 匹配光程差或相位差公式的核心逻辑：(mu-1)w 与 d*sin(theta) 符号相反
    # 典型形式如 d*sin(theta) - (mu-1)w 或 (mu-1)w - d*sin(theta)
    patterns = [
        r'd\\sin\\theta\\s*-\\s*\\(\\mu-1\\)w',
        r'\\(\\mu-1\\)w\\s*-\\s*d\\sin\\theta',
        r'\\Delta\\s*L\\s*=\\s*d\\sin\\theta\\s*-\\s*\\(\\mu-1\\)w',
        r'\\Delta\\s*\\phi\\s*=\\s*\\frac{2\\pi}{\\lambda}\\s*\\(d\\sin\\theta\\s*-\\s*\\(\\mu-1\\)w\\)'
    ]

    # 检查是否存在错误的符号组合，例如 d*sin(theta) + (mu-1)w
    error_pattern = r'd\\sin\\theta\\s*\\+\\s*\\(\\mu-1\\)w'

    found_correct = False
    for p in patterns:
        if re.search(p, prediction):
            found_correct = True
            break

    if re.search(error_pattern, prediction):
        return {
            "result": "fail",
            "message": "介质引入的光程差符号错误，应为减去 (mu-1)w 而非相加",
            "evidence": re.search(error_pattern, prediction).group(0)
        }

    if found_correct:
        return {
            "result": "pass",
            "message": "正确识别了介质引入的光程差及其符号关系",
            "evidence": ""
        }

    return {
        "result": "inconclusive",
        "message": "未在预测中找到明确的干涉光程差公式",
        "evidence": ""
    }

