def check_exp_b3ad1e6c3ebc4e88_7c83a62e4170(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    trigger_keywords = ['类比', '势场', '轨迹', 'Maupertuis', 'Fermat', '费马原理']
    is_triggered = any(kw in question or kw in prediction for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到光学-力学类比场景", "evidence": ""}

    # 检查是否存在 v 正比于 1/n 的错误描述 (通常光速在介质中是 c/n，但类比动量时应为 v ∝ n)
    error_patterns = [
        r'v\s*\\propto\s*1/n',
        r'v\s*=\s*c/n',
        r'速度.*反比.*折射率',
        r'v\s*\\propto\s*n\^\{-1\}'
    ]

    # 检查是否存在正确的 v ∝ n 描述
    correct_patterns = [
        r'v\s*\\propto\s*n',
        r'v\s*=\s*kn',
        r'速度.*正比.*折射率',
        r'动量.*正比.*折射率'
    ]

    for ep in error_patterns:
        match = re.search(ep, prediction)
        if match:
            # 进一步确认是否在讨论类比轨迹而非真实光速
            if '类比' in prediction or '势能' in prediction or 'E_p' in prediction:
                return {
                    "result": "fail",
                    "message": "在光学-力学类比中，质点速度应正比于折射率(v ∝ n)以满足等价性，而非反比。",
                    "evidence": match.group(0)
                }

    for cp in correct_patterns:
        match = re.search(cp, prediction)
        if match:
            return {
                "result": "pass",
                "message": "正确识别了光学-力学类比中的速度映射规则。",
                "evidence": match.group(0)
            }

    return {"result": "inconclusive", "message": "无法确定速度与折射率的具体比例关系描述", "evidence": ""}

# rule_id=exp_ee22f41f8bbbd995 | domain=Optics | topic=Optics / Snell's Law and Critical Angle
def check_exp_ee22f41f8bbbd995_ed38e8fd315d(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 检查是否涉及蜃景、距离d或折射率n(z)
    keywords = ['mirage', '蜃景', 'distance', '距离', 'n(z)', 'refractive index']
    if not any(kw in prediction.lower() or kw in question.lower() for kw in keywords):
        return {"result": "inconclusive", "message": "未识别到蜃景距离相关物理场景", "evidence": ""}

    # 核心逻辑：寻找积分公式 d = integral(1/sqrt((n/C)^2 - 1))
    # 匹配特征：1/sqrt, n(z)^2, cos(theta), 积分符号
    patterns = [
        r"integral",
        r"1/sqrt",
        r"n\(z\)",
        r"cos\(theta\)",
        r"n\(z_min\)",
        r"dz/dx\s*=\s*0"
    ]

    match_count = 0
    for p in patterns:
        if re.search(p, prediction, re.IGNORECASE):
            match_count += 1

    # 检查极值点条件 n(z_min) = n(h)cos(theta)
    condition_pattern = r"n\(.*\)\s*=\s*n\(.*\)\s*\*?\s*cos"
    has_condition = re.search(condition_pattern, prediction, re.IGNORECASE)

    if match_count >= 2 or has_condition:
        # 进一步检查分母结构 (n/C)^2 - 1
        if "- 1" in prediction and "/" in prediction and "sqrt" in prediction:
            return {"result": "pass", "message": "公式符合蜃景临界距离积分判定逻辑", "evidence": "命中积分或极值点条件"}
        else:
            return {"result": "fail", "message": "计算距离的积分公式结构错误，缺少折射率比值平方减一的根号项", "evidence": prediction[:100]}

    return {"result": "inconclusive", "message": "无法确定是否正确应用了蜃景距离判定公式", "evidence": ""}

# rule_id=exp_1c82129c3722e1c4 | domain=Optics | topic=Optics / Total Internal Reflection
def check_exp_1c82129c3722e1c4_7bb25ffb225d(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 检查是否涉及全反射或衰减波场景
    keywords = ['total internal reflection', 'evanescent', '全反射', '衰减波', '有耗介质']
    is_relevant = any(kw in prediction.lower() or kw in sample.get('question', '').lower() for kw in keywords)
    if not is_relevant:
        return {'result': 'inconclusive', 'message': '未检测到全反射或衰减波相关上下文', 'evidence': ''}

    # 检查复数i转换逻辑：Re{i * exp(i*phi)} 应对应 -sin(phi)
    # 寻找类似 i*exp 或 i*e^{i...} 的表达式，并检查后续是否错误地保留了 cos 或符号错误
    # 典型错误：Re{i * exp(i*phi)} = cos(phi) 或 sin(phi) 而非 -sin(phi)
    patterns = [
        (r'i\\cdot e\^\{i\\phi\}.*?cos\\(\\phi\\)', '错误地将虚数项转换为余弦'),
        (r'i\\cdot e\^\{i\\phi\}.*?[^\\-]sin\\(\\phi\\)', '虚数项转换丢失负号'),
        (r'\\text{Re}\{i.*?\\}.*?cos', '复数提取实部逻辑可能错误')
    ]

    for pattern, msg in patterns:
        match = re.search(pattern, prediction)
        if match:
            return {
                'result': 'fail',
                'message': f'复数波矢实部提取错误: {msg}',
                'evidence': match.group(0)
            }

    # 检查正确转换的迹象
    correct_pattern = r'-\\sin\\(\\phi\\)|\\text{Re}\{i.*?\\}.*?-\\sin'
    if re.search(correct_pattern, prediction):
        return {
            'result': 'pass',
            'message': '复数波矢实部提取逻辑正确',
            'evidence': re.search(correct_pattern, prediction).group(0)
        }

    return {'result': 'inconclusive', 'message': '无法确定复数转换逻辑的正确性', 'evidence': ''}

# rule_id=exp_1cb0e93e3083210b | domain=Optics | topic=Optics / Total Internal Reflection
def check_exp_1cb0e93e3083210b_d2e587da1baf(sample: dict) -> dict:

    prediction = sample.get('prediction', '')

    # 检查是否触发：题目涉及电场cos和磁场sin的相位差异
    trigger_keywords = ['cos', 'sin', '电场', '磁场', '相位']
    if not all(re.search(kw, prediction) for kw in ['cos', 'sin']):
        return {"result": "inconclusive", "message": "未检测到cos/sin相位对比场景", "evidence": ""}

    # 检查逻辑：验证波矢k是否为虚数/复数，以及是否存在pi/2或90度相位差
    imaginary_k_pattern = r'(k[xyz]|波矢).*?(虚数|复数|imaginary|complex|e\^\{-\\alpha|衰减)'
    phase_diff_pattern = r'(相位差|phase difference).*?(\\pi/2|90|垂直|正交)'

    has_imaginary_k = re.search(imaginary_k_pattern, prediction, re.IGNORECASE)
    has_phase_diff = re.search(phase_diff_pattern, prediction, re.IGNORECASE)

    if has_imaginary_k and has_phase_diff:
        return {
            "result": "pass",
            "message": "逻辑一致：波矢为虚数且存在pi/2相位差",
            "evidence": f"{has_imaginary_k.group()} | {has_phase_diff.group()}"
        }
    elif has_imaginary_k and not has_phase_diff:
        return {
            "result": "fail",
            "message": "逻辑错误：波矢为虚数但未说明磁场与电场的相位差",
            "evidence": has_imaginary_k.group()
        }

    return {"result": "inconclusive", "message": "无法确定波矢性质或相位关系", "evidence": ""}

# rule_id=exp_2a28e21c9a90c8bd | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
def check_exp_2a28e21c9a90c8bd_6faef0f1b64f(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '无预测内容', 'evidence': ''}

    # 寻找包含能量平衡相关的公式片段，特别是涉及 pi R^2 和 sigma T^4 的部分
    # 典型错误：(1-a)S * 4*pi*R^2 = 4*pi*R^2 * sigma * T^4 (吸收面积错用为4piR2)
    # 或者 (1-a)S * pi*R^2 = pi*R^2 * sigma * T^4 (辐射面积错用为piR2)

    # 匹配吸收项 (左侧)
    abs_pattern = re.compile(r'S.*?\\pi.*?R\^2')
    # 匹配辐射项 (右侧)
    rad_pattern = re.compile(r'4.*?\\pi.*?R\^2.*?\\sigma.*?T\^4')

    # 检查是否存在错误的系数组合，例如左边出现了 4*pi*R^2
    wrong_abs_pattern = re.compile(r'\(.*?\).*?S.*?4.*?\\pi.*?R\^2')
    # 检查右边是否漏掉了 4
    wrong_rad_pattern = re.compile(r'=\s*\\pi.*?R\^2.*?\\sigma.*?T\^4')

    if re.search(wrong_abs_pattern, prediction):
        return {
            'result': 'fail',
            'message': '吸收功率错误使用了全表面积(4πR²)而非投影面积(πR²)',
            'evidence': re.search(wrong_abs_pattern, prediction).group()
        }

    if re.search(wrong_rad_pattern, prediction) and not re.search(r'4\s*\\pi', prediction.split('=')[-1] if '=' in prediction else ''):
        return {
            'result': 'fail',
            'message': '辐射功率错误使用了投影面积(πR²)而非全表面积(4πR²)',
            'evidence': re.search(wrong_rad_pattern, prediction).group()
        }

    # 检查正确模式
    correct_pattern = re.compile(r'S.*?\\pi.*?R\^2.*?=.*?4.*?\\pi.*?R\^2.*?\\sigma.*?T\^4')
    if re.search(correct_pattern, prediction):
        return {
            'result': 'pass',
            'message': '正确区分了吸收投影面积与辐射全表面积',
            'evidence': re.search(correct_pattern, prediction).group()
        }

    return {'result': 'inconclusive', 'message': '未检测到明确的能量平衡公式', 'evidence': ''}

# rule_id=exp_a7851d2f15d50857 | domain=Thermodynamics & Statistical Physics | topic=Blackbody Radiation and Stefan-Boltzmann Law
def check_exp_a7851d2f15d50857_8f10eb95fc53(sample: dict) -> dict:

    text = (sample.get('prediction', '') + ' ' + sample.get('answer', '')).lower()

    # 检查是否触发：涉及温度/功率/距离的微小变化 (如 1%, 2%, 0.01)
    trigger_keywords = ['stefan', 'boltzmann', 'radiation', '辐射', '温度', '功率']
    has_trigger = any(kw in text for kw in trigger_keywords)
    has_small_change = any(p in text for p in ['1%', '2%', '0.01', '0.02', '微小', 'small change'])

    if not (has_trigger and has_small_change):
        return {"result": "inconclusive", "message": "未检测到辐射平衡微扰场景", "evidence": ""}

    # 核心逻辑：dT/T = 1/4 * dP/P 或 P ∝ T^4 的微分形式
    # 检查是否提到了 1/4 或 4 倍的关系
    patterns = [
        r"1/4", r"0\.25", r"4\s*倍", r"4\s*times",
        r"delta\s*t/t", r"dt/t", r"dp/p",
        r"t\s*\+.*0\.25", r"p\s*\+.*4"
    ]

    found_logic = False
    evidence = ""
    for p in patterns:
        match = re.search(p, text)
        if match:
            found_logic = True
            evidence = match.group(0)
            break

    # 检查距离与温度的关系：距离增加 f, 温度下降 f/2 (因为 P ∝ 1/r^2, P ∝ T^4 => T ∝ r^-0.5)
    dist_logic = ('distance' in text or '距离' in text) and ('1/2' in text or '0.5' in text)

    if found_logic or dist_logic:
        return {"result": "pass", "message": "推导符合线性化比例关系", "evidence": evidence}
    else:
        return {"result": "fail", "message": "未发现正确的线性化比例关系 (如 dT/T = 1/4 dP/P)", "evidence": ""}

# rule_id=exp_349d56a129768a81 | domain=Thermodynamics & Statistical Physics | topic=First Law of Thermodynamics
def check_exp_349d56a129768a81_b46f6f3a3dfd(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 触发条件：涉及弹簧、线性压力、热容/比热
    trigger_keywords = ['弹簧', 'spring', '线性', 'linear', '热容', 'heat capacity', '比热']
    is_triggered = any(kw in question for kw in trigger_keywords) or any(kw in prediction for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到变力做功或热容分析触发词", "evidence": ""}

    # 核心逻辑检查：是否使用了 dQ = dU + PdV 或 C = Cv + P(dV/dT)
