# rule_id=exp_2a3efc7d3a4143ce | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / First Law of Thermodynamics
def check_exp_2a3efc7d3a4143ce_ea14425cc711(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '无预测内容', 'evidence': ''}

    # 匹配速率比值和温度比值的模式，例如 v1/v2 = sqrt(T1/T2) 或 v1:v2 = sqrt(T1):sqrt(T2)
    # 寻找类似 1/2, 1:2, sqrt(300/600) 等表达式
    ratio_pattern = r'([\d\.]+)\s*[:/]\s*([\d\.]+)'
    sqrt_pattern = r'sqrt\s*\(\s*([\d\.]+)\s*[:/]\s*([\d\.]+)\s*\)'

    ratios = re.findall(ratio_pattern, prediction)
    sqrts = re.findall(sqrt_pattern, prediction)

    if not ratios:
        return {'result': 'inconclusive', 'message': '未检测到明显的比值关系', 'evidence': ''}

    for v1_str, v2_str in ratios:
        try:
            v1, v2 = float(v1_str), float(v2_str)
            if v2 == 0: continue
            v_ratio = v1 / v2

            # 检查是否存在对应的温度比值 T1, T2
            # 逻辑：如果 v1/v2 = sqrt(T1/T2)，那么 (v1/v2)^2 应该等于 T1/T2
            # 寻找上下文中的温度数值
            temp_matches = re.findall(r'(\d+)\s*[Kk]', sample.get('question', '') + prediction)
            if len(temp_matches) >= 2:
                t1, t2 = float(temp_matches[0]), float(temp_matches[1])
                if t2 != 0:
                    t_ratio = t1 / t2
                    # 检查是否错误地使用了 v1/v2 = T1/T2
                    if abs(v_ratio - t_ratio) < 0.01 and abs(v_ratio - (t_ratio**0.5)) > 0.05:
                        return {'result': 'fail', 'message': '错误地使用了温度直接比而非平方根比', 'evidence': f'{v1}/{v2} approx {t1}/{t2}'}
                    # 检查是否正确使用了平方根比
                    if abs(v_ratio - (t_ratio**0.5)) < 0.02:
                        return {'result': 'pass', 'message': '符合分子速率温度幂次律', 'evidence': f'{v1}/{v2} = sqrt({t1}/{t2})'}
        except:
            continue

    return {'result': 'inconclusive', 'message': '无法确定计算逻辑是否违反幂次律', 'evidence': ''}

# rule_id=exp_2bde2a2056e8ebb9 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / First Law of Thermodynamics
def check_exp_2bde2a2056e8ebb9_ca1ca76d2303(sample: dict) -> dict:

    prediction = sample.get('prediction', '')

    # 检查是否涉及循环过程功的计算
    if not any(kw in prediction for kw in ['循环', '净功', 'W_net', 'cycle', 'net work']):
        return {"result": "inconclusive", "message": "未检测到循环过程功的相关描述", "evidence": ""}

    # 寻找梯形面积公式的特征：(P1+P2)*(V2-V1)/2 或类似的变体
    trapezoid_pattern = r'\(?P[12]\s*\+\s*P[12]\)?\s*\*\s*\(?V[12]\s*-\s*V[12]\)?\s*/\s*2'
    has_trapezoid = re.search(trapezoid_pattern, prediction, re.IGNORECASE)

    # 寻找净功等于各部分之和的逻辑特征
    sum_logic_pattern = r'W_?(net|总)\s*=\s*W_?[1234]?\s*\+\s*W_?[1234]?'
    has_sum_logic = re.search(sum_logic_pattern, prediction, re.IGNORECASE)

    # 如果提到了直线过程但没有使用梯形公式，或者没有体现功的代数和逻辑
    if '直线' in prediction or 'linear' in prediction:
        if not has_trapezoid:
            return {
                "result": "fail",
                "message": "直线过程应优先使用梯形面积公式计算功",
                "evidence": "未发现 (P1+P2)(V2-V1)/2 形式的计算"
            }

    if has_sum_logic or has_trapezoid:
        return {
            "result": "pass",
            "message": "计算逻辑符合循环过程净功校验规则",
            "evidence": (has_trapezoid.group(0) if has_trapezoid else "") + (has_sum_logic.group(0) if has_sum_logic else "")
        }

    return {"result": "inconclusive", "message": "无法确定计算逻辑是否严谨", "evidence": ""}

# rule_id=exp_6c1b3785ab4616b7 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / First Law of Thermodynamics
def check_exp_6c1b3785ab4616b7_40e859a8b3c7(sample: dict) -> dict:

    text = (sample.get('prediction', '') + ' ' + sample.get('answer', '')).lower()

    # 触发词检查
    triggers = ['绝热', '导热隔板', '单侧做功', '准静态']
    trigger_count = sum(1 for t in triggers if t in text)
    if trigger_count < 2:
        return {"result": "inconclusive", "message": "未检测到足够的绝热联动建模触发词", "evidence": ""}

    # 错误假设检查：是否错误假设了等温过程 (Isothermal)
    isothermal_keywords = ['等温', '温度不变', 't=constant', 'delta t = 0', 'dt=0']
    has_isothermal_assumption = any(k in text for k in isothermal_keywords)

    # 正确逻辑检查：绝热过程内能变化与功的关系
    adiabatic_logic = ['dq=0', 'du=-dw', 'du+pdv=0', 'ncvdt', 't*v^']
    has_adiabatic_logic = any(re.search(k.replace('*', '\\*'), text) for k in adiabatic_logic)

    if has_isothermal_assumption and not ('等温' in sample.get('question', '')):
        return {
            "result": "fail",
            "message": "在绝热联动系统中错误地假设了等温过程，违反了绝热做功导致内能变化的物理规律。",
            "evidence": "检测到等温假设关键词"
        }

    if has_adiabatic_logic:
        return {
            "result": "pass",
            "message": "系统识别并应用了绝热过程的能量守恒关系。",
            "evidence": "匹配到绝热能量守恒相关公式或描述"
        }

    return {"result": "inconclusive", "message": "无法确定建模逻辑是否正确", "evidence": ""}

# rule_id=exp_a7313c671f098b5d | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / First Law of Thermodynamics
def check_exp_a7313c671f098b5d_3fb9a971af5a(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    # 触发条件检查
    trigger_keywords = ['活塞', '腔室', '温度变化率', 'dV/dt', 'dT/dt']
    is_triggered = any(kw in question for kw in trigger_keywords)
    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到可动边界或温度变化率相关触发词", "evidence": ""}

    # 检查逻辑：寻找能量方程是否包含功项 P*dV/dt 或类似的膨胀功表达
    # 错误模式：直接使用 dQ = n*Cv*dT 而忽略了 P*dV
    work_terms = ['P*dV', 'P dV', 'p*dv', 'pdV', 'P\\frac{dV}{dt}', 'P(dV/dt)']
    energy_eq_patterns = ['dQ', 'dU', 'dE', 'Q =', 'E =']

    has_work_term = any(term in prediction for term in work_terms)
    has_energy_eq = any(eq in prediction for eq in energy_eq_patterns)

    # 如果提到了温度变化和体积变化，但公式中只有 nCvDT 而没有 PdV
    if 'dT' in prediction and 'dV' in prediction:
        if not has_work_term:
            return {
                "result": "fail",
                "message": "在可动边界系统中，能量方程似乎遗漏了功项 P*dV/dt，不能仅使用定容热容公式。",
                "evidence": prediction[:200]
            }

    if has_work_term and has_energy_eq:
        return {
            "result": "pass",
            "message": "模型正确考虑了功热耦合项 P*dV/dt。",
            "evidence": "检测到功项表达"
        }

    return {"result": "inconclusive", "message": "无法确定推导过程中是否正确处理了功热耦合", "evidence": ""}

# rule_id=exp_bbc810d481bc2196 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / First Law of Thermodynamics
def check_exp_bbc810d481bc2196_ff87dcefc136(sample: dict) -> dict:

    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()

    trigger_keywords = ['irreversible adiabatic', 'released to move freely', 'suddenly released', 'irreversible expansion']
    is_triggered = any(kw in question for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到不可逆绝热过程触发词", "evidence": ""}

    forbidden_patterns = [
        r'p\\s*v\\s*\\^\\s*\\gamma',
        r't\\s*v\\s*\\^\\s*\\(\\s*\\gamma\\s*-\\s*1\\s*\\)',
        r'p1\\s*v1\\^\\gamma',
        r'p2\\s*v2\\^\\gamma'
    ]

    for pattern in forbidden_patterns:
        if re.search(pattern, prediction):
            return {
                "result": "fail",
                "message": "不可逆绝热过程禁忌使用绝热状态方程(pV^gamma=C)，应使用热力学第一定律能量守恒。",
                "evidence": re.search(pattern, prediction).group(0)
            }

    required_patterns = [
        r'\\delta\\s*u\\s*=\\s*w',
        r'q\\s*=\\s*0',
        r'n\\s*c_?v\\s*\\(\\s*t_?2\\s*-\\s*t_?1\\s*\\)',
        r'p_?ext\\s*\\(\\s*v_?2\\s*-\\s*v_?1\\s*\\)'
    ]

    hit_count = sum(1 for p in required_patterns if re.search(p, prediction))
    if hit_count >= 1:
        return {"result": "pass", "message": "正确使用了能量守恒分析不可逆过程", "evidence": "detected energy conservation logic"}

    return {"result": "inconclusive", "message": "未发现明显的公式错误或正确推导过程", "evidence": ""}

# rule_id=exp_c6753f638356d35a | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / First Law of Thermodynamics
def check_exp_c6753f638356d35a_cc301f87f688(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')

    trigger_keywords = ['As shown in the figure', '如图所示', '图示']
    has_trigger = any(kw in question for kw in trigger_keywords)
    has_constants = 'P0' in (prediction + answer) or 'V0' in (prediction + answer) or 'P_0' in (prediction + answer) or 'V_0' in (prediction + answer)

    if not (has_trigger and has_constants):
        return {"result": "inconclusive", "message": "未触发图解题或特征常数匹配条件", "evidence": ""}

    # 检查是否在预测中体现了坐标比例提取，例如 P_A=2P_0 或 V_B/V_A=2 等模式
    # 匹配类似 P_A = 2P_0, V_B = 3V_0, P_B/P_A = 2 等数值化过程
    coordinate_patterns = [
        r'[PV]_[A-Za-z0-9]\s*=\s*\d+',
        r'[PV]_[A-Za-z0-9]\s*/\s*[PV]_[A-Za-z0-9]',
        r'\d+\s*[PV]_0'
    ]

    found_modeling = False
    evidence = ""
    for pattern in coordinate_patterns:
        match = re.search(pattern, prediction)
        if match:
            found_modeling = True
            evidence = match.group(0)
            break

    if found_modeling:
        return {"result": "pass", "message": "已从图中提取坐标比例关系并代入", "evidence": evidence}
    else:
        return {"result": "fail", "message": "未发现从PV图中提取顶点坐标比例关系的建模过程", "evidence": ""}

# rule_id=exp_d293ed2a7dd62d12 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / First Law of Thermodynamics
def check_exp_d293ed2a7dd62d12_e5d40e927533(sample: dict) -> dict:

    text = (sample.get('prediction', '') + ' ' + sample.get('answer', '')).lower()

    # 检查触发条件：绝热、体积固定
    is_adiabatic = '绝热' in text or 'adiabatic' in text
    is_fixed_volume = '体积不变' in text or '固定体积' in text or 'fixed volume' in text

    if not (is_adiabatic and is_fixed_volume):
        return {"result": "inconclusive", "message": "未识别到绝热且体积固定的前提条件", "evidence": ""}

    # 检查内能守恒逻辑
    internal_energy_conserved = '内能不变' in text or '内能守恒' in text or 'u1=u2' in text or 'delta u = 0' in text

    # 检查压强结论
    pressure_constant = '压强不变' in text or '总压强不变' in text or 'p1=p2' in text or 'p_i = p_f' in text

    if internal_energy_conserved:
        if pressure_constant:
            return {"result": "pass", "message": "符合绝热容器内能与压强关联律", "evidence": "识别到内能不变且压强不变"}
        elif '压强变化' in text or '压强改变' in text:
            return {"result": "fail", "message": "违反绝热容器内能与压强关联律：内能不变时压强应保持不变", "evidence": "识别到压强变化的描述"}

    return {"result": "inconclusive", "message": "无法从文本中明确判定内能与压强的逻辑关系", "evidence": ""}

# rule_id=exp_de6e0ca5a77a1103 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / First Law of Thermodynamics
def check_exp_de6e0ca5a77a1103_33d7864ff62e(sample: dict) -> dict:

    text = (sample.get('prediction', '') + ' ' + sample.get('answer', '')).lower()
    trigger_keywords = ['绝热', '混合', '温度']
    if not all(k in text for k in ['绝热', '混合']):
        return {'result': 'inconclusive', 'message': '未触发绝热混合场景', 'evidence': ''}

    def extract_values(pattern, content):
        return [float(x) for x in re.findall(pattern, content)]

    p_vals = extract_values(r'(\d+\.?\d*)\s*(?:pa|atm|kpa)', text)
    v_vals = extract_values(r'(\d+\.?\d*)\s*(?:l|m\^3|ml)', text)
    t_vals = extract_values(r'(\d+\.?\d*)\s*(?:k|℃)', text)

    if len(p_vals) >= 2 and len(v_vals) >= 2 and len(t_vals) >= 3:
        p1, p2 = p_vals[0], p_vals[1]
        v1, v2 = v_vals[0], v_vals[1]
        t1, t2 = t_vals[0], t_vals[1]
        t_eq_pred = t_vals[2]

        try:
            numerator = p1 * v1 + p2 * v2
            denominator = (p1 * v1 / t1) + (p2 * v2 / t2)
            t_eq_calc = numerator / denominator

            if abs(t_eq_calc - t_eq_pred) / t_eq_calc < 0.05:
                return {'result': 'pass', 'message': '混合后温度符合内能守恒律', 'evidence': f'计算值:{t_eq_calc}, 预测值:{t_eq_pred}'}
            else:
                return {'result': 'fail', 'message': '混合后温度违反内能守恒律', 'evidence': f'计算值:{t_eq_calc}, 预测值:{t_eq_pred}'}
        except ZeroDivisionError:
            return {'result': 'inconclusive', 'message': '计算过程出现除零错误', 'evidence': ''}

    return {'result': 'inconclusive', 'message': '缺乏足够的数值参数进行验证', 'evidence': ''}

# rule_id=exp_ee9def544645155f | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / First Law of Thermodynamics
def check_exp_ee9def544645155f_25b087562a27(sample: dict) -> dict:

    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()

    # 触发条件：题目要求计算吸热量（heat added/absorbed）而非净热量（net heat）
    trigger_keywords = ['heat added', 'heat absorbed', 'absorbed heat', 'total heat input', 'q_in']
    exclude_keywords = ['net heat', 'total heat transfer', 'q_net']

    is_triggered = any(kw in question for kw in trigger_keywords) and not any(kw in question for kw in exclude_keywords)
    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到吸热量计算的特定触发词", "evidence": ""}

    # 检查逻辑：是否错误地使用了净热量（包含负值或代数和）
    # 寻找预测中是否出现了 Q_net = Q1 + Q2 + ... 且其中包含负项的情况
    # 或者检查是否明确提到了只累加正值

    # 寻找数值或表达式中是否存在减法（可能代表净热量计算）
    # 这是一个启发式检查：如果预测中出现了类似 Q_in = Q_total 或包含了所有过程的求和（包括放热过程）

    has_sum_all = re.search(r'q_in\s*=\s*q_1\s*\+\s*q_2\s*\+\s*q_3', prediction)
    has_net_logic = 'net' in prediction or 'total' in prediction

    # 如果预测中出现了 "sum of all Q" 或类似的逻辑，而题目要求的是 "heat added"
    if has_net_logic and ('sum' in prediction or '+' in prediction):
        # 进一步检查是否排除了负值
        if 'positive' not in prediction and 'q > 0' not in prediction and 'q>0' not in prediction:
            return {
                "result": "fail",
                "message": "检测到可能混淆了吸热量(Q_in)与净热量(Q_net)，未明确仅累加正热量过程。",
                "evidence": prediction[:100]
            }

    if 'q > 0' in prediction or 'only positive' in prediction or 'absorbed' in prediction:
        return {
            "result": "pass",
            "message": "正确识别并区分了吸热量计算。",
            "evidence": ""
        }

    return {"result": "inconclusive", "message": "无法确定计算逻辑是否区分了吸热量与净热量", "evidence": ""}

# rule_id=exp_3bd2af80486d4900 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Heat Transfer (Conduction, Convection, Radiation)
def check_exp_3bd2af80486d4900_318ccddb5cd3(sample: dict) -> dict:

    text = (sample.get('prediction', '') + ' ' + sample.get('answer', '')).lower()
    trigger_keywords = ['estimate of an order of magnitude', 'order of magnitude estimate', '数量级估算']
    is_triggered = any(kw in text for kw in trigger_keywords)
    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到数量级估算触发词", "evidence": ""}

    # 检查热导率 k 的量级
    k_pattern = re.compile(r'k\s*=\s*([0-9\.e\^\+]+)')
    k_matches = k_pattern.findall(text)
    for val_str in k_matches:
        try:
            if '^' in val_str:
                parts = val_str.split('^')
                if len(parts) == 2:
                    val = float(parts[0]) ** float(parts[1])
                else:
                    continue
            else:
                val = float(val_str)

            if val > 5000 or val < 0.001:
                return {"result": "fail", "message": "热导率k的选取超出常规物理量级", "evidence": f"k={val_str}"}
        except:
            continue

    # 检查热流/功率边界
    power_pattern = re.compile(r'(\d+\.?\d*)\s*(kw|kilowatts|w|watts)')
    p_matches = power_pattern.findall(text)
    for val_str, unit in p_matches:
        try:
            val = float(val_str)
            if 'k' in unit:
                val *= 1000
            if any(x in text for x in ['egg', 'boil', 'food', '蛋']):
                if val > 2000:
                    return {"result": "fail", "message": "估算的加热功率远超物理常识边界", "evidence": f"{val_str} {unit}"}
        except:
            continue

    return {"result": "pass", "message": "数量级估算在合理范围内", "evidence": ""}

# rule_id=exp_4e9602ce8d30a1fc | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Heat Transfer (Conduction, Convection, Radiation)
def check_exp_4e9602ce8d30a1fc_3341f56275c9(sample: dict) -> dict:

    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '')

    # Trigger check: Heat flow or Heat flux
    is_heat_flow = 'heat flow' in question
    is_heat_flux = 'heat flux' in question

    if not (is_heat_flow or is_heat_flux):
        return {"result": "inconclusive", "message": "Not a heat flow/flux problem", "evidence": ""}

    # Extract units from prediction (e.g., W, W/m^2, W/m2, Watts)
    unit_pattern = r'(\bW\b|\bWatts?\b|\bW/m\^?2\b|\bW\s*m\^-2\b)'
    match = re.search(unit_pattern, prediction, re.IGNORECASE)

    if not match:
        return {"result": "inconclusive", "message": "No explicit unit found in prediction", "evidence": ""}

    found_unit = match.group(0).lower()
    is_flux_unit = '/' in found_unit or '^-2' in found_unit or 'm-2' in found_unit

    # Logic: Heat flux must be W/m^2. Heat flow is usually W.
    # If 'flux' is mentioned, unit must be W/m^2.
    if is_heat_flux and not is_flux_unit:
        return {
            "result": "fail",
            "message": "Heat flux requires power density units (W/m^2), but found power units.",
            "evidence": found_unit
        }

    # If 'flow' is mentioned but no area is provided, it often implies flux.
    # This is a heuristic check.
    if is_heat_flow and not is_heat_flux:
        has_area = re.search(r'(\barea\b|\bm\^?2\b|\bsurface\b)', question)
        if not has_area and not is_flux_unit:
            # If no area is given, it might be expecting flux (W/m^2)
            # But this is ambiguous, so we return inconclusive unless it's a clear mismatch
            return {"result": "inconclusive", "message": "Ambiguous heat flow unit without area context", "evidence": found_unit}

    return {"result": "pass", "message": "Unit matches the physical quantity type", "evidence": found_unit}

# rule_id=exp_500c807abe9aa3fe | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Heat Transfer (Conduction, Convection, Radiation)
def check_exp_500c807abe9aa3fe_9639e11c0d89(sample: dict) -> dict:

    prediction = sample.get('prediction', '')

    # 定义积分公式的核心特征：t, C, P(T), dT 以及积分符号
    # 匹配模式：t = ∫ (C/P) dT 或类似的变体
    integral_patterns = [
        r"t\s*=\s*\\int.*C\s*/\s*P\(T\).*dT",
        r"t\s*=\s*\\int.*\\frac{C}{P\(T\)}.*dT",
        r"dt\s*=\s*\\frac{C}{P\(T\)}\s*dT",
        r"\\int.*\\frac{C}{P}.*dT"
    ]

    # 定义严禁使用的简略齐次公式特征
    forbidden_patterns = [
        r"t\s*=\s*\\Delta Q\s*/\s*P_avg",
        r"t\s*=\s*\\Delta Q\s*/\s*P_initial",
        r"t\s*=\s*Q\s*/\s*P",
        r"t\s*=\s*C\s*\\Delta T\s*/\s*P"
    ]

    found_integral = False
    evidence = ""
    for pattern in integral_patterns:
        match = re.search(pattern, prediction)
        if match:
            found_integral = True
            evidence = match.group(0)
            break

    if not found_integral:
        return {
            "result": "fail",
            "message": "未发现符合要求的积分公式 t = ∫ (C / P(T)) dT",
            "evidence": ""
        }

    for f_pattern in forbidden_patterns:
        if re.search(f_pattern, prediction):
            return {
                "result": "fail",
                "message": "使用了严禁的简略齐次公式而非积分式",
                "evidence": re.search(f_pattern, prediction).group(0)
            }

    return {
        "result": "pass",
        "message": "正确使用了变功率冷却时间积分公式",
        "evidence": evidence
    }

# rule_id=exp_68018b42e8d4d9f0 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Heat Transfer (Conduction, Convection, Radiation)
def check_exp_68018b42e8d4d9f0_f012f7f5befd(sample: dict) -> dict:

    prediction = sample.get('prediction', '')

    # 检查是否涉及热容C和功率P(T)
    has_c = 'C' in prediction or '热容' in prediction
    has_p = 'P' in prediction or '功率' in prediction

    if not (has_c and has_p):
        return {"result": "inconclusive", "message": "未检测到热容或功率相关符号", "evidence": ""}

    # 检查是否使用了错误的平均功率简化公式
    wrong_pattern = r't\s*=\s*\\Delta Q\s*/\s*P'
    if re.search(wrong_pattern, prediction) or 'P_avg' in prediction:
        return {"result": "fail", "message": "错误地使用了平均功率公式而非积分建模", "evidence": "P_avg"}

    # 检查积分形式特征: t = integral(C/P dT)
    # 匹配特征：积分符号, C/P, dT
    integral_patterns = [
        r'\\int.*C\s*/\s*P',
        r'\\int.*\\frac{C}{P}',
        r'dt\s*=\s*C\s*/\s*P.*dT',
        r'dt\s*=\s*-\\frac{C}{P}.*dT'
    ]

    found_integral = False
    hit_text = ""
    for pattern in integral_patterns:
        match = re.search(pattern, prediction)
        if match:
            found_integral = True
            hit_text = match.group(0)
            break

    if found_integral:
        return {"result": "pass", "message": "正确建立了冷却时间积分模型", "evidence": hit_text}

    # 如果提到了微分方程 dQ = C dT = -P dt 也算对
    diff_eq = r'C\s*d[T|t].*P.*d[t|T]'
    if re.search(diff_eq, prediction):
        return {"result": "pass", "message": "建立了正确的微分方程", "evidence": "C dT = -P dt"}

    return {"result": "inconclusive", "message": "无法确定是否使用了正确的积分建模", "evidence": ""}

# rule_id=exp_d87e79a8e11e03fe | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Heat Transfer (Conduction, Convection, Radiation)
def check_exp_d87e79a8e11e03fe_0d4a84d47ad7(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    # 检查是否涉及 P-T 图像（压强-温度 或 功率-温度）
    is_pt_graph = re.search(r'[P|p][-][T|t]\s*(图像|图表|图|graph)', question + prediction)
    # 检查是否要求解时间相关量
    is_time_related = re.search(r'(时间|时长|time|duration|dt|\Delta t)', question)

    if not (is_pt_graph and is_time_related):
        return {"result": "inconclusive", "message": "未识别到 P-T 图像或时间相关求解目标", "evidence": ""}

    # 检查是否存在直接对 P-T 图像求面积的逻辑
    # 关键词：面积、积分、integral、area，且上下文包含 P 和 T
