# rule_id=exp_1e1993b292e01c6c | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Ideal Gas Law and Real Gas Behavior
def check_exp_1e1993b292e01c6c_afc3fb09b268(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    # 匹配形如 (26) 或 (x) 的占位符模式
    placeholder_pattern = r'\((\d+|[a-zA-Z])\)'
    placeholders = re.findall(placeholder_pattern, question)

    if not placeholders:
        return {"result": "inconclusive", "message": "未在题干中发现括号占位符", "evidence": ""}

    # 检查预测中是否错误地将占位符数字当作已知物理量参与计算
    # 例如：如果占位符是 (26)，而预测中出现了 26 且该数字在题干中没有其他物理意义
    for ph in placeholders:
        if ph.isdigit():
            # 构造一个简单的检查：如果预测中出现了该数字，且伴随物理单位或赋值逻辑
            # 但该数字在题干中仅作为序号出现
            search_str = ph
            if search_str in prediction:
                # 进一步判断该数字在题干中是否仅以 (n) 形式存在
                context_pattern = r'[^\d\.]' + re.escape(search_str) + r'[^\d\.]'
                # 如果题干中除了括号形式外没有该数字，但预测中使用了它
                if not re.search(context_pattern, question.replace('(' + search_str + ')', '')):
                    return {
                        "result": "fail",
                        "message": "预测可能误将占位符序号 " + search_str + " 当作已知物理量",
                        "evidence": "placeholder: (" + search_str + ")"
                    }

    return {"result": "pass", "message": "未发现占位符干扰逻辑错误", "evidence": ""}

# rule_id=exp_3d4fd9095d8457dc | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Ideal Gas Law and Real Gas Behavior
def check_exp_3d4fd9095d8457dc_0eb9b5e1ffcf(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 触发条件：题目涉及湿空气、质量占比、混合气体摩尔质量
    trigger_keywords = ['湿空气', '质量占比', '质量分数', '混合气体', '摩尔质量']
    is_triggered = any(kw in question for kw in trigger_keywords) or any(kw in prediction for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到混合气体质量占比相关场景", "evidence": ""}

    # 检查逻辑：是否错误地使用了摩尔质量的加权平均 (M = w1*M1 + w2*M2) 而非倒数加权 (1/M = w1/M1 + w2/M2)
    # 错误模式：直接相乘求和 (w * M_water + (1-w) * M_air)
    error_pattern = r'(\w+)\s*\*\s*M_(?:water|w)\s*\+\s*\(1\s*-\s*\1\)\s*\*\s*M_(?:air|a)'
    # 正确模式：倒数求和 (m/M_total = m1/M1 + m2/M2)
    correct_pattern = r'\/\s*M_(?:water|w)|\/\s*M_(?:air|a)'

    if re.search(error_pattern, prediction):
        return {
            "result": "fail",
            "message": "错误地对质量占比使用了摩尔质量直接加权平均，应使用物质的量求和法",
            "evidence": re.search(error_pattern, prediction).group(0)
        }

    if re.search(correct_pattern, prediction):
        return {
            "result": "pass",
            "message": "正确使用了物质的量求和或倒数加权法计算混合气体",
            "evidence": "检测到分母位置的摩尔质量计算"
        }

    return {"result": "inconclusive", "message": "无法确定计算逻辑是否正确", "evidence": ""}

