# rule_id=exp_62cde6afae64d445 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Ideal Gas Law and Real Gas Behavior
def check_exp_62cde6afae64d445_a13a9aaa0755(sample: dict) -> dict:

    text = (sample.get('prediction', '') + ' ' + sample.get('answer', '')).lower()

    # 检查触发条件：等压且等容
    is_isobaric = any(kw in text for kw in ['等压', '压强不变', '压强恒定', 'constant pressure', 'isobaric'])
    is_isochoric = any(kw in text for kw in ['等容', '体积不变', '体积恒定', 'constant volume', 'isochoric'])

    if not (is_isobaric and is_isochoric):
        return {"result": "inconclusive", "message": "未识别到等压且等容的触发条件", "evidence": ""}

    # 检查结论：总动能恒定/不变
    kinetic_energy_keywords = ['动能', 'kinetic energy', 'k =', 'k=']
    const_keywords = ['不变', '恒定', '守恒', 'constant', 'unchanged', 'remains the same']

    found_ke = any(kw in text for kw in kinetic_energy_keywords)
    found_const = any(kw in text for kw in const_keywords)

    # 检查错误逻辑：如果提到动能随温度变化（在P,V恒定时），则违反此规则
    violation = any(kw in text for kw in ['动能改变', '动能随温度', 'kinetic energy changes'])

    if found_ke and found_const and not violation:
        return {"result": "pass", "message": "正确识别等压等容下总动能恒定", "evidence": "等压且等容...动能不变"}
    elif violation:
        return {"result": "fail", "message": "错误认为等压等容下总动能随温度或其他因素改变", "evidence": ""}

    return {"result": "inconclusive", "message": "无法确定动能状态的描述", "evidence": ""}

# rule_id=exp_6947b3c72e660eec | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Ideal Gas Law and Real Gas Behavior
def check_exp_6947b3c72e660eec_b2379ed55ff7(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 检查是否触发：题目涉及静力平衡、中心压力、量级估计等关键词
    trigger_keywords = ['静力平衡', 'hydrostatic equilibrium', '中心压力', '量级估计', 'order of magnitude']
    is_triggered = any(kw in question or kw in prediction for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到静力平衡量级估算相关触发词", "evidence": ""}

    # 检查逻辑：是否将 dP/dr 替换为 Pc/R 或类似的差分形式
    # 检查公式特征：Pc ~ GMp/R 或 P ~ GM^2/R^4 等
    patterns = [
        r'P_c\s*[≈~=]\s*G\s*\*?\s*M\s*\*?\s*ρ\s*/\s*R',
        r'P_c\s*[≈~=]\s*G\s*\*?\s*M\s*\*?\s*M\s*/\s*R\s*\*\*\s*4',
        r'ΔP/Δr',
        r'P_c/R',
        r'dP/dr\s*≈\s*-P_c/R'
    ]

    found_logic = False
    evidence = ""
    for pattern in patterns:
        match = re.search(pattern, prediction)
        if match:
            found_logic = True
            evidence = match.group(0)
            break

    # 检查平均分子量 mu 是否被提及（在理想气体方程部分）
    mu_mentioned = 'μ' in prediction or 'mu' in prediction.lower() or '平均分子量' in prediction

    if found_logic:
        if mu_mentioned:
            return {"result": "pass", "message": "正确使用了静力平衡量级估算并考虑了平均分子量", "evidence": evidence}
        else:
            return {"result": "fail", "message": "使用了量级估算但未明确体现平均分子量 μ 的一致性检查", "evidence": evidence}

    return {"result": "inconclusive", "message": "无法确定是否正确应用了微分算子离散化逻辑", "evidence": ""}

# rule_id=exp_6a27076ef4036131 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Ideal Gas Law and Real Gas Behavior
def check_exp_6a27076ef4036131_43639f53de65(sample: dict) -> dict:

    text = sample.get('prediction', '') + ' ' + sample.get('answer', '')

    def extract_val(pattern, text):
        match = re.search(pattern, text)
        return float(match.group(1)) if match else None

    p_val = extract_val(r'P\s*=\s*([0-9.]+)\s*(?:Pa|kPa|bar)', text)
    rho_val = extract_val(r'ρ\s*=\s*([0-9.]+)\s*(?:kg/m3|kg/m\^3)', text)
    t_val = extract_val(r'T\s*=\s*([0-9.]+)\s*(?:K)', text)
    r_val = extract_val(r'R\s*=\s*([0-9.]+)\s*(?:J/kgK|J/kg·K)', text)

    if p_val is None or rho_val is None or t_val is None:
        return {"result": "inconclusive", "message": "未在文本中找到完整的P, rho, T参数", "evidence": ""}

    if rho_val * t_val == 0:
        return {"result": "inconclusive", "message": "分母为零", "evidence": ""}

    calculated_r = p_val / (rho_val * t_val)

    if r_val is not None:
        if abs(calculated_r - r_val) / r_val > 0.05:
            return {"result": "fail", "message": "计算得到的气体常数R与给定的R不一致", "evidence": f"P={p_val}, rho={rho_val}, T={t_val}, R_given={r_val}, R_calc={calculated_r}"}
        else:
            return {"result": "pass", "message": "气体常数逻辑自洽", "evidence": f"R_calc={calculated_r}"}

    standard_r = 287.0
    if abs(calculated_r - standard_r) / standard_r > 0.05:
        return {"result": "fail", "message": "隐含的气体常数与标准值287差异过大且未显式修正", "evidence": f"R_calc={calculated_r}"}

    return {"result": "pass", "message": "状态方程参数基本符合标准气体常数", "evidence": ""}

# rule_id=exp_8d20ef317c1cbc07 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Ideal Gas Law and Real Gas Behavior
def check_exp_8d20ef317c1cbc07_fa8a924a1f45(sample: dict) -> dict:

    prediction = sample.get('prediction', '')

    # 尝试提取关键物理量：P1, P_final, n1, n2, V1, V2
    # 简化逻辑：寻找 P_final / P1 的比例关系
    # 匹配模式如 "P_final = ...", "P1 = ...", "n1 = ..."

    def extract_num(pattern, text):
        match = re.search(pattern, text)
        return float(match.group(1)) if match else None

    p_final = extract_num(r'P(?:_final|总|f)\s*=\s*([\d\.]+)', prediction)
    p1 = extract_num(r'P(?:1|初|i)\s*=\s*([\d\.]+)', prediction)
    n1 = extract_num(r'n(?:1|A)\s*=\s*([\d\.]+)', prediction)
    n2 = extract_num(r'n(?:2|B)\s*=\s*([\d\.]+)', prediction)
    v1 = extract_num(r'V(?:1|A)\s*=\s*([\d\.]+)', prediction)
    v2 = extract_num(r'V(?:2|B)\s*=\s*([\d\.]+)', prediction)

    # 如果能提取到所有必要参数，进行等温混合校验
    if all(v is not None for v in [p_final, p1, n1, n2, v1, v2]):
        try:
            # 理论公式: P_final = (n1 + n2) * R * T / (V1 + V2)
            # P1 = n1 * R * T / V1
            # 比例关系: P_final / P1 = ((n1 + n2) / (V1 + V2)) * (V1 / n1)
            expected_ratio = ((n1 + n2) / (v1 + v2)) * (v1 / n1)
            actual_ratio = p_final / p1

            if abs(actual_ratio - expected_ratio) < 1e-4:
                return {"result": "pass", "message": "压力比例符合等温混合定律", "evidence": f"P_final/P1={actual_ratio}"}
            else:
                return {"result": "fail", "message": f"压力比例不符。预期:{expected_ratio}, 实际:{actual_ratio}", "evidence": ""}
        except ZeroDivisionError:
            return {"result": "inconclusive", "message": "分母为零，无法计算", "evidence": ""}

    # 针对 V1=V2 的特殊情况简化匹配
    if "V1=V2" in prediction or "体积相等" in prediction:
        if all(v is not None for v in [p_final, p1, n1, n2]):
            expected_ratio = (n1 + n2) / (2 * n1)
            actual_ratio = p_final / p1
            if abs(actual_ratio - expected_ratio) < 1e-4:
                return {"result": "pass", "message": "等体积混合压力比例正确", "evidence": f"ratio={actual_ratio}"}
            else:
                return {"result": "fail", "message": "等体积混合压力比例错误", "evidence": ""}

    return {"result": "inconclusive", "message": "未提取到足够的数值参数进行校验", "evidence": ""}

# rule_id=exp_903b9ad103bebe65 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Ideal Gas Law and Real Gas Behavior
def check_exp_903b9ad103bebe65_5b53b406c98f(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测文本为空', 'evidence': ''}

    # 定义核心物理量关键词和公式模式
    # 匹配 m = (p * V * M) / (R * T) 及其变体
    patterns = [
        r'm\s*=\s*\(?p_{?sv}?.*?V.*?M.*?\)?\s*/\s*\(?R.*?T\)?',
        r'm_{?sv}?\s*=\s*\\frac{[^}]*p_{?sv}?[^}]*V[^}]*M[^}]*}{[^}]*R[^}]*T[^}]*}',
        r'm\s*=\s*p\s*V\s*M\s*/\s*\(\s*R\s*T\s*\)'
    ]

    found_pattern = False
    evidence = ''
    for p in patterns:
        match = re.search(p, prediction, re.IGNORECASE)
        if match:
            found_pattern = True
            evidence = match.group(0)
            break

    # 检查是否提及饱和蒸气压 p_sv 和 气相体积 V
    keywords = ['p_sv', '饱和蒸气压', '体积', 'V']
    keyword_count = sum(1 for k in keywords if k in prediction)

    if found_pattern:
        return {
            'result': 'pass',
            'message': '预测中包含了正确的饱和蒸气质量计算公式',
            'evidence': evidence
        }
    elif keyword_count >= 2:
        return {
            'result': 'fail',
            'message': '未发现符合要求的理想气体状态方程计算饱和蒸气质量的公式',
            'evidence': ''
        }
    else:
        return {
            'result': 'inconclusive',
            'message': '未检测到足够的物理建模信息',
            'evidence': ''
        }

# rule_id=exp_a3ab98f4a1a4b451 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Ideal Gas Law and Real Gas Behavior
def check_exp_a3ab98f4a1a4b451_e0fce4979f36(sample: dict) -> dict:

    text = sample.get('prediction', '') + ' ' + sample.get('answer', '')

    # 提取数值的辅助正则
    num_pattern = r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?'

    # 尝试寻找 M_mix, w_i, M_i 的数值
    # 寻找类似 M_mix = 28.5 这种模式
    m_mix_match = re.search(r'M(?:_?mix)?\s*=\s*(' + num_pattern + r')', text)

    # 寻找质量分数 w 和 组分摩尔质量 M
    w_matches = re.findall(r'w_?\d*\s*=\s*(' + num_pattern + r')', text)
    m_i_matches = re.findall(r'M_?\d*\s*=\s*(' + num_pattern + r')', text)

    if not m_mix_match or not w_matches or not m_i_matches or len(w_matches) != len(m_i_matches):
        return {"result": "inconclusive", "message": "未找到足够的数值信息进行验证", "evidence": ""}

    try:
        m_mix_val = float(m_mix_match.group(1))
        ws = [float(x) for x in w_matches]
        ms = [float(x) for x in m_i_matches]

        if any(m <= 0 for m in ms) or m_mix_val <= 0:
            return {"result": "fail", "message": "摩尔质量必须大于0", "evidence": str(m_mix_val)}

        # 验证 1/M_mix = sum(w_i / M_i)
        expected_inv_m = sum(w / m for w, m in zip(ws, ms))
        actual_inv_m = 1.0 / m_mix_val

        # 允许 1% 的误差
        is_formula_correct = abs(actual_inv_m - expected_inv_m) < 0.01 * max(abs(expected_inv_m), 1e-9)

        # 验证范围约束: min(M_i) <= M_mix <= max(M_i)
        is_range_correct = min(ms) <= m_mix_val <= max(ms)

        if is_formula_correct and is_range_correct:
            return {"result": "pass", "message": "混合摩尔质量计算符合倒数加权公式且在合理区间内", "evidence": f"M_mix={m_mix_val}"}
        else:
            msg = "公式计算错误" if not is_formula_correct else "数值超出组分范围"
            return {"result": "fail", "message": msg, "evidence": f"M_mix={m_mix_val}, expected_inv={expected_inv_m}"}

    except Exception:
        return {"result": "inconclusive", "message": "数值解析异常", "evidence": ""}

# rule_id=exp_a88f99b62e7df910 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Ideal Gas Law and Real Gas Behavior
def check_exp_a88f99b62e7df910_c0ae334e6f82(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 检查是否涉及冷凝、饱和蒸汽压、降温等关键词
    keywords = ['冷凝', '饱和蒸汽压', '降温', '除湿', '质量', 'PV/RT']
    hit_keywords = [kw for kw in keywords if kw in prediction or kw in sample.get('question', '')]
    if not hit_keywords:
        return {"result": "inconclusive", "message": "未检测到冷凝建模相关关键词", "evidence": ""}

    # 检查是否包含理想气体状态方程变形计算质量的逻辑特征
    # 模式1: m = M * (P1*V/RT1 - P2*V/RT2) 或其变体
    patterns = [
        r"m\s*=\s*M\s*\*?\s*\(\s*P1\*V/\(R\*T1\)\s*-\s*P2\*V/\(R\*T2\)\s*\)",
        r"n\s*=\s*PV/RT",
        r"\\Delta n\s*=\s*\\frac{P_1V}{RT_1}\s*-\s*\\frac{P_2V}{RT_2}",
        r"m\s*=\s*M\s*\\Delta n"
    ]

    found_pattern = False
    evidence = ""
    for p in patterns:
        match = re.search(p, prediction.replace(' ', ''))
        if match:
            found_pattern = True
            evidence = match.group(0)
            break

    if found_pattern:
        return {"result": "pass", "message": "模型正确应用了理想气体方程计算冷凝质量", "evidence": evidence}

    # 如果有计算过程但公式不匹配，可能存在建模错误
    if 'P' in prediction and 'V' in prediction and 'T' in prediction and ('m' in prediction or 'M' in prediction):
        return {"result": "fail", "message": "涉及冷凝计算但未发现正确的理想气体状态方程差值建模", "evidence": ""}

    return {"result": "inconclusive", "message": "无法确定建模逻辑是否符合规则", "evidence": ""}

# rule_id=exp_df2e8113b0b071c6 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Ideal Gas Law and Real Gas Behavior
def check_exp_df2e8113b0b071c6_a7dbd1030437(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 检查是否建立了质量守恒与分压/状态方程的关联
    # 核心逻辑：m = sum(m_i) = sum(P_i * V * mu_i / RT)
    # 匹配特征：m_0 或 m_total 等于 两个及以上分压项之和
    patterns = [
        r'm.*=.*P_.*V.*mu.*/.*RT.*\+.*P_.*V.*mu.*/.*RT',
        r'm.*=.*\\frac{P.*V.*\\mu}{RT}.*\+.*\\frac{P.*V.*\\mu}{RT}',
        r'P_.*\+.*P_.*=.*P_total',
        r'm_.*\+.*m_.*=.*m_total'
    ]

    found_logic = False
    for p in patterns:
        if re.search(p, prediction, re.IGNORECASE):
            found_logic = True
            break

    # 检查是否违规直接假设了总压（在没有解出分量前）
    # 如果文本中直接出现 "假设 P_total =" 或 "令 P =" 且没有上述方程，则可能违规
    violation_pattern = r'(假设|令|assume).*P_total.*='
    has_violation = re.search(violation_pattern, prediction)

    if found_logic:
        return {
            "result": "pass",
            "message": "建立了质量守恒与分压定律的联立关系",
            "evidence": ""
        }
    elif has_violation:
        return {
            "result": "fail",
            "message": "严禁在未解出各组分质量前假设总压",
            "evidence": ""
        }
    else:
        return {
            "result": "inconclusive",
            "message": "未检测到明确的混合气体质量守恒方程推导",
            "evidence": ""
        }

# rule_id=exp_e44ed0cc24b4d693 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Ideal Gas Law and Real Gas Behavior
def check_exp_e44ed0cc24b4d693_83e1f1da0cc7(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 检查是否涉及浮力平衡场景
    keywords = ['热气球', '浮力', '密度差', 'buoyancy', 'density difference']
    if not any(kw in prediction or kw in sample.get('question', '') for kw in keywords):
        return {'result': 'inconclusive', 'message': '未识别到浮力平衡相关场景', 'evidence': ''}

    # 匹配核心公式逻辑: (rho_out - rho_in) * V = m 或 delta_rho = m / V
    # 匹配模式1: delta_rho = m / V
    pattern1 = r'(\\Delta\\rho|\u0394\rho|delta_rho)\s*=\s*m[^/]*\/\s*V'
    # 匹配模式2: (rho_out - rho_in) * V = m
    pattern2 = r'\(\s*\\rho_out\s*-\s*\\rho_in\s*\)\s*\*?\s*V\s*=\s*m'
    # 匹配模式3: m = (rho_out - rho_in) * V
    pattern3 = r'm\s*=\s*\(\s*\\rho_out\s*-\s*\\rho_in\s*\)\s*\*?\s*V'

    found_pattern = None
    for p in [pattern1, pattern2, pattern3]:
        match = re.search(p, prediction)
        if match:
            found_pattern = match.group(0)
            break

    if found_pattern:
        return {
            'result': 'pass',
            'message': '正确建立了密度差与负载质量的直接关联公式',
            'evidence': found_pattern
        }
    else:
        # 如果提到了浮力但没有使用简化的密度差公式，可能存在建模冗余
        if 'F_b' in prediction or 'mg' in prediction:
            return {
                'result': 'fail',
                'message': '建议直接使用 (ρ_out - ρ_in) * V = m 建立关联，避免中间变量导致的精度损失',
                'evidence': ''
            }
        return {'result': 'inconclusive', 'message': '未检测到明确的密度差关联公式', 'evidence': ''}

# rule_id=exp_f6c91f3f2ef2b14d | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Ideal Gas Law and Real Gas Behavior
def check_exp_f6c91f3f2ef2b14d_5aea94823839(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 检查是否涉及密闭容器、蒸发、空气混合等关键词
    keywords = ['密闭', '容器', '蒸发', '饱和汽', '混合']
    is_relevant = any(kw in question for kw in keywords) or any(kw in prediction for kw in keywords)
    if not is_relevant:
        return {"result": "inconclusive", "message": "未检测到密闭容器或蒸发相关场景", "evidence": ""}

    # 检查是否错误地假设总压等于大气压 P0 (通常在密闭容器中不成立)
    # 匹配类似 P = P0, P_total = P0, 总压等于大气压 等表述
    p0_assumption = re.search(r'(P|p|总压|压强)\s*=\s*(P_0|p_0|P0|p0|大气压|1\.01|101)', prediction)

    # 检查是否应用了道尔顿分压定律 P = P_air + P_vapor
    dalton_pattern = re.search(r'(P|p|总压)\s*=\s*(P|p)_(air|a|空气)\s*\+\s*(P|p)_(v|sv|vapor|汽)', prediction)

    if p0_assumption and not dalton_pattern:
        return {
            "result": "fail",
            "message": "在密闭容器场景下错误地假设总压等于环境大气压，未应用分压求和准则",
            "evidence": p0_assumption.group(0)
        }

    if dalton_pattern:
        return {
            "result": "pass",
            "message": "正确应用了分压求和准则",
            "evidence": dalton_pattern.group(0)
        }

    return {"result": "inconclusive", "message": "无法确定是否正确应用了分压求和逻辑", "evidence": ""}

# rule_id=exp_2654a3ffd2e6ff87 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Kinetic Theory of Gases
def check_exp_2654a3ffd2e6ff87_c0b49bab6858(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 检查是否触发：题目要求具体数值阈值
    trigger_keywords = ['At which values', 'calculate', 'numerical', '数值', '计算']
    is_triggered = any(kw.lower() in question.lower() for kw in trigger_keywords)
    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到数值计算触发词", "evidence": ""}

    # 检查是否包含空气平均摩尔质量 M (28.8-29.0 g/mol 或 0.0288-0.029 kg/mol)
    # 检查是否包含重力加速度 g (9.8 或 9.81)
    m_pattern = r'(28\.[89]|29|0\.028[89]|0\.029)'
    g_pattern = r'(9\.8|9\.81)'

    has_m = re.search(m_pattern, prediction) is not null
    has_g = re.search(g_pattern, prediction) is not null

    # 检查是否仅停留在字母表达式 (简单判断是否包含公式符号但缺乏数值)
    has_symbols = all(s in prediction for s in ['M', 'g', 'R'])

    if has_m and has_g:
        return {
            "result": "pass",
            "message": "已包含空气摩尔质量和重力加速度的数值代入",
            "evidence": f"M_match: {has_m}, g_match: {has_g}"
        }
    elif has_symbols:
        return {
            "result": "fail",
            "message": "仅检测到字母表达式，未发现空气摩尔质量(29g/mol)或重力加速度(9.8)的数值代入",
            "evidence": prediction
        }
    else:
        return {
            "result": "inconclusive",
            "message": "无法确定是否进行了数值代入",
            "evidence": ""
        }

# rule_id=exp_2b12b2e417cd5aa6 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Kinetic Theory of Gases
def check_exp_2b12b2e417cd5aa6_3263e209c9a0(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 匹配 U = 3/2 * Integral(P dV) 的各种变体
    # 匹配模式包括: U=3/2PV, U=1.5PV, U=3/2\int P dV, U=1.5\int P dV
    patterns = [
        r'U\s*=\s*(3/2|1\.5)\s*\*?\s*P\s*V',
        r'U\s*=\s*(3/2|1\.5)\s*\*?\s*\\int\s*P\s*d[Vv]',
        r'U\s*=\s*(3/2|1\.5)\s*\*?\s*\\int\s*P\s*dV',
        r'U\s*=\s*\\int\s*(3/2|1\.5)\s*P\s*d[Vv]'
    ]

    found_correct = False
    evidence = ''
    for p in patterns:
        match = re.search(p, prediction)
        if match:
            found_correct = True
            evidence = match.group(0)
            break

    # 检查是否存在错误的系数，如 1/2, 5/2
    wrong_patterns = [
        r'U\s*=\s*(1/2|0\.5|5/2|2\.5)\s*\*?\s*\\int\s*P\s*d[Vv]',
        r'U\s*=\s*(1/2|0\.5|5/2|2\.5)\s*\*?\s*P\s*V'
    ]

    for wp in wrong_patterns:
        w_match = re.search(wp, prediction)
        if w_match:
            return {
                'result': 'fail',
                'message': '内能系数错误，单原子分子应为3/2',
                'evidence': w_match.group(0)
            }

    if found_correct:
        return {
            'result': 'pass',
            'message': '符合单原子理想气体内能积分公式',
            'evidence': evidence
        }

    return {
        'result': 'inconclusive',
        'message': '未发现明确的内能积分表达式',
        'evidence': ''
    }

# rule_id=exp_2fd345bf551aef67 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Kinetic Theory of Gases
def check_exp_2fd345bf551aef67_a4c54c044bc1(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 匹配 exp(-...) 或 e^(-...) 结构
    exp_patterns = [r'exp\(([^\)]+)\)', r'e\^\{?([^\}\s]+)\}?']

    found_exp = False
    for pattern in exp_patterns:
        matches = re.findall(pattern, prediction)
        if matches:
            found_exp = True
            for content in matches:
                # 检查指数项中是否包含高度 h 以及对应的特征高度项组合
                # 特征高度项通常包含 R, T, mu, g 或 k, T, m, g
                has_h = 'h' in content
                # 检查分母结构，寻找除法符号或负幂次
                has_division = '/' in content or '^-1' in content or '\\frac' in content
                # 检查物理常数组合 (RT/mg, kT/mg, RT/\mu g 等)
                has_constants = any(c in content for c in ['R', 'k', 'T', 'g', 'm', 'mu', '\\mu'])

                # 如果有指数项但没有除法结构，或者只有 h 没有常数项，则可能量纲错误
                if has_h and not (has_division and has_constants):
                    return {
                        'result': 'fail',
                        'message': '指数项必须为无量纲量，高度 h 需除以特征高度项(如RT/μg)',
                        'evidence': content
                    }

    if not found_exp:
        return {'result': 'inconclusive', 'message': '未检测到指数分布公式', 'evidence': ''}

    return {'result': 'pass', 'message': '指数项符合无量纲要求', 'evidence': ''}

# rule_id=exp_6db17c9895e69949 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Kinetic Theory of Gases
def check_exp_6db17c9895e69949_b8d6a5c2cc5b(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 搜索 dp/dr 的表达式或描述
    # 匹配模式如 dp/dr = ..., dp/dr > 0, dp/dr < 0
    dpdr_pattern = re.compile(r'dp/dr\s*([=><])\s*([^\s,;]+)')
    match = dpdr_pattern.search(prediction)

    if not match:
        return {"result": "inconclusive", "message": "未在预测中找到 dp/dr 的明确表达式", "evidence": ""}

    operator = match.group(1)
    expression = match.group(2).lower()

    # 检查逻辑：dp/dr 应该与 r 同号，即在 r>0 时 dp/dr > 0
    # 如果表达式中包含负号且没有抵消项，或者明确写着 dp/dr < 0，则判定为错误
    if operator == '<' or (operator == '=' and expression.startswith('-')):
        # 排除 rho * omega^2 * r 这种正项但带负号的情况（如 -rho... 是错的）
        return {
            "result": "fail",
            "message": "压力梯度 dp/dr 符号错误。在旋转流体中，压力随半径增加而增加以平衡离心力，dp/dr 应为正。",
            "evidence": match.group(0)
        }

    if 'rho' in expression and 'omega' in expression and 'r' in expression:
        if '-' not in expression:
            return {
                "result": "pass",
                "message": "压力梯度符号正确且符合物理公式。",
                "evidence": match.group(0)
            }

    return {"result": "inconclusive", "message": "无法确定 dp/dr 符号的物理正确性", "evidence": match.group(0)}

# rule_id=exp_6e915c3392cb7cb9 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Kinetic Theory of Gases
def check_exp_6e915c3392cb7cb9_765420e746c1(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {"result": "inconclusive", "message": "无预测结果", "evidence": ""}

    # 匹配数值及其单位，支持科学计数法
    # 匹配模式：数字 + (可选空格) + (m/s 或 m.s^-1 或 ms^-1)
    pattern = r'([+-]?\\d*\\.?\\d+(?:[eE][+-]?\\d+)?)\\s*(m/s|m\\.s\^?-1|ms\^?-1)'
    matches = re.findall(pattern, prediction)

    if not matches:
        return {"result": "inconclusive", "message": "未在结果中识别到速率数值及单位", "evidence": ""}

    # 检查是否涉及常温气体（300K左右）的上下文
    context_text = (sample.get('question', '') + sample.get('context', '')).lower()
    is_room_temp = any(x in context_text for x in ['300k', '300 k', '常温', 'room temperature', '27℃', '27摄氏度'])
    is_common_gas = any(x in context_text for x in ['n2', 'o2', 'air', '氮气', '氧气', '空气'])

    if not (is_room_temp or is_common_gas):
        return {"result": "inconclusive", "message": "未识别到常温或常见气体背景", "evidence": ""}

    for val_str, unit in matches:
        try:
            val = float(val_str)
            # 检查是否在 300-600 范围外且数量级过大
            if val >= 10000:
                return {
                    "result": "fail",
                    "message": "速率数量级异常偏高(>=10^4)，可能存在单位换算或开方错误",
                    "evidence": val_str + " " + unit
                }
            # 如果在常温常见气体背景下，数值显著偏离 300-600 范围
            if val < 100 or (val > 1000 and val < 10000):
                 return {
                    "result": "fail",
                    "message": "常温气体速率偏离合理范围(300-600 m/s)",
                    "evidence": val_str + " " + unit
                }
        except ValueError:
            continue

    return {"result": "pass", "message": "速率数值在合理数量级范围内", "evidence": ""}

# rule_id=exp_77b95aa27dc23169 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Kinetic Theory of Gases
def check_exp_77b95aa27dc23169_25dec529a68c(sample: dict) -> dict:

    text = sample.get('prediction', '') + ' ' + sample.get('answer', '')

    # 定义关键模式
    pattern_n = r'n\s*=\s*P\s*/\s*\(?k\s*T\)?'
    pattern_v = r'v\s*=\s*sqrt\(8\s*k\s*T\s*/\s*\(?π\s*m\)?\)'
    pattern_j_raw = r'J\s*=\s*\(?1/4\)?\s*\*?\s*n\s*\*?\s*v'
    pattern_j_final = r'P\s*/\s*sqrt\(2\s*π\s*m\s*k\s*T\)'

    # 检查是否涉及撞击率推导
    if not re.search(r'[Jj]\s*=', text) or not re.search(r'[Pp]', text):
        return {"result": "inconclusive", "message": "未检测到撞击率 J 与压强 P 的推导过程", "evidence": ""}

    # 检查代换逻辑
    has_n = bool(re.search(pattern_n, text, re.IGNORECASE))
    has_v = bool(re.search(pattern_v, text, re.IGNORECASE))
    has_j_raw = bool(re.search(pattern_j_raw, text, re.IGNORECASE))

    # 检查最终系数简化
    has_correct_final = bool(re.search(pattern_j_final, text, re.IGNORECASE))

    # 逻辑判断
    if has_n and has_v and has_j_raw:
        if has_correct_final:
            return {"result": "pass", "message": "正确联立 n=P/kT 和平均速率并完成了系数简化", "evidence": "J = P/sqrt(2πmkT)"}
        else:
            # 如果有推导但结果系数不对
            if "1/4" in text and "sqrt(8)" in text and "sqrt(2" not in text:
                return {"result": "fail", "message": "未正确将 1/4 * sqrt(8) 简化为 1/sqrt(2π)", "evidence": "检测到原始系数但未见简化结果"}
            return {"result": "inconclusive", "message": "推导过程不完整或简化结果不匹配", "evidence": ""}

    return {"result": "inconclusive", "message": "推导步骤不完整，无法验证一致性", "evidence": ""}

# rule_id=exp_82cbd563376b6d5c | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Kinetic Theory of Gases
def check_exp_82cbd563376b6d5c_29fc970896ac(sample: dict) -> dict:
    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '无预测内容', 'evidence': ''}

    # 提取可能的数学表达式行或步骤
    steps = [s.strip() for s in re.split(r'\n|\\\\|=>', prediction) if len(s.strip()) > 5]

    if len(steps) < 4:
        return {'result': 'pass', 'message': '步骤较少，未发现死循环', 'evidence': ''}

    # 简化表达式结构以检测重复（去除空格、统一括号、忽略微小常数差异）
    def simplify_structure(text):
        text = re.sub(r'\s+', '', text)
        # 将数字替换为占位符，关注代数结构
        text = re.sub(r'\d+\.?\d*', 'N', text)
        return text

    structures = [simplify_structure(s) for s in steps]

    # 检测连续3次以上的结构重复或极高相似度
    repeat_count = 0
    last_struct = ""
    evidence_segment = ""

    for i in range(len(structures)):
        if structures[i] == last_struct and len(last_struct) > 0:
            repeat_count += 1
            if repeat_count >= 2: # 连续三次相同（初始一次 + 两次重复）
                evidence_segment = steps[i-2] + " -> " + steps[i-1] + " -> " + steps[i]
                return {
                    'result': 'fail',
                    'message': '检测到代数化简死循环：表达式结构连续多次无实质变化',
                    'evidence': evidence_segment
                }
        else:
            repeat_count = 0
        last_struct = structures[i]

    # 检查震荡模式 (A -> B -> A -> B)
    for i in range(len(structures) - 3):
        if structures[i] == structures[i+2] and structures[i+1] == structures[i+3]:
            return {
                'result': 'fail',
                'message': '检测到代数化简震荡死循环',
                'evidence': steps[i] + " ... " + steps[i+2]
            }

    return {'result': 'pass', 'message': '未发现明显的化简死循环', 'evidence': ''}

# rule_id=exp_98b1af0b61062e14 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Kinetic Theory of Gases
def check_exp_98b1af0b61062e14_d70e73d82d4d(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 检查是否涉及压强随高度变化的建模
    keywords = ['dp/dh', 'dp/dz', 'dp', 'dh', '压强', '高度', '密度']
    if not any(kw in prediction for kw in keywords):
        return {"result": "inconclusive", "message": "未检测到流体静力学建模过程", "evidence": ""}

    # 检查符号一致性：dp/dh = -rho*g 或 dp = -rho*g*dh
    # 匹配 dp/dh = rho*g (错误) 或 dp/dh = -rho*g (正确)
    pos_pattern = r'dp/d[hz]\s*=\s*\+?\s*ρ?\s*g'
    neg_pattern = r'dp/d[hz]\s*=\s*-\s*ρ?\s*g'

    # 检查状态方程代换 rho = PM/RT
    substitution_pattern = r'ρ\s*=\s*P\s*M\s*/\s*\(R\s*T\)'

    has_pos = re.search(pos_pattern, prediction)
    has_neg = re.search(neg_pattern, prediction)

    if has_pos and not has_neg:
        return {"result": "fail", "message": "流体静力学方程符号错误，随高度增加压强应减小", "evidence": has_pos.group()}

    # 检查是否正确代换了密度
    if 'ρ' in prediction and 'P' in prediction and 'R' in prediction:
        if not re.search(r'dp/d[hz]\s*=\s*-\s*\(\s*P\s*M\s*g\s*\)\s*/\s*\(\s*R\s*T\s*\)', prediction.replace(' ', '')):
            if not re.search(substitution_pattern, prediction):
                return {"result": "fail", "message": "未发现密度 rho 向压强 P 的正确状态方程代换", "evidence": ""}

    if has_neg:
        return {"result": "pass", "message": "流体静力学方程符号正确且包含代换逻辑", "evidence": has_neg.group()}

    return {"result": "inconclusive", "message": "无法确定方程一致性", "evidence": ""}

# rule_id=exp_c63bed7bff2951f8 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Kinetic Theory of Gases
def check_exp_c63bed7bff2951f8_a02a98d85e8b(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    # 检查是否涉及密度随高度变化的相关关键词
    keywords = ['密度', '高度', '梯度', 'dρ/dz', 'density', 'height', 'gradient']
    if not any(kw in question for kw in keywords):
        return {"result": "inconclusive", "message": "未识别到密度梯度相关背景", "evidence": ""}

    # 识别题目中关于不稳定的特定条件：密度随高度增加 (dρ/dz > 0)
    # 匹配模式：密度随高度增加、dρ/dz > 0、density increases with height
    instability_condition = re.search(r'(密度随高度增加|dρ/dz\s*>\s*0|density\s+increases\s+with\s+height)', question)

    if instability_condition:
        evidence = instability_condition.group(0)
        # 检查预测中是否正确关联了“不稳定”或“对流”
        # 如果题目定义了dρ/dz > 0为不稳定，而预测说它是稳定的，则逻辑错误
        if '稳定' in prediction and '不稳定' not in prediction:
            return {"result": "fail", "message": "预测与题目定义的密度梯度不稳定判据冲突", "evidence": evidence}
        if '对流' in prediction or '不稳定' in prediction:
            return {"result": "pass", "message": "预测符合题目定义的不稳定判据", "evidence": evidence}

    return {"result": "inconclusive", "message": "无法确定预测是否违反密度梯度逻辑", "evidence": ""}

