# rule_id=exp_ee6f3f265e5f5ba2 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Kinetic Theory of Gases
def check_exp_ee6f3f265e5f5ba2_979d1bdbc84b(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 检查是否触发规则：题目中是否提及分子流量、单位时间粒子数或 N* = 1/4 n v_bar
    trigger_keywords = ['分子流量', '单位时间', '粒子数', '1/4', 'n', 'v']
    is_triggered = any(kw in question for kw in trigger_keywords) or 'N' in question

    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到分子流量相关触发条件", "evidence": ""}

    # 核心逻辑：验证最终表达式是否等价于 N = pS / sqrt(2 * pi * m * kB * T)
    # 考虑到 v_bar = sqrt(8 * kB * T / (pi * m))
    # N = 1/4 * (p / (kB * T)) * sqrt(8 * kB * T / (pi * m)) * S
    # N = p * S / sqrt(2 * pi * m * kB * T)

    # 搜索预测结果中是否存在类似的公式结构
    # 匹配特征：p, S 在分子；m, T, kB, pi 在分母且在根号下；系数包含 2 或 pi
    patterns = [
        r'p.*S.*sqrt.*2.*pi.*m.*k.*T',
        r'p.*S.*\\sqrt.*2.*\\pi.*m.*k.*T',
        r'\\frac{p.*S}{.*sqrt{2.*pi.*m.*k.*T}}',
        r'1/4.*n.*v.*S'
    ]

    found_match = False
    matched_text = ""
    for pattern in patterns:
        match = re.search(pattern, prediction, re.IGNORECASE)
        if match:
            found_match = True
            matched_text = match.group(0)
            break

    if found_match:
        return {
            "result": "pass",
            "message": "公式符合分子流量一致性要求",
            "evidence": matched_text
        }
    else:
        # 如果提到了相关物理量但公式不匹配，则可能存在建模错误
        if 'p' in prediction and 'S' in prediction and ('T' in prediction or 'm' in prediction):
            return {
                "result": "fail",
                "message": "分子流量公式建模错误，未满足 N = pS / sqrt(2*pi*m*kB*T)",
                "evidence": prediction[:100]
            }

    return {"result": "inconclusive", "message": "无法确定公式一致性", "evidence": ""}

# rule_id=exp_53c4a9740c13da96 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Phase Transitions and Latent Heat
def check_exp_53c4a9740c13da96_742426c05e40(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    # 检查题目是否涉及多种物态或物质
    phase_keywords = ['冰', '水', '汽', '固', '液', '气', '混合', '熔化', '凝固']
    has_multiple_phases = any(kw in question for kw in phase_keywords)

    if not has_multiple_phases:
        return {"result": "inconclusive", "message": "未识别到多物态场景", "evidence": ""}

    # 检查题目是否只给出了一个比热容符号（如 c 或 C）
    # 匹配类似 "比热容为c" 或 "比热容c" 的描述
    c_symbols = re.findall(r'[比热容][为是]?([cC])', question)
    unique_c_in_q = set(c_symbols)

    # 如果题目只给了一个比热容符号，但涉及多物态，检查预测中是否区分了变量
    if len(unique_c_in_q) == 1:
        single_c = list(unique_c_in_q)[0]
        # 修复 f-string 包含反斜杠的问题：将正则表达式模式预先定义
        # 检查预测中是否出现了区分下标，如 c1, c2, c_s, c_l 等
        distinguished_pattern = single_c + r'[_\{\dsa-z]+'
        pattern_distinguished = re.compile(distinguished_pattern)
        has_distinguished = bool(pattern_distinguished.search(prediction))

        # 检查是否在等式中直接使用了同一个 c 且没有体现出不同物质的差异
        if not has_distinguished and '=' in prediction:
            # 寻找类似 m*c*deltaT = m*c*deltaT 的结构
            if prediction.count(single_c) >= 2:
                return {
                    "result": "fail",
                    "message": "多物态平衡计算中未对不同物质/相态的比热容设独立变量",
                    "evidence": prediction
                }

    return {"result": "pass", "message": "变量使用符合逻辑或未发现明显建模错误", "evidence": ""}

# rule_id=exp_66634bc2269c39ec | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Phase Transitions and Latent Heat
def check_exp_66634bc2269c39ec_3758f0d54875(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = str(sample.get('prediction', ''))

    # 匹配题目末尾常见的括号数字，如 (27) 或 (15)
    pattern = re.compile(r'\((\d+)\)\s*$')
    match = pattern.search(question.strip())

    if not match:
        return {"result": "pass", "message": "未在题目末尾发现括号数字序号", "evidence": ""}

    serial_number = match.group(1)
    # 如果预测值完全等于括号内的序号，且该序号看起来像题号（通常较小或特定格式）
