    if prediction.strip() == serial_number:
        return {
            "result": "fail",
            "message": "预测值与题目末尾的题号或分值序号一致，疑似逻辑回填错误",
            "evidence": match.group(0)
        }

    return {"result": "pass", "message": "预测值与题号不冲突", "evidence": match.group(0)}

