# rule_id=exp_e8df1df814984f8a | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Phase Transitions and Latent Heat
def check_exp_e8df1df814984f8a_cb10b940f66d(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    if not prediction:
        return {'result': 'inconclusive', 'message': '预测内容为空', 'evidence': ''}

    # 查找涉及“年”到“秒”转换的模式，例如 365*24*3600 或 3.1536e7
    year_keywords = ['year', '每年', 'per year', '1 year']
    sec_keywords = ['3.1536', '31536000', '3.15', '3.16']

    has_year = any(kw in prediction.lower() for kw in year_keywords)
    has_sec_val = any(kw in prediction for kw in sec_keywords)

    # 如果提到了年，但转换数值明显错误（例如只用了3600或86400而没乘天数）
    # 匹配常见的错误转换：1 year = 86400 s 或 1 year = 3600 s
    wrong_patterns = [
        r'1\s*year\s*=\s*86400',
        r'1\s*year\s*=\s*3600',
        r'365\s*\*\s*3600'  # 漏了24小时
    ]

    for pattern in wrong_patterns:
        match = re.search(pattern, prediction, re.IGNORECASE)
        if match:
            return {
                'result': 'fail',
                'message': '时间单位转换错误：年转换为秒时计算逻辑不完整或数值错误',
                'evidence': match.group(0)
            }

    # 检查是否正确使用了 3.1536e7 或类似的完整转换
    correct_patterns = [
        r'3\.1536\s*[x*·]?\s*10\^?7',
        r'31536000',
        r'365\s*\*\s*24\s*\*\s*3600'
    ]

    for pattern in correct_patterns:
        match = re.search(pattern, prediction)
        if match:
            return {
                'result': 'pass',
                'message': '检测到正确的时间单位转换数值',
                'evidence': match.group(0)
            }

    if has_year and not has_sec_val:
        # 提到了年但没看到转换数值，且上下文涉及秒的计算时，可能存在隐患，但此处保守返回 inconclusive
        return {'result': 'inconclusive', 'message': '涉及年单位但未发现明确的秒转换数值', 'evidence': ''}

    return {'result': 'inconclusive', 'message': '未触发时间单位转换检查逻辑', 'evidence': ''}

# rule_id=exp_2858c336c9257acc | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Second Law and Entropy
def check_exp_2858c336c9257acc_1f7d91b026f0(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 触发条件：题目涉及恒温热库/热浴
    trigger_keywords = ['恒温热库', '热浴', 'Heat Reservoir', 'Heat Bath', 'T_bath']
    is_triggered = any(kw in question or kw in prediction for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到恒温热库相关场景", "evidence": ""}

    # 检查逻辑：是否使用了正确的熵变公式 Delta S = -Q/T 或 Delta S = -(Delta U + W)/T
    # 错误逻辑通常是试图对热库进行路径积分或忽略了能量守恒关系
    correct_patterns = [
        r"\\Delta S_{?bath}?.*=.*-?Q.*[/\\\\]T",
        r"\\Delta S.*=.*-.*\\Delta U.*[/\\\\]T",
        r"\\Delta S.*=.*-.*\\(.*?\\+.*?\\).*[/\\\\]T"
    ]

    # 寻找预测中是否包含熵变计算步骤
    has_entropy_calc = "Delta S" in prediction or "\\Delta S" in prediction or "熵变" in prediction
    if not has_entropy_calc:
        return {"result": "inconclusive", "message": "预测中未显式包含熵变计算步骤", "evidence": ""}

    # 检查是否符合简化律公式
    match_correct = any(re.search(p, prediction, re.IGNORECASE) for p in correct_patterns)

    # 检查是否存在错误倾向：对热库进行积分 (int dQ/T)
    wrong_pattern = r"\\int.*dQ.*/.*T"
    match_wrong = re.search(wrong_pattern, prediction)

    if match_correct:
        return {"result": "pass", "message": "正确使用了恒温热库熵变简化公式", "evidence": "命中正确公式模式"}
    elif match_wrong:
        return {"result": "fail", "message": "错误地对恒温热库使用了路径积分，应直接使用能量守恒简化公式", "evidence": str(match_wrong.group())}
    else:
        return {"result": "inconclusive", "message": "无法确定熵变计算逻辑是否符合简化律", "evidence": ""}

# rule_id=exp_2cfa70362ef366a3 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Second Law and Entropy
def check_exp_2cfa70362ef366a3_9a6460f820fb(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    context = sample.get('context', '')
    text = (prediction + ' ' + context).lower()

    # 寻找温度数值 T_A, T_B
    temps = re.findall(r'(\d+(?:\.\d+)?)\s*[kK]', text)
    if len(set(temps)) < 2:
        return {"result": "inconclusive", "message": "未识别到两个不同的初始温度", "evidence": ""}

    t1, t2 = float(temps[0]), float(temps[1])
    arithmetic_mean = (t1 + t2) / 2.0
    geometric_mean = (t1 * t2) ** 0.5

    # 检查逻辑：热机/最大功 -> 几何平均；直接接触 -> 算术平均
    is_heat_engine = any(kw in text for kw in ['heat engine', 'maximum work', 'max work', '热机', '最大功'])
    is_direct_contact = any(kw in text for kw in ['direct contact', 'thermal contact', '直接接触', '热接触'])

    # 提取预测中的平衡温度数值
    final_temp_match = re.search(r'(?:final|equilibrium|balance|平衡|最终).*?(\d+(?:\.\d+)?)', text)
    if not final_temp_match:
        return {"result": "inconclusive", "message": "未找到平衡温度数值", "evidence": ""}

    final_t = float(final_temp_match.group(1))

    if is_heat_engine and not is_direct_contact:
        if abs(final_t - arithmetic_mean) < abs(final_t - geometric_mean) * 0.5:
            return {"result": "fail", "message": "热机输出最大功时平衡温度应为几何平均而非算术平均", "evidence": final_temp_match.group(0)}
    elif is_direct_contact and not is_heat_engine:
        if abs(final_t - geometric_mean) < abs(final_t - arithmetic_mean) * 0.5:
            return {"result": "fail", "message": "直接热接触平衡温度应为算术平均而非几何平均", "evidence": final_temp_match.group(0)}

    return {"result": "pass", "message": "逻辑校验通过或未触发冲突条件", "evidence": ""}

# rule_id=exp_ce7eed588405c92b | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Second Law and Entropy
def check_exp_ce7eed588405c92b_554f172d9639(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    trigger_keywords = ['最大功', '提取最大能量', '有限热容', '变温热源']
    is_triggered = any(kw in question or kw in prediction for kw in trigger_keywords)
    if not is_triggered:
        return {"result": "inconclusive", "message": "未触发最大功相关关键词", "evidence": ""}

    # 检查是否错误地使用了算术平均值 (T1+T2)/2 而非几何平均值 sqrt(T1*T2)
    # 寻找温度数值，假设题目给出两个初始温度 T1, T2
    temps = re.findall(r'(\d+(?:\.\d+)?)\s*[Kk]', question)
    if len(temps) >= 2:
        t1, t2 = float(temps[0]), float(temps[1])
        arithmetic_mean = (t1 + t2) / 2
        geometric_mean = (t1 * t2) ** 0.5

        # 如果预测中出现了算术平均值且未提及熵增为零或几何平均
        if str(round(arithmetic_mean, 1)) in prediction or str(int(arithmetic_mean)) in prediction:
            if 'sqrt' not in prediction.lower() and '几何平均' not in prediction and str(round(geometric_mean, 1)) not in prediction:
                return {
                    "result": "fail",
                    "message": "错误地使用了算术平均值计算终温，最大功要求全系统熵增为零，终温应为几何平均值。",
                    "evidence": f"T1={t1}, T2={t2}, 预测中可能误用了 {arithmetic_mean}"
                }

    # 检查逻辑描述
    entropy_logic = ['熵增为零', '可逆', 'delta S = 0', 'dS = 0', '积分']
    has_entropy_logic = any(logic in prediction.lower() for logic in entropy_logic)

    if '能量守恒' in prediction and not has_entropy_logic and '最大' in prediction:
         return {
            "result": "fail",
            "message": "仅提及能量守恒不足以确定最大功，必须满足熵增为零。",
            "evidence": "预测中缺少熵平衡逻辑"
        }

    return {"result": "pass", "message": "逻辑符合热力学第二定律约束", "evidence": ""}

# rule_id=exp_eaf8e9258cd6f0b2 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Second Law and Entropy
def check_exp_eaf8e9258cd6f0b2_06ea0b03aa8a(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 触发条件检查：是否存在绝热壁、活塞、多气室等关键词
    trigger_keywords = ['绝热', '活塞', '气室', '隔板']
    is_triggered = any(kw in question for kw in trigger_keywords) or any(kw in prediction for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到绝热联动系统相关背景", "evidence": ""}

    # 检查逻辑：是否体现了 Q = ΔU1 + ΔU2 或 能量守恒的整体建模
    # 匹配模式：Q=dU1+dU2, Q=deltaU1+deltaU2, 或者文字描述“内能变化之和”
    patterns = [
        r'Q\s*=\s*\\?delta\s*U_?1\s*\+\s*\\?delta\s*U_?2',
        r'Q\s*=\s*\\Delta\s*U_?1\s*\+\s*\\Delta\s*U_?2',
        r'Q\s*=\s*\\Delta\s*U_\\text\{总\}',
        r'内能(变化|增量)之和',
        r'\\Delta\s*U_1\s*\+\s*\\Delta\s*U_2\s*=\s*Q'
    ]

    found_pattern = None
    for p in patterns:
        match = re.search(p, prediction, re.IGNORECASE)
        if match:
            found_pattern = match.group(0)
            break

    if found_pattern:
        return {
            "result": "pass",
            "message": "正确使用了整体能量守恒建模逻辑",
            "evidence": found_pattern
        }
    else:
        # 如果提到了绝热和热量，但没有看到整体求和公式，可能陷入了复杂的路径积分
        if 'Q' in prediction and ('W' in prediction or 'P' in prediction):
            return {
                "result": "fail",
                "message": "未能利用整体能量守恒逻辑，可能陷入了复杂的路径积分",
                "evidence": ""
            }

    return {"result": "inconclusive", "message": "无法确定是否使用了整体建模逻辑", "evidence": ""}

# rule_id=exp_17582a51d85b3657 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Specific Heat and Heat Capacities
def check_exp_17582a51d85b3657_7963fd118c47(sample: dict) -> dict:

    text = (sample.get('prediction', '') + ' ' + sample.get('answer', '')).lower()

    # 识别非线性多原子分子关键词
    nonlinear_molecules = ['h2o', 'ch4', '水蒸气', '甲烷', '非线性']
    is_target = any(m in text for m in nonlinear_molecules)

    if not is_target:
        return {"result": "inconclusive", "message": "未检测到非线性多原子分子相关描述", "evidence": ""}

    # 检查自由度 i 的取值
    # 匹配 i=5, i=6, 自由度为5, 自由度为6 等模式
    i_val_match = re.search(r'(?:i|自由度)\s*[=是]\s*(\d)', text)
    cvm_match = re.search(r'c_?v,?m?\s*[=是]\s*([\d\.]+)r', text)

    if i_val_match:
        i_val = int(i_val_match.group(1))
        if i_val == 5:
            return {"result": "fail", "message": "非线性多原子分子自由度应为6而非5", "evidence": i_val_match.group(0)}
        elif i_val == 6:
            return {"result": "pass", "message": "自由度校验正确", "evidence": i_val_match.group(0)}

    if cvm_match:
        cvm_val = float(cvm_match.group(1))
        if abs(cvm_val - 2.5) < 0.1:
            return {"result": "fail", "message": "热容计算错误，使用了双原子分子的2.5R而非3R", "evidence": cvm_match.group(0)}
        elif abs(cvm_val - 3.0) < 0.1:
            return {"result": "pass", "message": "热容计算正确", "evidence": cvm_match.group(0)}

    return {"result": "inconclusive", "message": "无法从文本中提取明确的自由度或热容数值", "evidence": ""}

# rule_id=exp_36289d492748e881 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Specific Heat and Heat Capacities
def check_exp_36289d492748e881_5acb54f8175f(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 定义匹配加权平均公式的模式，考虑 LaTeX 格式和普通文本格式
    # 核心逻辑：分子是 n_i * C_V 的求和，分母是 n_i 的求和
    patterns = [
        r'\\sum\\s*n_i\\s*C_{V,i}\\s*/\\s*\\sum\\s*n_i',
        r'\\frac{\\sum\\s*n_i\\s*C_{V,i}}{\\sum\\s*n_i}',
        r'\\sum\\s*n_i\\s*C_v\\s*/\\s*\\sum\\s*n_i',
        r'\\frac{\\sum\\s*n_i\\s*C_v}{\\sum\\s*n_i}',
        r'\(n1\\*C1\\s*\+\\s*n2\\*C2\)\\s*/\\s*\(n1\\s*\+\\s*n2\)'
    ]

    # 检查是否涉及混合气体热容计算
    keywords = ['混合气体', '热容', 'C_V', 'C_{V,mix}', 'mixture', 'heat capacity']
    is_relevant = any(kw in prediction or kw in sample.get('question', '') for kw in keywords)

    if not is_relevant:
        return {"result": "inconclusive", "message": "未检测到混合气体热容相关计算场景", "evidence": ""}

    # 检查是否使用了错误的权重（如质量权重 m_i 而非摩尔权重 n_i）
    wrong_patterns = [
        r'\\sum\\s*m_i\\s*C_{V,i}\\s*/\\s*\\sum\\s*m_i',
        r'\\frac{\\sum\\s*m_i\\s*C_{V,i}}{\\sum\\s*m_i}'
    ]

    for wp in wrong_patterns:
        if re.search(wp, prediction, re.IGNORECASE):
            return {"result": "fail", "message": "错误地使用了质量权重而非摩尔权重进行平均", "evidence": re.search(wp, prediction).group()}

    for p in patterns:
        if re.search(p, prediction, re.IGNORECASE):
            return {"result": "pass", "message": "正确使用了摩尔数加权平均公式", "evidence": re.search(p, prediction).group()}

    return {"result": "inconclusive", "message": "无法确定是否使用了正确的加权平均公式", "evidence": ""}

# rule_id=exp_7cf635ae9630f852 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Specific Heat and Heat Capacities
def check_exp_7cf635ae9630f852_c7e51aa89850(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    # 尝试匹配 Q, a, b, T1, T2 的数值或表达式
    # 寻找类似 Q = (a + b*(T1+T2)/2) * (T2-T1) 的结构
    # 由于是经验规则检查，主要检查预测文本中是否提到了平均热容或正确的积分形式

    # 提取数值的简单正则
    def get_val(pattern, text):
        match = re.search(pattern, text)
        return match.group(1) if match else None

    # 检查是否包含线性热容特征
    has_linear_c = 'a+bT' in prediction.replace(' ', '') or 'C=' in prediction
    if not has_linear_c and '热容' not in prediction:
        return {"result": "inconclusive", "message": "未检测到线性热容相关描述", "evidence": ""}

    # 检查逻辑：Q 是否等于平均热容乘以温差
    # 搜索关键词：(C1+C2)/2, (T1+T2)/2, 平均热容
    keywords = ['(C1+C2)/2', '(T1+T2)/2', '平均热容', 'C_avg', 'a+b*(T1+T2)/2']
    found_logic = any(kw in prediction.replace(' ', '') or kw in prediction for kw in keywords)

    # 检查积分结果形式 Q = a(T2-T1) + 0.5*b(T2^2-T1^2)
    integral_form = '0.5*b' in prediction.replace(' ', '') or '1/2*b' in prediction.replace(' ', '')

    if found_logic or integral_form:
        # 如果逻辑匹配，返回 pass
        return {
            "result": "pass",
            "message": "积分逻辑符合线性热容热量计算公式",
            "evidence": prediction[:100]
        }

    # 如果提到了计算但公式明显错误（例如直接用 C1*deltaT）
    if 'Q=' in prediction.replace(' ', '') and 'T2-T1' in prediction.replace(' ', ''):
        return {
            "result": "fail",
            "message": "热量计算未采用平均热容或正确的积分形式",
            "evidence": prediction[:100]
        }

    return {"result": "inconclusive", "message": "无法确定计算逻辑的准确性", "evidence": ""}

# rule_id=exp_b7293e38a7630ba8 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Specific Heat and Heat Capacities
def check_exp_b7293e38a7630ba8_a17e6872ab1d(sample: dict) -> dict:

    prediction = sample.get('prediction', '')
    question = sample.get('question', '')

    # 触发词检查：理想气体、混合物、摩尔热容/摩尔质量/摩尔焓
    trigger_keywords = ['理想气体', '混合', '摩尔', '热容', '质量', '焓']
    is_triggered = any(kw in question for kw in trigger_keywords) or any(kw in prediction for kw in trigger_keywords)

    if not is_triggered:
        return {"result": "inconclusive", "message": "未检测到理想气体混合物强度性质计算场景", "evidence": ""}

    # 检查逻辑：寻找加权平均公式模式 (n1*X1 + n2*X2) / (n1 + n2)
    # 匹配模式如 (n1*C1 + n2*C2)/(n1+n2) 或 (n1*M1 + n2*M2)/n_total
    patterns = [
        r'\(n1\*\w+1\s*\+\s*n2\*\w+2\)\s*/\s*\(n1\s*\+\s*n2\)',
        r'\sum\s*n_i\s*\*\s*\w+_i\s*/\s*\sum\s*n_i',
        r'\(n_A\*\w+_A\s*\+\s*n_B\*\w+_B\)\s*/\s*\(n_A\s*\+\s*n_B\)',
        r'x1\*\w+1\s*\+\s*x2\*\w+2' # 摩尔分数形式
    ]

    found_pattern = False
    for p in patterns:
        if re.search(p, prediction, re.IGNORECASE):
            found_pattern = True
            break

    # 检查文字描述：加权平均、总量除以总物质的量
    text_indicators = ['加权平均', '总物质的量', '除以总', '摩尔分数']
    found_text = any(ti in prediction for ti in text_indicators)

    if found_pattern or found_text:
        return {"result": "pass", "message": "采用了正确的摩尔加权平均计算混合物强度性质", "evidence": "命中加权平均逻辑描述或公式"}

    # 如果明确在计算混合物性质但没有体现加权平均逻辑，则可能存在概念错误
    if '混合' in prediction and ('=' in prediction or '计算' in prediction):
        return {"result": "fail", "message": "未发现正确的摩尔加权平均计算逻辑，可能直接相加或公式错误", "evidence": prediction[:100]}

    return {"result": "inconclusive", "message": "无法确定是否正确应用了混合物强度性质计算规则", "evidence": ""}

# rule_id=exp_18efe81dfcd6a9b3 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_exp_18efe81dfcd6a9b3_dca8fe626508(sample: dict) -> dict:

    text = (sample.get('prediction', '') + ' ' + sample.get('answer', '')).lower()
    question = sample.get('question', '').lower()

    is_adiabatic = 'adiabatic' in question or '绝热' in question
    is_sphere = 'sphere' in question or '球' in question or 'radius' in question or '半径' in question

    if not (is_adiabatic and is_sphere):
        return {"result": "inconclusive", "message": "未识别到球体绝热过程场景", "evidence": ""}

    # 检查是否提到了 T 和 r 的关系
    has_t = 't' in text or '温度' in text
    has_r = 'r' in text or '半径' in text
    if not (has_t and has_r):
        return {"result": "inconclusive", "message": "未发现温度与半径的关系描述", "evidence": ""}

    # 匹配 T ∝ r^(-3(gamma-1)) 或 T * r^(3(gamma-1)) = C
    # 允许的模式：r^(-3(gamma-1)), r^(3-3gamma), r^(3gamma-3) 在分母等
    patterns = [
        r'r\^\s*\(\s*-\s*3\s*\*?\s*\(\s*gamma\s*-\s*1\s*\)\s*\)',
        r'r\^\s*\(\s*3\s*-\s*3\s*gamma\s*\)',
        r't\s*\*\s*r\^\s*\(\s*3\s*\*?\s*\(\s*gamma\s*-\s*1\s*\)\s*\)',
        r't\s*\*\s*r\^\s*\(\s*3\s*gamma\s*-\s*3\s*\)',
        r't\s*proportional\s*to\s*r\^\s*\(\s*3\s*-\s*3\s*gamma\s*\)',
        r't\s*\\propto\s*r\^\{\s*3\s*\(\s*1-gamma\s*\)\}'
    ]

    found_correct = False
    evidence = ""
    for p in patterns:
        match = re.search(p, text.replace(' ', ''))
        if match:
            found_correct = True
            evidence = match.group(0)
            break

    # 检查错误模式：例如 T ∝ r^(gamma-1) 忽略了体积V=r^3的关系
    error_patterns = [
        r't\s*\*\s*r\^\s*\(\s*gamma\s*-\s*1\s*\)',
        r't\s*\\propto\s*r\^\{\s*gamma-1\}'
    ]

    for ep in error_patterns:
        if re.search(ep, text.replace(' ', '')):
            return {"result": "fail", "message": "未考虑球体体积与半径的三次方关系，指数应为3(gamma-1)", "evidence": ep}

    if found_correct:
        return {"result": "pass", "message": "正确应用了球体绝热过程的幂律转换", "evidence": evidence}

    return {"result": "inconclusive", "message": "无法确定幂律转换的准确性", "evidence": ""}

# rule_id=exp_8c7f11a4f8dae4ff | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_exp_8c7f11a4f8dae4ff_b70fa3895ae7(sample: dict) -> dict:

    text = sample.get('prediction', '') + ' ' + sample.get('answer', '')
    if not ('adiabatic' in text.lower() or '绝热' in text):
        return {'result': 'inconclusive', 'message': '未识别到绝热过程关键词', 'evidence': ''}

    # 匹配 dT/T = ((gamma-1)/gamma) * dp/p 的变体
    # 寻找类似 dT/T, dp/p, (gamma-1)/gamma 的表达式
    dt_t_pattern = r'd[T|t]/[T|t]'
    dp_p_pattern = r'd[P|p]/[P|p]'
    gamma_term_pattern = r'\(?\s*(\\gamma|gamma)\s*-\s*1\s*\)?\s*/\s*(\\gamma|gamma)'

    has_dt_t = re.search(dt_t_pattern, text)
    has_dp_p = re.search(dp_p_pattern, text)
    gamma_match = re.search(gamma_term_pattern, text)

    if has_dt_t and has_dp_p:
        # 检查系数逻辑：dT/T = [(gamma-1)/gamma] * dp/p
        # 如果文本中出现了 dT/T 和 dp/p，但系数不匹配 (gamma-1)/gamma，则报错
        if gamma_match:
            # 简单检查等式结构，寻找 dT/T 和 dp/p 之间的系数关系
            # 构造一个粗略的正则来寻找等号连接
            relation_pattern = r'd[T|t]/[T|t]\s*=\s*([^=]*?)d[P|p]/[P|p]'
            rel_match = re.search(relation_pattern, text)
            if rel_match:
                coeff_part = rel_match.group(1)
                if 'gamma' in coeff_part or '\\gamma' in coeff_part:
                    if '-' in coeff_part and '/' in coeff_part:
                        return {'result': 'pass', 'message': '绝热过程微分关系校验通过', 'evidence': rel_match.group(0)}
                    else:
                        return {'result': 'fail', 'message': '绝热过程微分关系系数错误，应为(gamma-1)/gamma', 'evidence': rel_match.group(0)}
        return {'result': 'pass', 'message': '检测到微分关系，初步符合物理逻辑', 'evidence': has_dt_t.group(0)}

    return {'result': 'inconclusive', 'message': '未找到完整的微分关系表达式', 'evidence': ''}

# rule_id=exp_ac94e83b7ba234c6 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_exp_ac94e83b7ba234c6_ccd454c57534(sample: dict) -> dict:

    text = (sample.get('prediction', '') + ' ' + sample.get('answer', '')).lower()

    # 检查是否涉及喷管、喷嘴或通道流动
    keywords = ['nozzle', 'channel', 'diffuser', '喷管', '喷嘴', '通道', '流道']
    is_relevant = any(kw in text for kw in keywords)
    if not is_relevant:
        return {"result": "inconclusive", "message": "未检测到喷管或通道流动相关关键词", "evidence": ""}

    # 检查是否同时提到焓不变 (h1=h2) 和 速度/动能变化
    # 匹配焓不变的表述
    enthalpy_const_patterns = [
        r'h_1\s*=\s*h_2',
        r'h1\s*=\s*h2',
        r'enthalpy\s+remains\s+constant',
        r'焓值不变',
        r'等焓'
    ]

    # 匹配速度增加或动能增加的表述
    velocity_change_patterns = [
        r'v_2\s*>\s*v_1',
        r'v2\s*>\s*v1',
        r'velocity\s+increases',
        r'速度增加',
        r'动能增加',
        r'kinetic\s+energy\s+increases'
    ]

    has_h_const = any(re.search(p, text) for p in enthalpy_const_patterns)
    has_v_increase = any(re.search(p, text) for p in velocity_change_patterns)

    if has_h_const and has_v_increase:
        # 命中逻辑错误：在动能增加时假设焓不变违反了 SFEE (h1 + v1^2/2 = h2 + v2^2/2)
        evidence_h = [re.search(p, text).group() for p in enthalpy_const_patterns if re.search(p, text)][0]
        evidence_v = [re.search(p, text).group() for p in velocity_change_patterns if re.search(p, text)][0]
        return {
            "result": "fail",
            "message": "违反稳态稳流能量方程：动能增加时焓值不可能保持不变。",
            "evidence": f"{evidence_h} AND {evidence_v}"
        }

    # 检查是否正确应用了 SFEE 公式形式
    sfee_pattern = r'h_?1\s*\+\s*v_?1\^2/2\s*=\s*h_?2\s*\+\s*v_?2\^2/2'
    if re.search(sfee_pattern, text.replace(' ', '')):
        return {"result": "pass", "message": "正确引用了稳态稳流能量方程", "evidence": "h1 + v1^2/2 = h2 + v2^2/2"}

    return {"result": "inconclusive", "message": "未发现明显的能量守恒逻辑冲突或公式引用", "evidence": ""}

# rule_id=exp_ecd4b6df23948ece | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_exp_ecd4b6df23948ece_2e5c0cfac8c8(sample: dict) -> dict:

    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    trigger_keywords = ['reversible expansion', 'liquid', 'gaseous', 'adiabatic index']
    trigger_count = sum(1 for kw in trigger_keywords if kw.lower() in question.lower())

    if trigger_count < 2:
        return {"result": "inconclusive", "message": "未触发两相流绝热膨胀场景", "evidence": ""}

    # 检查是否错误使用了理想气体绝热方程 P*V^gamma
    wrong_pattern = re.compile(r'P\\s*V\\^\\s*[\\gamma|k|1\\.4]', re.IGNORECASE)
    # 检查是否包含等熵方程特征 (s = (1-x)sg + xsf 或类似形式)
    entropy_pattern = re.compile(r's_?[12]?\\s*=\\s*.*s_?[fg]', re.IGNORECASE)
    # 检查能量守恒/焓降公式
    energy_pattern = re.compile(r'\\Delta\\s*h|h_?1\\s*-\\s*h_?2|v\\^2\\s*/\\s*2', re.IGNORECASE)

    has_entropy = bool(entropy_pattern.search(prediction))
    has_energy = bool(energy_pattern.search(prediction))
    has_wrong_pv = bool(wrong_pattern.search(prediction))

    if has_entropy and has_energy:
        return {"result": "pass", "message": "正确建立了等熵方程与能量守恒模型", "evidence": "找到熵与焓相关公式"}
    elif has_wrong_pv:
        return {"result": "fail", "message": "错误地对两相流使用了理想气体P-V关系", "evidence": "检测到PV^gamma相关表达式"}
    else:
        return {"result": "inconclusive", "message": "无法确定建模逻辑是否符合要求", "evidence": ""}

# rule_id=exp_f7099f29ab935e03 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamics & Statistical Physics / Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_exp_f7099f29ab935e03_b3607f4bd708(sample: dict) -> dict:

    text = sample.get('prediction', '') + ' ' + sample.get('answer', '')
    # 匹配类似 d^2x/dt^2 = Ax 或 x'' = Ax 的模式
    # 重点寻找等号右侧的系数
    patterns = [
        r"d\^2[a-zA-Z]/dt\^2\s*=\s*([+-]?\d*\.?\d*)\s*[a-zA-Z]",
        r"[a-zA-Z]''\s*=\s*([+-]?\d*\.?\d*)\s*[a-zA-Z]",
        r"\\ddot\{[a-zA-Z]\}\s*=\s*([+-]?\d*\.?\d*)\s*[a-zA-Z]"
    ]

    found_positive = False
    evidence = ""

    for p in patterns:
        matches = re.finditer(p, text)
        for m in matches:
            coeff_str = m.group(1).strip()
            # 处理符号
            if coeff_str == "" or coeff_str == "+":
                val = 1.0
            elif coeff_str == "-":
                val = -1.0
            else:
                try:
                    val = float(coeff_str)
                except:
                    continue

            if val > 0:
                found_positive = True
                evidence = m.group(0)
                break
        if found_positive: break

    if found_positive:
        return {
            "result": "fail",
            "message": "简谐振动方程系数 A 应为负值以保证系统稳定振荡，检测到正值系数会导致系统发散。",
            "evidence": evidence
        }

    # 如果没找到明确的正值，但存在振动方程描述，保守返回 inconclusive 或 pass
    if "d^2" in text or "\\ddot" in text:
        return {
            "result": "pass",
            "message": "未检测到违反简谐振动正定性的系数。",
            "evidence": ""
        }

    return {
        "result": "inconclusive",
        "message": "未在文本中识别出明确的位移二阶微分方程。",
        "evidence": ""
    }

